@Test
public void testVerifyResourceName() {
    final String validName = "my-bucket.01";
    HddsClientUtils.verifyResourceName(validName);
    final String shortestValidName = StringUtils.repeat("a", OzoneConsts.OZONE_MIN_BUCKET_NAME_LENGTH);
    HddsClientUtils.verifyResourceName(shortestValidName);
    // various kinds of invalid names
    final String ipaddr = "192.68.1.1";
    final String dotDash = "not.-a-name";
    final String dashDot = "not-a-.name";
    final String dotDot = "not..a-name";
    final String upperCase = "notAname";
    final String endDot = "notaname.";
    final String startDot = ".notaname";
    final String unicodeCharacters = "ｚｚｚ";
    // Other tests cover the "too short" case.
    List<String> invalidNames = new ArrayList<>();
    invalidNames.add(ipaddr);
    invalidNames.add(dotDash);
    invalidNames.add(dashDot);
    invalidNames.add(dotDot);
    invalidNames.add(upperCase);
    invalidNames.add(endDot);
    invalidNames.add(startDot);
    invalidNames.add(unicodeCharacters);
    for (String name : invalidNames) {
        assertThrows(IllegalArgumentException.class, () -> HddsClientUtils.verifyResourceName(name), getInvalidNameMessage(name));
    }
}

@Test
public void testNameTooShort() {
    final String tooShort = StringUtils.repeat("a", OzoneConsts.OZONE_MIN_BUCKET_NAME_LENGTH - 1);
    doTestBadResourceNameLengthReported(tooShort, "too short");
}

@Test
public void testNameTooLong() {
    // Too long, but within the limit for logging (no truncation).
    final String tooLong = StringUtils.repeat("a", OzoneConsts.OZONE_MAX_BUCKET_NAME_LENGTH + 1);
    doTestBadResourceNameLengthReported(tooLong, "too long");
}

@Test
public void testNameTooLongCapped() {
    // Logging arbitrarily long names is a readability concern and possibly a
    // vulnerability. Report a prefix with a truncation marker instead if the
    // maximum length is exceeded by a large margin.
    final String exceedsLogLimit = "x" + StringUtils.repeat("a", HddsClientUtils.MAX_BUCKET_NAME_LENGTH_IN_LOG);
    final String truncationMarker = "...";
    Throwable thrown = assertThrows(IllegalArgumentException.class, () -> HddsClientUtils.verifyResourceName(exceedsLogLimit), getInvalidNameMessage(exceedsLogLimit));
    String message = thrown.getMessage();
    assertNotNull(message);
    String truncatedName = exceedsLogLimit.substring(0, HddsClientUtils.MAX_BUCKET_NAME_LENGTH_IN_LOG);
    String expectedInMessage = truncatedName + truncationMarker;
    assertThat(message).contains(expectedInMessage);
    assertThat(message).doesNotContain(exceedsLogLimit);
}

@Test
public void testInvalidCharactersNotReported() {
    // Names of illegal length may appear in logs through the exception
    // message. If they also contain invalid characters, they should not be
    // included verbatim. This is to avoid vulnerabilities like Log4Shell.
    final String tooShortInvalidChar = "$a";
    Throwable thrown = assertThrows(IllegalArgumentException.class, () -> HddsClientUtils.verifyResourceName(tooShortInvalidChar), getInvalidNameMessage(tooShortInvalidChar));
    String message = thrown.getMessage();
    assertNotNull(message);
    assertThat(message).doesNotContain(tooShortInvalidChar);
}

@Test
void testVerifyKeyName() throws IllegalArgumentException {
    List<String> invalidNames = new ArrayList<>();
    invalidNames.add("#");
    invalidNames.add("ab^cd");
    invalidNames.add("test|name~");
    invalidNames.add("~hi!ozone");
    invalidNames.add("test<string>");
    invalidNames.add("10%3=1");
    invalidNames.add("photo[0201]");
    invalidNames.add("square_right]");
    invalidNames.add("my\\file");
    invalidNames.add("for}");
    invalidNames.add("{curly-left");
    invalidNames.add("\"hi\"");
    invalidNames.add("\\\\~`");
    invalidNames.add("Code`");
    for (String name : invalidNames) {
        assertThrows(IllegalArgumentException.class, () -> HddsClientUtils.verifyKeyName(name), getInvalidNameMessage(name));
    }
    List<String> validNames = new ArrayList<>();
    validNames.add("123_123");
    validNames.add("abcd/abcd");
    validNames.add("test-name");
    validNames.add("hi!ozone");
    validNames.add("test(string)");
    validNames.add("10*3+1");
    validNames.add("photo'0201'");
    validNames.add("my.name");
    validNames.add("you&me");
    validNames.add("1=0");
    validNames.add("print;");
    validNames.add("3:5:2");
    validNames.add("a,b,c");
    validNames.add("my name is");
    validNames.add("xyz@mail");
    validNames.add("dollar$");
    for (String name : validNames) {
        HddsClientUtils.verifyKeyName(name);
        HddsClientUtils.verifyKeyName(name + OzoneConsts.FS_FILE_COPYING_TEMP_SUFFIX);
    }
}

@Test
void testContainsException() {
    Exception ex1 = new ConnectException();
    Exception ex2 = new IOException(ex1);
    Exception ex3 = new IllegalArgumentException(ex2);
    assertSame(ex1, HddsClientUtils.containsException(ex3, ConnectException.class));
    assertSame(ex2, HddsClientUtils.containsException(ex3, IOException.class));
    assertSame(ex3, HddsClientUtils.containsException(ex3, IllegalArgumentException.class));
    assertNull(HddsClientUtils.containsException(ex3, IllegalStateException.class));
}

@Test
public void testSeek() throws Exception {
    // Seek to position 0
    int pos = 0;
    seekAndVerify(pos);
    assertEquals(0, blockStream.getChunkIndex(), "ChunkIndex is incorrect");
    // Before BlockInputStream is initialized (initialization happens during
    // read operation), seek should update the BlockInputStream#blockPosition
    pos = CHUNK_SIZE;
    seekAndVerify(pos);
    assertEquals(0, blockStream.getChunkIndex(), "ChunkIndex is incorrect");
    assertEquals(pos, blockStream.getBlockPosition());
    // Initialize the BlockInputStream. After initialization, the chunkIndex
    // should be updated to correspond to the sought position.
    blockStream.initialize();
    assertEquals(1, blockStream.getChunkIndex(), "ChunkIndex is incorrect");
    pos = (CHUNK_SIZE * 4) + 5;
    seekAndVerify(pos);
    assertEquals(4, blockStream.getChunkIndex(), "ChunkIndex is incorrect");
    pos = blockSize + 10;
    int finalPos = pos;
    assertThrows(EOFException.class, () -> seekAndVerify(finalPos));
    // Seek to random positions between 0 and the block size.
    for (int i = 0; i < 10; i++) {
        pos = RandomUtils.secure().randomInt(0, blockSize);
        seekAndVerify(pos);
    }
}

@Test
public void testRead() throws Exception {
    // read 200 bytes of data starting from position 50. Chunk0 contains
    // indices 0 to 99, chunk1 from 100 to 199 and chunk3 from 200 to 299. So
    // the read should result in 3 ChunkInputStream reads
    seekAndVerify(50);
    byte[] b = new byte[200];
    int bytesRead = blockStream.read(b, 0, 200);
    assertEquals(200, bytesRead, "Expected to read 200 bytes");
    matchWithInputData(b, 50, 200);
    // The new position of the blockInputStream should be the last index read
    // + 1.
    assertEquals(250, blockStream.getPos());
    assertEquals(2, blockStream.getChunkIndex());
}

@Test
public void testReadWithByteBuffer() throws Exception {
    // read 200 bytes of data starting from position 50. Chunk0 contains
    // indices 0 to 99, chunk1 from 100 to 199 and chunk3 from 200 to 299. So
    // the read should result in 3 ChunkInputStream reads
    seekAndVerify(50);
    ByteBuffer buffer = ByteBuffer.allocate(200);
    blockStream.read(buffer);
    matchWithInputData(buffer.array(), 50, 200);
    // The new position of the blockInputStream should be the last index read
