    assertEquals(250, blockStream.getPos());
    assertEquals(2, blockStream.getChunkIndex());
}

@Test
public void testReadWithDirectByteBuffer() throws Exception {
    // read 200 bytes of data starting from position 50. Chunk0 contains
    // indices 0 to 99, chunk1 from 100 to 199 and chunk3 from 200 to 299. So
    // the read should result in 3 ChunkInputStream reads
    seekAndVerify(50);
    ByteBuffer buffer = ByteBuffer.allocateDirect(200);
    blockStream.read(buffer);
    for (int i = 50; i < 50 + 200; i++) {
        assertEquals(blockData[i], buffer.get(i - 50));
    }
    // The new position of the blockInputStream should be the last index read
    // + 1.
    assertEquals(250, blockStream.getPos());
    assertEquals(2, blockStream.getChunkIndex());
}

@Test
public void testSeekAndRead() throws Exception {
    // Seek to a position and read data
    seekAndVerify(50);
    byte[] b1 = new byte[100];
    int bytesRead1 = blockStream.read(b1, 0, 100);
    assertEquals(100, bytesRead1, "Expected to read 100 bytes");
    matchWithInputData(b1, 50, 100);
    // Next read should start from the position of the last read + 1 i.e. 100
    byte[] b2 = new byte[100];
    int bytesRead2 = blockStream.read(b2, 0, 100);
    assertEquals(100, bytesRead2, "Expected to read 100 bytes");
    matchWithInputData(b2, 150, 100);
}

@Test
public void testRefreshPipelineFunction() throws Exception {
    LogCapturer logCapturer = LogCapturer.captureLogs(BlockInputStream.class);
    GenericTestUtils.setLogLevel(BlockInputStream.class, Level.DEBUG);
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    AtomicBoolean isRefreshed = new AtomicBoolean();
    createChunkList(5);
    OzoneClientConfig clientConfig = conf.getObject(OzoneClientConfig.class);
    clientConfig.setChecksumVerify(false);
    try (BlockInputStream blockInputStreamWithRetry = new DummyBlockInputStreamWithRetry(blockID, blockSize, MockPipeline.createSingleNodePipeline(), null, null, chunks, chunkDataMap, isRefreshed, null, clientConfig)) {
        assertFalse(isRefreshed.get());
        seekAndVerify(50);
        byte[] b = new byte[200];
        int bytesRead = blockInputStreamWithRetry.read(b, 0, 200);
        assertEquals(200, bytesRead, "Expected to read 200 bytes");
        assertThat(logCapturer.getOutput()).contains("Retry read after");
        assertTrue(isRefreshed.get());
    }
}

@ParameterizedTest
@MethodSource("exceptionsTriggersRefresh")
void refreshesPipelineOnReadFailure(IOException ex) throws Exception {
    // GIVEN
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    BlockLocationInfo blockLocationInfo = mock(BlockLocationInfo.class);
    when(blockLocationInfo.getPipeline()).thenReturn(pipeline);
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    BlockLocationInfo newBlockLocationInfo = mock(BlockLocationInfo.class);
    testRefreshesPipelineOnReadFailure(ex, blockLocationInfo, id -> newBlockLocationInfo);
    when(newBlockLocationInfo.getPipeline()).thenReturn(newPipeline);
    testRefreshesPipelineOnReadFailure(ex, blockLocationInfo, id -> blockLocationInfo);
    when(newBlockLocationInfo.getPipeline()).thenReturn(null);
    testRefreshesPipelineOnReadFailure(ex, blockLocationInfo, id -> newBlockLocationInfo);
}

@ParameterizedTest
@MethodSource("exceptionsNotTriggerRefresh")
public void testReadNotRetriedOnOtherException(IOException ex) throws Exception {
    // GIVEN
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    final int len = ThreadLocalRandom.current().nextInt(100, 300);
    final ChunkInputStream stream = throwingChunkInputStream(ex, len, false);
    try (BlockInputStream subject = createSubject(blockID, pipeline, stream)) {
        subject.initialize();
        // WHEN
        assertThrows(ex.getClass(), () -> {
            byte[] buffer = new byte[len];
            int bytesRead = subject.read(buffer, 0, len);
            // This line should never be reached due to the exception
            assertEquals(len, bytesRead);
        });
        // THEN
        verify(refreshFunction, never()).apply(blockID);
    }
}

@ParameterizedTest
@MethodSource("exceptionsTriggersRefresh")
public void testRefreshOnReadFailureAfterUnbuffer(IOException ex) throws Exception {
    // GIVEN
    BlockID blockID = new BlockID(new ContainerBlockID(1, 1));
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    BlockLocationInfo blockLocationInfo = mock(BlockLocationInfo.class);
    when(clientFactory.acquireClientForReadData(pipeline)).thenReturn(client);
    final int len = 200;
    final ChunkInputStream stream = throwingChunkInputStream(ex, len, true);
    when(refreshFunction.apply(blockID)).thenReturn(blockLocationInfo);
    when(blockLocationInfo.getPipeline()).thenReturn(newPipeline);
    OzoneClientConfig clientConfig = conf.getObject(OzoneClientConfig.class);
    clientConfig.setChecksumVerify(false);
    BlockInputStream subject = new BlockInputStream(new BlockLocationInfo(new BlockLocationInfo.Builder().setBlockID(blockID).setLength(blockSize)), pipeline, null, clientFactory, refreshFunction, clientConfig) {

        @Override
        protected ChunkInputStream createChunkInputStream(ChunkInfo chunkInfo) {
            return stream;
        }

        @Override
        protected ContainerProtos.BlockData getBlockDataUsingClient() throws IOException {
            BlockID blockID = getBlockID();
            ContainerProtos.DatanodeBlockID datanodeBlockID = blockID.getDatanodeBlockIDProtobuf();
            return ContainerProtos.BlockData.newBuilder().addAllChunks(chunks).setBlockID(datanodeBlockID).build();
        }
    };
    try {
        subject.initialize();
        subject.unbuffer();
        // WHEN
        byte[] b = new byte[len];
        int bytesRead = subject.read(b, 0, len);
        // THEN
        assertEquals(len, bytesRead);
        verify(refreshFunction).apply(blockID);
        verify(clientFactory).acquireClientForReadData(pipeline);
        verify(clientFactory).releaseClientForReadData(client, false);
    } finally {
        subject.close();
    }
}

@ParameterizedTest
@ValueSource(ints = { 1, 1024, 1024 * 1024 })
void test(final int writeSize) throws IOException {
    assertEquals(0, DATA_SIZE % writeSize);
    final BufferPool bufferPool = new BufferPool(4 * 1024 * 1024, 32 / 4);
    for (int block = 0; block < 10; block++) {
        try (BlockOutputStream outputStream = createBlockOutputStream(bufferPool)) {
            for (int i = 0; i < DATA_SIZE / writeSize; i++) {
                if (writeSize > 1) {
                    outputStream.write(DATA, i * writeSize, writeSize);
                } else {
                    outputStream.write(DATA[i]);
                }
            }
        }
    }
}

/**
 * Tests an EC offline reconstruction scenario in which none of the ChunkInfo in an EC stripe have stripeChecksum.
 * Such ChunkInfo will exist for any EC data that was written in a version in which the ChunkInfo protobuf message did
 * not have the stripeChecksum field. Here, we assert that executePutBlock during reconstruction does not throw an
 * exception because of missing stripeChecksum. This essentially tests compatibility between an Ozone version that
 * did not have stripeChecksum and a version that has stripeChecksum.
 */
@Test
public void testMissingStripeChecksumDoesNotMakeExecutePutBlockFailDuringECReconstruction() throws IOException {
    // setup some parameters required for creating ECBlockOutputStream
    OzoneClientConfig config = new OzoneClientConfig();
    ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
    BlockID blockID = new BlockID(1, 1);
    DatanodeDetails datanodeDetails = MockDatanodeDetails.randomDatanodeDetails();
    Pipeline pipeline = Pipeline.newBuilder().setId(datanodeDetails.getID()).setReplicationConfig(replicationConfig).setNodes(ImmutableList.of(datanodeDetails)).setState(Pipeline.PipelineState.CLOSED).// we'll executePutBlock for the parity index 5 because stripeChecksum is written to either the first or the
    // parity indexes
    setReplicaIndexes(ImmutableMap.of(datanodeDetails, 5)).build();
    BlockLocationInfo locationInfo = new BlockLocationInfo.Builder().setBlockID(blockID).setOffset(1).setLength(10).setPipeline(pipeline).build();
    /*
    The array of BlockData contains metadata about blocks and their chunks, and is read in executePutBlock. In
    this test, we deliberately don't write stripeChecksum to any chunk. The expectation is that executePutBlock
    should not throw an exception because of missing stripeChecksum.
     */
    BlockData[] blockData = createBlockDataWithoutStripeChecksum(blockID, replicationConfig);
    try (ECBlockOutputStream ecBlockOutputStream = createECBlockOutputStream(config, replicationConfig, blockID, pipeline)) {
        Assertions.assertDoesNotThrow(() -> ecBlockOutputStream.executePutBlock(true, true, locationInfo.getLength(), blockData));
    }
}

