    validate(ReplicationConfig.adjustReplication(replicationConfig, (short) 1, conf), org.apache.hadoop.hdds.client.ReplicationType.valueOf(type), org.apache.hadoop.hdds.client.ReplicationFactor.ONE, replicationConfigClass);
