@Test
public void testStateMachineStates() throws InvalidStateTransitionException {
    Set<STATES> finals = new HashSet<>();
    finals.add(FINAL);
    StateMachine<STATES, EVENTS> stateMachine = new StateMachine<>(INIT, finals);
    stateMachine.addTransition(INIT, CREATING, EVENTS.ALLOCATE);
    stateMachine.addTransition(CREATING, OPERATIONAL, EVENTS.CREATE);
    stateMachine.addTransition(OPERATIONAL, OPERATIONAL, EVENTS.UPDATE);
    stateMachine.addTransition(OPERATIONAL, CLEANUP, EVENTS.DELETE);
    stateMachine.addTransition(OPERATIONAL, CLOSED, EVENTS.CLOSE);
    stateMachine.addTransition(CREATING, CLEANUP, EVENTS.TIMEOUT);
    // Initial and Final states
    assertEquals(INIT, stateMachine.getInitialState(), "Initial State");
    assertTrue(SetUtils.isEqualSet(finals, stateMachine.getFinalStates()), "Final States");
    // Valid state transitions
    assertEquals(OPERATIONAL, stateMachine.getNextState(CREATING, EVENTS.CREATE), "STATE should be OPERATIONAL after being created");
    assertEquals(OPERATIONAL, stateMachine.getNextState(OPERATIONAL, EVENTS.UPDATE), "STATE should be OPERATIONAL after being updated");
    assertEquals(CLEANUP, stateMachine.getNextState(OPERATIONAL, EVENTS.DELETE), "STATE should be CLEANUP after being deleted");
    assertEquals(CLEANUP, stateMachine.getNextState(CREATING, EVENTS.TIMEOUT), "STATE should be CLEANUP after being timeout");
    assertEquals(CLOSED, stateMachine.getNextState(OPERATIONAL, EVENTS.CLOSE), "STATE should be CLOSED after being closed");
    // Negative cases: invalid transition
    assertThrowsExactly(InvalidStateTransitionException.class, () -> stateMachine.getNextState(OPERATIONAL, EVENTS.CREATE), "Invalid event");
    assertThrowsExactly(InvalidStateTransitionException.class, () -> stateMachine.getNextState(CREATING, EVENTS.CLOSE), "Invalid event");
}

