@Test
public void testValidateToken() throws Exception {
    try {
        final OzoneConfiguration conf = new OzoneConfiguration();
        conf.set(HDDS_DATANODE_DIR_KEY, testDir.getPath());
        conf.set(OzoneConfigKeys.OZONE_METADATA_DIRS, testDir.getPath());
        final DatanodeDetails dd = randomDatanodeDetails();
        final UUID scmId = UUID.randomUUID();
        final AtomicBoolean verified = new AtomicBoolean();
        final TokenVerifier tokenVerifier = new TokenVerifier() {

            private void verify() {
                final boolean previous = verified.getAndSet(true);
                assertFalse(previous);
            }

            @Override
            public void verify(ContainerCommandRequestProtoOrBuilder cmd, String encodedToken) {
                verify();
            }

            @Override
            public void verify(Token<?> token, ContainerCommandRequestProtoOrBuilder cmd) {
                verify();
            }
        };
        final ContainerCommandRequestProto request = getWriteChunkRequest(dd.getUuidString(), 1L, 1L);
        final HddsDispatcher dispatcher = createDispatcher(dd, scmId, conf, tokenVerifier);
        final DispatcherContext[] notVerify = { newContext(Op.WRITE_STATE_MACHINE_DATA, WriteChunkStage.WRITE_DATA), newContext(Op.READ_STATE_MACHINE_DATA), newContext(Op.APPLY_TRANSACTION), newContext(Op.STREAM_LINK, WriteChunkStage.COMMIT_DATA) };
        for (DispatcherContext context : notVerify) {
            LOG.info("notVerify {}", context);
            assertFalse(verified.get());
            dispatcher.dispatch(request, context);
            assertFalse(verified.get());
        }
        final Op[] verify = { Op.NULL, Op.HANDLE_GET_SMALL_FILE, Op.HANDLE_PUT_SMALL_FILE, Op.HANDLE_READ_CHUNK, Op.HANDLE_WRITE_CHUNK, Op.STREAM_INIT };
        for (Op op : verify) {
            final DispatcherContext context = newContext(op);
            assertFalse(verified.get());
            dispatcher.dispatch(request, context);
            assertTrue(verified.getAndSet(false));
        }
    } finally {
        ContainerMetrics.remove();
    }
}

