    when(stateMachine.getDatanodeDetails()).thenReturn(datanodeDetails);
    StateContext context = new StateContext(configuration, mock(DatanodeStateMachine.DatanodeStates.class), stateMachine, "");
    // Set Queue limit
    dnConf.setBlockDeleteQueueLimit(blockDeleteQueueLimit);
    handler = new DeleteBlocksCommandHandler(container, configuration, dnConf, "");
    // Check if the command status is as expected: PENDING when queue is not full, FAILED when queue is full
    for (int i = 0; i < blockDeleteQueueLimit + 2; i++) {
        DeleteBlocksCommand deleteBlocksCommand = new DeleteBlocksCommand(emptyList());
        context.addCommand(deleteBlocksCommand);
        handler.handle(deleteBlocksCommand, container, context, mock(SCMConnectionManager.class));
        CommandStatus cmdStatus = context.getCmdStatus(deleteBlocksCommand.getId());
        if (i < blockDeleteQueueLimit) {
            assertEquals(cmdStatus.getStatus(), Status.PENDING);
        } else {
            assertEquals(cmdStatus.getStatus(), Status.FAILED);
            assertEquals(cmdStatus.getProtoBufMessage().getBlockDeletionAck().getResultsCount(), 0);
        }
    }
}

@Test
public void testExpiredCommandsAreNotProcessed() throws IOException, InterruptedException {
    CountDownLatch latch1 = new CountDownLatch(1);
    ThreadFactory threadFactory = new ThreadFactoryBuilder().build();
    ThreadPoolWithLockExecutor executor = new ThreadPoolWithLockExecutor(threadFactory, latch1);
    DeleteContainerCommandHandler handler = new DeleteContainerCommandHandler(clock, executor, 100);
    DeleteContainerCommand command1 = new DeleteContainerCommand(1L);
    command1.setDeadline(clock.millis() + 10000);
    DeleteContainerCommand command2 = new DeleteContainerCommand(2L);
    command2.setDeadline(clock.millis() + 20000);
    DeleteContainerCommand command3 = new DeleteContainerCommand(3L);
    // No deadline on the 3rd command
    clock.fastForward(15000);
    handler.handle(command1, ozoneContainer, null, null);
    latch1.await();
    assertEquals(1, handler.getTimeoutCount());
    CountDownLatch latch2 = new CountDownLatch(2);
    executor.setLatch(latch2);
    handler.handle(command2, ozoneContainer, null, null);
    handler.handle(command3, ozoneContainer, null, null);
    latch2.await();
    assertEquals(1, handler.getTimeoutCount());
    assertEquals(3, handler.getInvocationCount());
    verify(controller, times(0)).deleteContainer(1L, false);
    verify(controller, times(1)).deleteContainer(2L, false);
    verify(controller, times(1)).deleteContainer(3L, false);
}

