@Test
public void testheartbeatWithAllReports() throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachine = mock(DatanodeStateMachine.class);
    StateContext context = new StateContext(conf, DatanodeStates.RUNNING, datanodeStateMachine, "");
    // Return a Map of command counts when the heartbeat logic requests it
    final Map<SCMCommandProto.Type, Integer> commands = new HashMap<>();
    int count = 1;
    for (SCMCommandProto.Type cmd : SCMCommandProto.Type.values()) {
        commands.put(cmd, count++);
    }
    when(datanodeStateMachine.getQueuedCommandCount()).thenReturn(commands);
    StorageContainerDatanodeProtocolClientSideTranslatorPB scm = mock(StorageContainerDatanodeProtocolClientSideTranslatorPB.class);
    ArgumentCaptor<SCMHeartbeatRequestProto> argument = ArgumentCaptor.forClass(SCMHeartbeatRequestProto.class);
    when(scm.sendHeartbeat(argument.capture())).thenAnswer(invocation -> SCMHeartbeatResponseProto.newBuilder().setDatanodeUUID(((SCMHeartbeatRequestProto) invocation.getArgument(0)).getDatanodeDetails().getUuid()).build());
    HeartbeatEndpointTask endpointTask = getHeartbeatEndpointTask(conf, context, scm);
    context.addEndpoint(TEST_SCM_ENDPOINT);
    context.refreshFullReport(NodeReportProto.getDefaultInstance());
    context.refreshFullReport(ContainerReportsProto.getDefaultInstance());
    context.addIncrementalReport(CommandStatusReportsProto.getDefaultInstance());
    context.addContainerAction(getContainerAction());
    endpointTask.call();
    SCMHeartbeatRequestProto heartbeat = argument.getValue();
    assertTrue(heartbeat.hasDatanodeDetails());
    assertTrue(heartbeat.hasNodeReport());
    assertTrue(heartbeat.hasContainerReport());
    assertNotEquals(0, heartbeat.getCommandStatusReportsCount());
    assertTrue(heartbeat.hasContainerActions());
    assertTrue(heartbeat.hasCommandQueueReport());
    CommandQueueReportProto queueCount = heartbeat.getCommandQueueReport();
    assertEquals(queueCount.getCommandCount(), commands.size());
    assertEquals(queueCount.getCountCount(), commands.size());
    for (int i = 0; i < commands.size(); i++) {
        assertEquals(commands.get(queueCount.getCommand(i)).intValue(), queueCount.getCount(i));
    }
}

@Test
public void testContainerCacheEviction() throws Exception {
    File root = new File(testRoot);
    assertTrue(root.mkdirs());
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setInt(OzoneConfigKeys.OZONE_CONTAINER_CACHE_SIZE, 2);
    ContainerCache cache = ContainerCache.getInstance(conf);
    cache.clear();
    assertEquals(0, cache.size());
    File containerDir1 = new File(root, "cont1");
    File containerDir2 = new File(root, "cont2");
    File containerDir3 = new File(root, "cont3");
    File containerDir4 = new File(root, "cont4");
    createContainerDB(conf, containerDir1);
    createContainerDB(conf, containerDir2);
    createContainerDB(conf, containerDir3);
    createContainerDB(conf, containerDir4);
    ContainerCacheMetrics metrics = cache.getMetrics();
    long numDbGetCount = metrics.getNumDbGetOps();
    long numCacheMisses = metrics.getNumCacheMisses();
    // Get 2 references out of the same db and verify the objects are same.
    ReferenceCountedDB db1 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    assertEquals(1, db1.getReferenceCount());
    assertEquals(numDbGetCount + 1, metrics.getNumDbGetOps());
    ReferenceCountedDB db2 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    assertEquals(2, db2.getReferenceCount());
    assertEquals(numCacheMisses + 1, metrics.getNumCacheMisses());
    assertEquals(2, db1.getReferenceCount());
    assertEquals(db1, db2);
    assertEquals(numDbGetCount + 2, metrics.getNumDbGetOps());
    assertEquals(numCacheMisses + 1, metrics.getNumCacheMisses());
    // add one more references to ContainerCache.
    ReferenceCountedDB db3 = cache.getDB(2, "RocksDB", containerDir2.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    assertEquals(1, db3.getReferenceCount());
    // and close the reference
    db3.close();
    assertEquals(0, db3.getReferenceCount());
    // add one more reference to ContainerCache and verify that it will not
    // evict the least recent entry as it has reference.
    ReferenceCountedDB db4 = cache.getDB(3, "RocksDB", containerDir3.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    assertEquals(1, db4.getReferenceCount());
    assertEquals(2, cache.size());
    assertNotNull(cache.get(containerDir1.getPath()));
    assertNull(cache.get(containerDir2.getPath()));
    // Now close both the references for container1
    db1.close();
    db2.close();
    assertEquals(0, db1.getReferenceCount());
    assertEquals(0, db2.getReferenceCount());
    // The reference count for container1 is 0 but it is not evicted.
    ReferenceCountedDB db5 = cache.getDB(1, "RocksDB", containerDir1.getPath(), VersionedDatanodeFeatures.SchemaV2.chooseSchemaVersion(), conf);
    assertThrows(IllegalArgumentException.class, () -> {
        assertEquals(1, db5.getReferenceCount());
        assertEquals(db1, db5);
