@ParameterizedTest
@MethodSource("getLayoutAndCompression")
public void pack(ContainerTestVersionInfo versionInfo, CopyContainerCompression compression) throws IOException {
    initTests(versionInfo, compression);
    //GIVEN
    KeyValueContainerData sourceContainerData = createContainer(sourceContainerRoot, true, false);
    KeyValueContainer sourceContainer = new KeyValueContainer(sourceContainerData, conf);
    //sample db file in the metadata directory
    writeDbFile(sourceContainerData, TEST_DB_FILE_NAME);
    //sample chunk file in the chunk directory
    writeChunkFile(sourceContainerData, TEST_CHUNK_FILE_NAME);
    //write container checksum file in the metadata directory
    ContainerMerkleTreeWriter treeWriter = buildTestTree(conf);
    checksumTreeManager.updateTree(sourceContainerData, treeWriter);
    assertTrue(ContainerChecksumTreeManager.getContainerChecksumFile(sourceContainerData).exists());
    //sample container descriptor file
    writeDescriptor(sourceContainer);
    Path targetFile = tempDir.resolve("container.tar");
    //WHEN: pack it
    SpyOutputStream outputForPack = new SpyOutputStream(newOutputStream(targetFile));
    packer.pack(sourceContainer, outputForPack);
    //THEN: check the result
    TarArchiveInputStream tarStream = null;
    try (InputStream input = newInputStream(targetFile)) {
        InputStream uncompressed = packer.decompress(input);
        tarStream = new TarArchiveInputStream(uncompressed);
        boolean first = true;
        TarArchiveEntry entry;
        Map<String, TarArchiveEntry> entries = new HashMap<>();
        while ((entry = tarStream.getNextTarEntry()) != null) {
            if (first) {
                assertEquals(CONTAINER_FILE_NAME, entry.getName());
                first = false;
            }
            entries.put(entry.getName(), entry);
        }
        assertThat(entries).containsKey(CONTAINER_FILE_NAME);
    } finally {
        if (tarStream != null) {
            tarStream.close();
        }
    }
    outputForPack.assertClosedExactlyOnce();
    //read the container descriptor only
    SpyInputStream inputForUnpackDescriptor = new SpyInputStream(newInputStream(targetFile));
    String containerYaml = new String(packer.unpackContainerDescriptor(inputForUnpackDescriptor), UTF_8);
    assertEquals(TEST_DESCRIPTOR_FILE_CONTENT, containerYaml);
    inputForUnpackDescriptor.assertClosedExactlyOnce();
    KeyValueContainerData destinationContainerData = createContainer(destContainerRoot, false, false);
    KeyValueContainer destinationContainer = new KeyValueContainer(destinationContainerData, conf);
    //unpackContainerData
    SpyInputStream inputForUnpackData = new SpyInputStream(newInputStream(targetFile));
    String descriptor = new String(packer.unpackContainerData(destinationContainer, inputForUnpackData, tempDir, destContainerRoot.resolve(String.valueOf(destinationContainer.getContainerData().getContainerID()))), UTF_8);
    assertExampleMetadataDbIsGood(TarContainerPacker.getDbPath(destinationContainerData), TEST_DB_FILE_NAME);
    assertExampleChunkFileIsGood(Paths.get(destinationContainerData.getChunksPath()), TEST_CHUNK_FILE_NAME);
    assertEquals(sourceContainerData.getContainerID(), destinationContainerData.getContainerID());
    assertTrue(ContainerChecksumTreeManager.getContainerChecksumFile(destinationContainerData).exists());
    assertTreesSortedAndMatch(checksumTreeManager.read(sourceContainerData).getContainerMerkleTree(), checksumTreeManager.read(destinationContainerData).getContainerMerkleTree());
    String containerFileData = new String(Files.readAllBytes(destinationContainer.getContainerFile().toPath()), UTF_8);
    assertTrue(containerFileData.contains("RECOVERING"), "The state of the container is not 'RECOVERING' in the container file");
    assertEquals(TEST_DESCRIPTOR_FILE_CONTENT, descriptor);
    inputForUnpackData.assertClosedExactlyOnce();
}

