    OutputStream subject = new SendContainerOutputStream(getObserver(), getContainerId(), getBufferSize(), compression, null);
    byte[] bytes = getRandomBytes(16);
    subject.write(bytes, 0, bytes.length);
    subject.close();
    SendContainerRequest req = SendContainerRequest.newBuilder().setContainerID(getContainerId()).setOffset(0).setData(ByteString.copyFrom(bytes)).setCompression(compression.toProto()).build();
    verify(getObserver()).onNext(req);
    verify(getObserver()).onCompleted();
}

