    final List<DatanodeDetails> datanodes = createDatanodes();
    TestingContainerDownloader downloader = TestingContainerDownloader.randomOrder();
    //WHEN executed, THEN at least once the second datanode should be
    //returned.
    for (int i = 0; i < 10000; i++) {
        Path path = downloader.getContainerDataFromReplicas(1L, datanodes, tempDir, NO_COMPRESSION);
        if (path.toString().equals(datanodes.get(1).getUuidString())) {
