@Test
public void testContainerTableAccessBeforeAndAfterUpgrade() throws Exception {
    initTests();
    // start DN and SCM
    scmRpcServer = SCMTestUtils.startScmRpcServer(conf, new ScmTestMock(CLUSTER_ID), address, 10);
    UpgradeTestHelper.addHddsVolume(conf, tempFolder);
    dsm = UpgradeTestHelper.startPreFinalizedDatanode(conf, tempFolder, dsm, address, HDDSLayoutFeature.HBASE_SUPPORT.layoutVersion());
    ContainerDispatcher dispatcher = dsm.getContainer().getDispatcher();
    final Pipeline pipeline = MockPipeline.createPipeline(Collections.singletonList(dsm.getDatanodeDetails()));
    // add a container
    final long containerID = UpgradeTestHelper.addContainer(dispatcher, pipeline);
    Container<?> container = dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OPEN, container.getContainerData().getState());
    // check if the containerIds table is in old format
    WitnessedContainerMetadataStore metadataStore = dsm.getContainer().getWitnessedContainerMetadataStore();
    TypedTable<ContainerID, String> tableWithStringCodec = metadataStore.getStore().getTable(metadataStore.getContainerCreateInfoTable().getName(), ContainerID.getCodec(), StringCodec.get());
    assertEquals("containerIds", metadataStore.getContainerCreateInfoTable().getName());
    assertEquals(OPEN.name(), tableWithStringCodec.get(ContainerID.valueOf(containerID)));
    // close container to allow upgrade.
    UpgradeTestHelper.closeContainer(dispatcher, containerID, pipeline);
    dsm.finalizeUpgrade();
    assertTrue(dsm.getLayoutVersionManager().isAllowed(HDDSLayoutFeature.WITNESSED_CONTAINER_DB_PROTO_VALUE));
    assertEquals(WitnessedContainerDBDefinition.CONTAINER_CREATE_INFO_TABLE_DEF.getName(), metadataStore.getContainerCreateInfoTable().getName());
    ContainerCreateInfo containerCreateInfo = metadataStore.getContainerCreateInfoTable().get(ContainerID.valueOf(containerID));
    // state is always open as state is update while create container only.
    assertEquals(OPEN, containerCreateInfo.getState());
}

@Test
public void testContainerTableFinalizeRetry() throws Exception {
    initTests();
    // start DN and SCM
    scmRpcServer = SCMTestUtils.startScmRpcServer(conf, new ScmTestMock(CLUSTER_ID), address, 10);
    UpgradeTestHelper.addHddsVolume(conf, tempFolder);
    dsm = UpgradeTestHelper.startPreFinalizedDatanode(conf, tempFolder, dsm, address, HDDSLayoutFeature.HBASE_SUPPORT.layoutVersion());
    ContainerDispatcher dispatcher = dsm.getContainer().getDispatcher();
    final Pipeline pipeline = MockPipeline.createPipeline(Collections.singletonList(dsm.getDatanodeDetails()));
    // add a container
    final long containerID = UpgradeTestHelper.addContainer(dispatcher, pipeline);
    Container<?> container = dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OPEN, container.getContainerData().getState());
    // check if the containerIds table is in old format
    WitnessedContainerMetadataStore metadataStore = dsm.getContainer().getWitnessedContainerMetadataStore();
    TypedTable<ContainerID, String> tableWithStringCodec = metadataStore.getStore().getTable(metadataStore.getContainerCreateInfoTable().getName(), ContainerID.getCodec(), StringCodec.get());
    assertEquals("containerIds", metadataStore.getContainerCreateInfoTable().getName());
    assertEquals(OPEN.name(), tableWithStringCodec.get(ContainerID.valueOf(containerID)));
    // add few more container entries to containerIds table as dummy
    for (int i = 0; i < 10; i++) {
        long containerIDWithDummy = containerID + i + 1;
        tableWithStringCodec.put(ContainerID.valueOf(containerIDWithDummy), OPEN.name());
    }
    // close container to allow upgrade.
    UpgradeTestHelper.closeContainer(dispatcher, containerID, pipeline);
    // trigger one upgrade which is not persisted to metastore, partial upgrade
    ContainerTableSchemaFinalizeAction upgradeAction = new ContainerTableSchemaFinalizeAction();
    upgradeAction.execute(dsm);
    Table<ContainerID, ContainerCreateInfo> currTable = WitnessedContainerDBDefinition.CONTAINER_CREATE_INFO_TABLE_DEF.getTable(metadataStore.getStore());
    // 1 original + 10 dummy entries
    assertEquals(11, getTableEntryCount(currTable));
    // cleanup entry and again upgrade
    for (int i = 0; i < 10; i++) {
        long containerIDWithDummy = containerID + i + 1;
        tableWithStringCodec.delete(ContainerID.valueOf(containerIDWithDummy));
    }
    // trigger another upgrade which will update metainfo for upgrade
    dsm.finalizeUpgrade();
    assertTrue(dsm.getLayoutVersionManager().isAllowed(HDDSLayoutFeature.WITNESSED_CONTAINER_DB_PROTO_VALUE));
    assertEquals(WitnessedContainerDBDefinition.CONTAINER_CREATE_INFO_TABLE_DEF.getName(), metadataStore.getContainerCreateInfoTable().getName());
    ContainerCreateInfo containerCreateInfo = metadataStore.getContainerCreateInfoTable().get(ContainerID.valueOf(containerID));
    // state is always open as state is update while create container only.
    assertEquals(OPEN, containerCreateInfo.getState());
    // 1 original + 10 dummy entries
    assertEquals(1, getTableEntryCount(currTable));
}

/**
 * Test incremental chunk list before and after finalization.
 */
@Test
public void testIncrementalChunkListBeforeAndAfterUpgrade() throws Exception {
    initTests();
    // start DN and SCM
    scmRpcServer = SCMTestUtils.startScmRpcServer(conf, new ScmTestMock(CLUSTER_ID), address, 10);
    UpgradeTestHelper.addHddsVolume(conf, tempFolder);
    dsm = UpgradeTestHelper.startPreFinalizedDatanode(conf, tempFolder, dsm, address, HDDSLayoutFeature.HADOOP_PRC_PORTS_IN_DATANODEDETAILS.layoutVersion());
    ContainerDispatcher dispatcher = dsm.getContainer().getDispatcher();
    final Pipeline pipeline = MockPipeline.createPipeline(Collections.singletonList(dsm.getDatanodeDetails()));
    // Add data to read.
    final long containerID = UpgradeTestHelper.addContainer(dispatcher, pipeline);
    // incremental chunk list should be rejected before finalizing.
    UpgradeTestHelper.putBlock(dispatcher, containerID, pipeline, true, ContainerProtos.Result.UNSUPPORTED_REQUEST);
    Container<?> container = dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OPEN, container.getContainerData().getState());
    // close container to allow upgrade.
    UpgradeTestHelper.closeContainer(dispatcher, containerID, pipeline);
    dsm.finalizeUpgrade();
    assertTrue(dsm.getLayoutVersionManager().isAllowed(HDDSLayoutFeature.HBASE_SUPPORT));
    // open a new container after finalization
    final long containerID2 = UpgradeTestHelper.addContainer(dispatcher, pipeline);
    // incremental chunk list should work after finalizing.
    UpgradeTestHelper.putBlock(dispatcher, containerID2, pipeline, true);
    Container<?> container2 = dsm.getContainer().getContainerSet().getContainer(containerID2);
    assertEquals(OPEN, container2.getContainerData().getState());
}

