/**
 * Test RocksDB is created on data volume, not matter Schema V3 is
 * enabled or not.
 * If Schema V3 is enabled, RocksDB will be loaded.
 */
@ParameterizedTest(name = "schema V3 enabled :{0}")
@ValueSource(booleans = { true, false })
public void testDBOnHddsVolume(boolean schemaV3Enabled) throws Exception {
    initTests(schemaV3Enabled);
    // start DN and SCM
    scmRpcServer = SCMTestUtils.startScmRpcServer(conf, new ScmTestMock(CLUSTER_ID), address, 10);
    UpgradeTestHelper.addHddsVolume(conf, tempFolder);
    dsm = UpgradeTestHelper.startPreFinalizedDatanode(conf, tempFolder, dsm, address, HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion());
    HddsVolume dataVolume = (HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0);
    assertNull(dataVolume.getDbVolume());
    assertFalse(dataVolume.isDbLoaded());
    dsm.finalizeUpgrade();
    // RocksDB is created during upgrade
    File dbFile = new File(dataVolume.getStorageDir().getAbsolutePath() + "/" + dataVolume.getClusterID() + "/" + dataVolume.getStorageID());
    assertTrue(dbFile.exists());
    // RocksDB loaded when SchemaV3 is enabled
    if (VersionedDatanodeFeatures.SchemaV3.isFinalizedAndEnabled(conf)) {
        assertTrue(dataVolume.getDbParentDir().getAbsolutePath().startsWith(dataVolume.getStorageDir().toString()));
    } else {
        // RocksDB is not loaded when SchemaV3 is disabled.
        assertFalse(dataVolume.isDbLoaded());
    }
}

