@Test
public void testSignAndVerifySuccess() throws Exception {
    // Data can be signed and verified by same key.
    byte[] data = RandomUtils.secure().randomBytes(100);
    ManagedSecretKey secretKey = generateHmac(now(), ofDays(1));
    byte[] signature = secretKey.sign(data);
    assertTrue(secretKey.isValidSignature(data, signature));
    // Data can be signed and verified by same key transferred via network.
    ManagedSecretKey transferredKey = fromProtobuf(secretKey.toProtobuf());
    assertTrue(transferredKey.isValidSignature(data, signature));
    // Token can be sign and verified by the same key.
    OzoneBlockTokenIdentifier tokenId = new OzoneBlockTokenIdentifier("owner", new BlockID(1L, 1L), of(AccessModeProto.READ), 0L, 1L);
    tokenId.setSecretKeyId(secretKey.getId());
    signature = secretKey.sign(tokenId);
    assertTrue(secretKey.isValidSignature(tokenId, signature));
    // Token can be signed and verified by same key transferred via network.
    assertTrue(transferredKey.isValidSignature(tokenId, signature));
}

@Test
public void testVerifyFailure() throws Exception {
    byte[] data = RandomUtils.secure().randomBytes(100);
    ManagedSecretKey secretKey = generateHmac(now(), ofDays(1));
    // random signature is not valid.
    assertFalse(secretKey.isValidSignature(data, RandomUtils.secure().randomBytes(100)));
    // Data sign by one key can't be verified by another key.
    byte[] signature = secretKey.sign(data);
    ManagedSecretKey secretKey1 = generateHmac(now(), ofDays(1));
    assertFalse(secretKey1.isValidSignature(data, signature));
}

/**
 * Verify how SecretKeyManager initializes its keys under different scenarios,
 * e.g. with or without the present of saved keys.
 */
@ParameterizedTest
@MethodSource("loadSecretKeysTestCases")
public void testLoadSecretKeys(List<ManagedSecretKey> savedSecretKey, ManagedSecretKey expectedCurrentKey, List<ManagedSecretKey> expectedLoadedKeys) throws Exception {
    SecretKeyState state = new SecretKeyStateImpl(mockedKeyStore);
    SecretKeyManager lifeCycleManager = new SecretKeyManager(state, mockedKeyStore, ROTATION_DURATION, VALIDITY_DURATION, ALGORITHM);
    when(mockedKeyStore.load()).thenReturn(savedSecretKey);
    lifeCycleManager.checkAndInitialize();
    if (expectedCurrentKey != null) {
        assertEquals(state.getCurrentKey(), expectedCurrentKey);
        List<ManagedSecretKey> allKeys = state.getSortedKeys();
        assertSameKeys(expectedLoadedKeys, allKeys);
    } else {
        // expect the current key is newly generated.
        assertThat(savedSecretKey).doesNotContain(state.getCurrentKey());
        assertEquals(1, state.getSortedKeys().size());
        assertThat(state.getSortedKeys()).contains(state.getCurrentKey());
    }
}

/**
 * Verify rotation behavior under different scenarios.
 */
@ParameterizedTest
@MethodSource("rotationTestCases")
public void testRotate(List<ManagedSecretKey> initialKeys, boolean expectRotate, List<ManagedSecretKey> expectedRetainedKeys) throws Exception {
    SecretKeyState state = new SecretKeyStateImpl(mockedKeyStore);
    SecretKeyManager lifeCycleManager = new SecretKeyManager(state, mockedKeyStore, ROTATION_DURATION, VALIDITY_DURATION, ALGORITHM);
    // Set the initial state.
    state.updateKeys(initialKeys);
    ManagedSecretKey initialCurrentKey = state.getCurrentKey();
    reset(mockedKeyStore);
    assertEquals(expectRotate, lifeCycleManager.checkAndRotate(false));
    if (expectRotate) {
        // Verify rotation behavior.
        // 1. A new key is generated as current key.
        ManagedSecretKey currentKey = state.getCurrentKey();
        assertNotEquals(initialCurrentKey, currentKey);
        assertThat(initialKeys).doesNotContain(currentKey);
        // 2. keys are correctly rotated, expired ones are excluded.
        List<ManagedSecretKey> expectedAllKeys = expectedRetainedKeys;
        expectedAllKeys.add(currentKey);
        assertSameKeys(expectedAllKeys, state.getSortedKeys());
        // 3. All keys are stored.
        ArgumentCaptor<Collection<ManagedSecretKey>> storedKeyCaptor = ArgumentCaptor.forClass(Collection.class);
        verify(mockedKeyStore).save(storedKeyCaptor.capture());
        assertSameKeys(expectedAllKeys, storedKeyCaptor.getValue());
        // 4. The new generated key has correct data.
        assertEquals(ALGORITHM, currentKey.getSecretKey().getAlgorithm());
        assertEquals(0, Duration.between(currentKey.getCreationTime(), now()).toMinutes());
        Instant expectedExpiryTime = now().plus(VALIDITY_DURATION);
        assertEquals(0, Duration.between(currentKey.getExpiryTime(), expectedExpiryTime).toMinutes());
    } else {
        assertEquals(initialCurrentKey, state.getCurrentKey());
        assertSameKeys(initialKeys, state.getSortedKeys());
    }
}

