@Test
public void testCertificateLoadingOnInit() throws Exception {
    KeyPair keyPair = keyGenerator.generateKey();
    X509Certificate cert1 = generateX509Cert(keyPair);
    X509Certificate cert2 = generateX509Cert(keyPair);
    X509Certificate cert3 = generateX509Cert(keyPair);
    X509Certificate rootCa1 = generateX509Cert(keyPair);
    X509Certificate rootCa2 = generateX509Cert(keyPair);
    X509Certificate subCa1 = generateX509Cert(keyPair);
    X509Certificate subCa2 = generateX509Cert(keyPair);
    Path certPath = dnSecurityConfig.getCertificateLocation(DN_COMPONENT);
    CertificateCodec codec = new CertificateCodec(dnSecurityConfig, DN_COMPONENT);
    // Certificate not found.
    CertificateException certException = assertThrows(CertificateException.class, () -> dnCertClient.getCertificate(cert1.getSerialNumber().toString()));
    assertThat(certException.getMessage()).contains("Error while getting certificate");
    certException = assertThrows(CertificateException.class, () -> dnCertClient.getCertificate(cert2.getSerialNumber().toString()));
    assertThat(certException.getMessage()).contains("Error while getting certificate");
    certException = assertThrows(CertificateException.class, () -> dnCertClient.getCertificate(cert3.getSerialNumber().toString()));
    assertThat(certException.getMessage()).contains("Error while getting certificate");
    codec.writeCertificate(certPath, "1.crt", getPEMEncodedString(cert1));
    codec.writeCertificate(certPath, "2.crt", getPEMEncodedString(cert2));
    codec.writeCertificate(certPath, "3.crt", getPEMEncodedString(cert3));
    codec.writeCertificate(certPath, CAType.ROOT.getFileNamePrefix() + "1.crt", getPEMEncodedString(rootCa1));
    codec.writeCertificate(certPath, CAType.ROOT.getFileNamePrefix() + "2.crt", getPEMEncodedString(rootCa2));
    codec.writeCertificate(certPath, CAType.SUBORDINATE.getFileNamePrefix() + "1.crt", getPEMEncodedString(subCa1));
    codec.writeCertificate(certPath, CAType.SUBORDINATE.getFileNamePrefix() + "2.crt", getPEMEncodedString(subCa2));
    // Re instantiate DN client which will load certificates from filesystem.
