    createTableCache(cacheType);
    // In non-HA epoch entries might be out of order.
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(0, Long.toString(0)));
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(1, Long.toString(1)));
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(3, Long.toString(3)));
    tableCache.put(new CacheKey<>(Long.toString(0)), CacheValue.get(2, Long.toString(2)));
    tableCache.put(new CacheKey<>(Long.toString(1)), CacheValue.get(4, Long.toString(1)));
    List<Long> epochs = new ArrayList<>();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(3L);
    tableCache.evictCache(epochs);
    assertEquals(2, tableCache.size());
    if (cacheType == TableCache.CacheType.FULL_CACHE) {
        // no deleted entries
        assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        assertEquals(2, tableCache.getEpochEntries().size());
    }
    assertNotNull(tableCache.get(new CacheKey<>(Long.toString(0))));
    assertEquals(2, tableCache.get(new CacheKey<>(Long.toString(0))).getEpoch());
    assertNotNull(tableCache.get(new CacheKey<>(Long.toString(1))));
    assertEquals(4, tableCache.get(new CacheKey<>(Long.toString(1))).getEpoch());
    // now evict 2,4
    epochs = new ArrayList<>();
    epochs.add(2L);
    epochs.add(4L);
    tableCache.evictCache(epochs);
    if (cacheType == TableCache.CacheType.PARTIAL_CACHE) {
        assertEquals(0, tableCache.size());
        assertEquals(0, tableCache.getEpochEntries().size());
    } else {
        assertEquals(2, tableCache.size());
        assertEquals(0, tableCache.getEpochEntries().size());
        // Entries should exist, as the entries are not delete entries
        assertNotNull(tableCache.get(new CacheKey<>(Long.toString(0))));
        assertEquals(2, tableCache.get(new CacheKey<>(Long.toString(0))).getEpoch());
        assertNotNull(tableCache.get(new CacheKey<>(Long.toString(1))));
        assertEquals(4, tableCache.get(new CacheKey<>(Long.toString(1))).getEpoch());
    }
}

