    TreeMap<Pair<String, Integer>, String> keys = IntStream.range(0, 100).boxed().collect(Collectors.toMap(i -> Pair.of(String.format(keyFormat, i), i % 2), i -> i % 2 == 0 ? "" : String.format(valueFormat, i), (v1, v2) -> v2, TreeMap::new));
