    try (ManagedOptions options = new ManagedOptions();
        ManagedRawSSTFileReader<ManagedRawSSTFileIterator.KeyValue> reader = new ManagedRawSSTFileReader<>(options, file.getAbsolutePath(), 2 * 1024 * 1024)) {
        List<Optional<String>> testBounds = TestUtils.getTestingBounds(keys.keySet().stream().collect(Collectors.toMap(Pair::getKey, Pair::getValue, (v1, v2) -> v1, TreeMap::new)));
        for (Optional<String> keyStart : testBounds) {
            for (Optional<String> keyEnd : testBounds) {
                Map<Pair<String, Integer>, String> expectedKeys = keys.entrySet().stream().filter(e -> keyStart.map(s -> e.getKey().getKey().compareTo(s) >= 0).orElse(true)).filter(e -> keyEnd.map(s -> e.getKey().getKey().compareTo(s) < 0).orElse(true)).collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
                Optional<ManagedSlice> lowerBound = keyStart.map(s -> new ManagedSlice(StringUtils.string2Bytes(s)));
                Optional<ManagedSlice> upperBound = keyEnd.map(s -> new ManagedSlice(StringUtils.string2Bytes(s)));
                try (ManagedRawSSTFileIterator<ManagedRawSSTFileIterator.KeyValue> iterator = reader.newIterator(Function.identity(), lowerBound.orElse(null), upperBound.orElse(null))) {
                    while (iterator.hasNext()) {
                        ManagedRawSSTFileIterator.KeyValue r = iterator.next();
                        String key = StringUtils.bytes2String(r.getKey());
                        Pair<String, Integer> recordKey = Pair.of(key, r.getType());
                        assertThat(expectedKeys).containsKey(recordKey);
                        assertEquals(Optional.ofNullable(expectedKeys.get(recordKey)).orElse(""), StringUtils.bytes2String(r.getValue()));
                        expectedKeys.remove(recordKey);
                    }
                    assertEquals(0, expectedKeys.size());
                } finally {
                    lowerBound.ifPresent(ManagedSlice::close);
                    upperBound.ifPresent(ManagedSlice::close);
                }
            }
        }
    }
}

