public void testPruneOlderSnapshotsWithCompactionHistory(String description, List<String> compactionLogs, List<CompactionLogEntry> compactionLogEntries, Set<String> expectedNodes, int expectedNumberOfLogEntriesBeforePruning, int expectedNumberOfLogEntriesAfterPruning) throws IOException, ExecutionException, InterruptedException, TimeoutException {
    List<File> filesCreated = new ArrayList<>();
    if (compactionLogs != null) {
        for (int i = 0; i < compactionLogs.size(); i++) {
            String compactionFileName = METADATA_DIR_NAME + "/" + COMPACTION_LOG_DIR_NAME + "/0000" + i + COMPACTION_LOG_FILE_NAME_SUFFIX;
            File compactionFile = new File(compactionFileName);
            Files.write(compactionFile.toPath(), compactionLogs.get(i).getBytes(StandardCharsets.UTF_8));
            filesCreated.add(compactionFile);
        }
    } else if (compactionLogEntries != null) {
        compactionLogEntries.forEach(entry -> rocksDBCheckpointDiffer.addToCompactionLogTable(entry));
    } else {
        throw new IllegalArgumentException("One of compactionLog or" + " compactionLogEntries should be present.");
    }
    rocksDBCheckpointDiffer.loadAllCompactionLogs();
    assertEquals(expectedNumberOfLogEntriesBeforePruning, countEntriesInCompactionLogTable());
    waitForLock(rocksDBCheckpointDiffer, RocksDBCheckpointDiffer::pruneOlderSnapshotsWithCompactionHistory);
    Set<String> actualNodesInForwardDAG = rocksDBCheckpointDiffer.getForwardCompactionDAG().nodes().stream().map(CompactionNode::getFileName).collect(Collectors.toSet());
    Set<String> actualNodesBackwardDAG = rocksDBCheckpointDiffer.getBackwardCompactionDAG().nodes().stream().map(CompactionNode::getFileName).collect(Collectors.toSet());
    assertEquals(expectedNodes, actualNodesInForwardDAG);
    assertEquals(expectedNodes, actualNodesBackwardDAG);
    for (int i = 0; compactionLogs != null && i < compactionLogs.size(); i++) {
        File compactionFile = filesCreated.get(i);
        assertFalse(compactionFile.exists());
    }
    assertEquals(expectedNumberOfLogEntriesAfterPruning, countEntriesInCompactionLogTable());
}

