    List<CompactionNode> compactionNodes = rocksDBCheckpointDiffer.getCompactionNodeMap().values().stream().filter(node -> !COLUMN_FAMILIES_TO_TRACK_IN_DAG.contains(node.getColumnFamily())).collect(Collectors.toList());
