@Test
public void testDeleteNotSentWithExpirationTimeInPast() throws Exception {
    containerInfo = ReplicationTestUtil.createContainer(HddsProtos.LifeCycleState.CLOSED, new ECReplicationConfig(3, 2));
    setupMocks();
    long moveTimeout = 55 * 60 * 1000, replicationTimeout = 50 * 60 * 1000;
    moveManager.setMoveTimeout(moveTimeout);
    moveManager.setReplicationTimeout(replicationTimeout);
    replicas.addAll(ReplicationTestUtil.createReplicas(containerInfo.containerID(), 1, 2, 3, 4, 5));
    Iterator<ContainerReplica> iterator = replicas.iterator();
    ContainerReplica srcReplica = iterator.next();
    src = srcReplica.getDatanodeDetails();
    tgt = MockDatanodeDetails.randomDatanodeDetails();
    nodes.put(src, NodeStatus.inServiceHealthy());
    nodes.put(tgt, NodeStatus.inServiceHealthy());
    CompletableFuture<MoveManager.MoveResult> res = moveManager.move(containerInfo.containerID(), src, tgt);
    ArgumentCaptor<Long> longCaptorReplicate = ArgumentCaptor.forClass(Long.class);
    verify(replicationManager).sendLowPriorityReplicateContainerCommand(eq(containerInfo), eq(srcReplica.getReplicaIndex()), eq(src), eq(tgt), longCaptorReplicate.capture());
    ContainerReplicaOp op = new ContainerReplicaOp(ADD, tgt, srcReplica.getReplicaIndex(), null, clock.millis() + 1000);
    moveManager.opCompleted(op, containerInfo.containerID(), false);
    ArgumentCaptor<Long> longCaptorDelete = ArgumentCaptor.forClass(Long.class);
    verify(replicationManager).sendDeleteCommand(eq(containerInfo), eq(srcReplica.getReplicaIndex()), eq(src), eq(true), longCaptorDelete.capture());
    // verify that command is sent with deadline as (moveStartTime + moveTimeout)
    // moveStartTime can be calculated as (expirationTime set for replication - replicationTimeout)
    assertEquals(longCaptorReplicate.getValue() - replicationTimeout + moveTimeout, longCaptorDelete.getValue());
    // replicationManager sends a datanode command with the deadline as
    // (scmDeadlineEpochMs - rmConf.getDatanodeTimeoutOffset()). The offset is 6 minutes by default.
    // For the datanode deadline to not be in the past, the below condition is checked.
    assertTrue((longCaptorDelete.getValue() - Duration.ofMinutes(6).toMillis()) > clock.millis());
    op = new ContainerReplicaOp(DELETE, src, srcReplica.getReplicaIndex(), null, clock.millis() + 1000);
    moveManager.opCompleted(op, containerInfo.containerID(), false);
    MoveManager.MoveResult finalResult = res.get();
    assertEquals(COMPLETED, finalResult);
}

@Test
public void testRackAwarePolicy() throws IOException {
    conf.set(ScmConfigKeys.OZONE_SCM_CONTAINER_PLACEMENT_IMPL_KEY, SCMContainerPlacementRackAware.class.getName());
    conf.setStorageSize(OZONE_DATANODE_RATIS_VOLUME_FREE_SPACE_MIN, 0, StorageUnit.MB);
    NodeSchema[] schemas = new NodeSchema[] { ROOT_SCHEMA, RACK_SCHEMA, LEAF_SCHEMA };
    NodeSchemaManager.getInstance().init(schemas, true);
    // network topology cluster
    NetworkTopology cluster = new NetworkTopologyImpl(NodeSchemaManager.getInstance());
    // build datanodes, and network topology
    String rack = "/rack";
    String hostname = "node";
    for (int i = 0; i < 15; i++) {
        // Totally 3 racks, each has 5 datanodes
        DatanodeDetails datanodeDetails = MockDatanodeDetails.createDatanodeDetails(hostname + i, rack + (i / 5));
        DatanodeInfo datanodeInfo = new DatanodeInfo(datanodeDetails, NodeStatus.inServiceHealthy(), UpgradeUtils.defaultLayoutVersionProto());
        StorageReportProto storage1 = HddsTestUtils.createStorageReport(datanodeInfo.getID(), "/data1-" + datanodeInfo.getID(), STORAGE_CAPACITY, 0, 100L, null);
        MetadataStorageReportProto metaStorage1 = HddsTestUtils.createMetadataStorageReport("/metadata1-" + datanodeInfo.getID(), STORAGE_CAPACITY, 0, 100L, null);
        datanodeInfo.updateStorageReports(new ArrayList<>(Arrays.asList(storage1)));
        datanodeInfo.updateMetaDataStorageReports(new ArrayList<>(Arrays.asList(metaStorage1)));
        datanodes.add(datanodeDetails);
        cluster.add(datanodeDetails);
        dnInfos.add(datanodeInfo);
    }
    StorageReportProto storage2 = HddsTestUtils.createStorageReport(dnInfos.get(2).getID(), "/data1-" + dnInfos.get(2).getID(), STORAGE_CAPACITY, 90L, 10L, null);
    dnInfos.get(2).updateStorageReports(new ArrayList<>(Arrays.asList(storage2)));
    StorageReportProto storage3 = HddsTestUtils.createStorageReport(dnInfos.get(3).getID(), "/data1-" + dnInfos.get(3).getID(), STORAGE_CAPACITY, 80L, 20L, null);
    dnInfos.get(3).updateStorageReports(new ArrayList<>(Arrays.asList(storage3)));
    StorageReportProto storage4 = HddsTestUtils.createStorageReport(dnInfos.get(4).getID(), "/data1-" + dnInfos.get(4).getID(), STORAGE_CAPACITY, 70L, 30L, null);
    dnInfos.get(4).updateStorageReports(new ArrayList<>(Arrays.asList(storage4)));
    // create mock node manager
    // node manager
    NodeManager nodeManager = mock(NodeManager.class);
    when(nodeManager.getNodes(NodeStatus.inServiceHealthy())).thenReturn(new ArrayList<>(datanodes));
    for (DatanodeInfo dn : dnInfos) {
        when(nodeManager.getNode(dn.getID())).thenReturn(dn);
    }
    PlacementPolicy policy = ContainerPlacementPolicyFactory.getPolicy(conf, nodeManager, cluster, true, SCMContainerPlacementMetrics.create());
    int nodeNum = 3;
    List<DatanodeDetails> datanodeDetails = policy.chooseDatanodes(null, null, nodeNum, 15, 15);
    assertEquals(nodeNum, datanodeDetails.size());
    assertTrue(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(1)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(2)));
    assertFalse(cluster.isSameParent(datanodeDetails.get(1), datanodeDetails.get(2)));
}

