    dns.add(datanodes.get(1));
    // This is on second rack
    dns.add(datanodes.get(5));
    stat = policy.validateContainerPlacement(dns, 3);
    assertFalse(stat.isPolicySatisfied());
    assertEquals(1, stat.misReplicationCount());
