    //    /rack0/node0  -> IN_SERVICE - used
    //    /rack0/node1
    //    /rack0/node2
    //    /rack1/node3  -> IN_SERVICE - used
    //    /rack1/node4
    //    /rack1/node5
    //    /rack2/node6  -> IN_SERVICE - used
    //    /rack2/node7
    //    /rack2/node8
