/**
 * A closed EC container that is not under, over, or mis replicated but
 * has some unhealthy replicas should be handled.
 */
@Test
public void testClosedWithSufficientReplicationDespiteUnhealthyReplicasReturnsTrue() throws NotLeaderException {
    ContainerInfo container = createContainerInfo(ecReplicationConfig, 1, CLOSED);
    // create 5 closed replicas and 1 unhealthy replica each for indices 2 and 5
    Set<ContainerReplica> containerReplicas = ReplicationTestUtil.createReplicas(container.containerID(), ContainerReplicaProto.State.CLOSED, 1, 2, 3, 4, 5);
    ContainerReplica unhealthyIndex2 = createContainerReplica(container.containerID(), 2, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    ContainerReplica unhealthyIndex5 = createContainerReplica(container.containerID(), 5, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY);
    containerReplicas.add(unhealthyIndex2);
    containerReplicas.add(unhealthyIndex5);
    ContainerCheckRequest request = requestBuilder.setContainerReplicas(containerReplicas).setContainerInfo(container).build();
    ContainerCheckRequest readRequest = requestBuilder.setContainerReplicas(containerReplicas).setContainerInfo(container).setReadOnly(true).build();
    assertTrue(handler.handle(request));
    assertEquals(1, request.getReport().getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    assertTrue(handler.handle(readRequest));
    // Same report object is incremented again
    assertEquals(2, request.getReport().getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    // Only a single delete should be sent, as the read request should not have
    // triggered one.
    ArgumentCaptor<Integer> replicaIndexCaptor = ArgumentCaptor.forClass(Integer.class);
    verify(replicationManager, times(2)).sendDeleteCommand(eq(container), anyInt(), any(DatanodeDetails.class), eq(true));
    // replica index that delete was sent for should either be 2 or 5
    replicaIndexCaptor.getAllValues().forEach(index -> assertTrue(index == 2 || index == 5));
}

