@Test
public void testCanAddReplicasForAdd() {
    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn1, 0, addCmd, deadline, FIVE_GB_CONTAINER_SIZE, clock.millis());
    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn2, 0, addCmd, deadline, FIVE_GB_CONTAINER_SIZE, clock.millis());
    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn3, 0, addCmd, deadline, FIVE_GB_CONTAINER_SIZE, clock.millis());
    // Duplicate for DN2
    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn2, 0, addCmd, deadline + 1, FIVE_GB_CONTAINER_SIZE, clock.millis());
    // Not a duplicate for DN2 as different index. Should not happen in practice as it is not valid to have 2 indexes
    // on the same node.
    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn2, 1, addCmd, deadline, FIVE_GB_CONTAINER_SIZE, clock.millis());
    pendingOps.scheduleAddReplica(ContainerID.valueOf(2), dn1, 1, addCmd, deadline, THREE_GB_CONTAINER_SIZE, clock.millis());
    pendingOps.scheduleAddReplica(ContainerID.valueOf(2), dn1, 1, addCmd, deadline + 1, THREE_GB_CONTAINER_SIZE, clock.millis());
    List<ContainerReplicaOp> ops = pendingOps.getPendingOps(ContainerID.valueOf(1));
    assertEquals(4, ops.size());
    for (ContainerReplicaOp op : ops) {
        if (!op.getTarget().equals(dn2)) {
            assertEquals(0, op.getReplicaIndex());
        }
        assertEquals(ADD, op.getOpType());
        if (op.getTarget().equals(dn2) && op.getReplicaIndex() == 0) {
            assertEquals(deadline + 1, op.getDeadlineEpochMillis());
        } else {
            assertEquals(deadline, op.getDeadlineEpochMillis());
        }
    }
    List<DatanodeDetails> allDns = ops.stream().map(ContainerReplicaOp::getTarget).collect(Collectors.toList());
    assertThat(allDns).contains(dn1);
    assertThat(allDns).contains(dn2);
    assertThat(allDns).contains(dn3);
    ops = pendingOps.getPendingOps(ContainerID.valueOf(2));
    assertEquals(1, ops.size());
    assertEquals(1, ops.get(0).getReplicaIndex());
    assertEquals(ADD, ops.get(0).getOpType());
    assertEquals(dn1, ops.get(0).getTarget());
    assertEquals(deadline + 1, ops.get(0).getDeadlineEpochMillis());
}

