    pendingOps.scheduleAddReplica(ContainerID.valueOf(1), dn1, 0, addCmd, now + eventTimeout, FIVE_GB_CONTAINER_SIZE, clock.millis());
    // Assert that containerSizeScheduled has the correct size
    ConcurrentHashMap<DatanodeID, ContainerReplicaPendingOps.SizeAndTime> scheduled = pendingOps.getContainerSizeScheduled();
    assertEquals(1, scheduled.size());
    assertEquals(FIVE_GB_CONTAINER_SIZE, scheduled.get(dn1.getID()).getSize());
    // Schedule a second op for the same datanode
    pendingOps.scheduleAddReplica(ContainerID.valueOf(2), dn1, 0, addCmd, now + eventTimeout, THREE_GB_CONTAINER_SIZE, clock.millis());
    assertEquals(FIVE_GB_CONTAINER_SIZE + THREE_GB_CONTAINER_SIZE, scheduled.get(dn1.getID()).getSize());
    // Complete the first op
