public void testUnRecoverable() {
    ECContainerReplicaCount rcnt = new ECContainerReplicaCount(container, new HashSet<>(), Collections.emptyList(), 1);
    assertTrue(rcnt.isUnrecoverable());
    assertEquals(5, rcnt.unavailableIndexes(true).size());
    Set<ContainerReplica> replica = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_MAINTENANCE, 2));
    // The unhealthy replica does not help with recovery even though we now
    // have 3 replicas.
    replica.addAll(ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 3)));
    rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
    assertTrue(rcnt.isUnrecoverable());
    assertEquals(3, rcnt.unavailableIndexes(true).size());
    assertEquals(0, rcnt.additionalMaintenanceCopiesNeeded(false));
    replica = ReplicationTestUtil.createReplicas(Pair.of(DECOMMISSIONED, 1), Pair.of(DECOMMISSIONED, 2), Pair.of(DECOMMISSIONED, 3), Pair.of(DECOMMISSIONED, 4), Pair.of(DECOMMISSIONED, 5));
    rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
    // Not missing as the decommission replicas are still online
    assertFalse(rcnt.isUnrecoverable());
    assertEquals(0, rcnt.unavailableIndexes(true).size());
    // All unhealthy replicas is still un-recoverable.
    replica = ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(IN_SERVICE, 5));
