    replica = ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2));
    rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
