    replica = ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3));
    rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
    assertFalse(rcnt.isMissing());
    assertTrue(rcnt.isUnrecoverable());
    // 3 replicas, with 1 unhealthy
    replica = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2));
    replica.addAll(ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 3)));
    rcnt = new ECContainerReplicaCount(container, replica, Collections.emptyList(), 1);
    assertFalse(rcnt.isMissing());
    assertTrue(rcnt.isUnrecoverable());
    // 4 replicas, with 1 unhealthy
    replica = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3));
    replica.addAll(ReplicationTestUtil.createReplicas(UNHEALTHY, Pair.of(IN_SERVICE, 4)));
