@Test
public void testDatanodesPendingAddAreNotSelectedAsTargets() throws IOException {
    Set<ContainerReplica> availableReplicas = createReplicas(3);
    DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
    List<ContainerReplicaOp> pendingOps = ImmutableList.of(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.ADD, dn, 4));
    /*
    Mock the placement policy. If the list of nodes to be excluded does not
    contain the DN pending ADD, then chooseDatanodes will return a list
    containing that DN. Ensures the test will fail if excludeNodes does not
    contain the DN pending ADD.
     */
    when(ecPlacementPolicy.chooseDatanodes(anyList(), anyList(), isNull(), anyInt(), anyLong(), anyLong())).thenAnswer(invocationOnMock -> {
        List<DatanodeDetails> usedList = invocationOnMock.getArgument(0);
        List<DatanodeDetails> excludeList = invocationOnMock.getArgument(1);
        List<DatanodeDetails> targets = new ArrayList<>(1);
        if (usedList.contains(dn) || excludeList.contains(dn)) {
            targets.add(MockDatanodeDetails.randomDatanodeDetails());
        } else {
            targets.add(dn);
        }
        return targets;
    });
    UnderReplicatedHealthResult result = mock(UnderReplicatedHealthResult.class);
    when(result.getContainerInfo()).thenReturn(container);
    ECUnderReplicationHandler handler = new ECUnderReplicationHandler(ecPlacementPolicy, conf, replicationManager);
    handler.processAndSendCommands(availableReplicas, pendingOps, result, 1);
    assertEquals(1, commandsSent.size());
    assertNotEquals(dn, commandsSent.iterator().next().getKey());
}

@Test
public void testDecommissioningIndexCopiedWhenContainerUnRecoverable() throws IOException {
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1));
    ContainerReplica decomReplica = createContainerReplica(container.containerID(), 2, DECOMMISSIONING, CLOSED);
    availableReplicas.add(decomReplica);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> cmds = testUnderReplicationWithMissingIndexes(emptyList(), availableReplicas, 1, 0, policy);
    assertEquals(1, cmds.size());
    // With push replication the command should always be sent to the
    // decommissioning source.
    DatanodeDetails target = cmds.iterator().next().getKey();
    assertEquals(decomReplica.getDatanodeDetails(), target);
}

@Test
public void testMaintenanceIndexCopiedWhenContainerUnRecoverable() throws IOException {
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1));
    ContainerReplica maintReplica = createContainerReplica(container.containerID(), 2, ENTERING_MAINTENANCE, CLOSED);
    availableReplicas.add(maintReplica);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> cmds = testUnderReplicationWithMissingIndexes(emptyList(), availableReplicas, 0, 1, policy);
    assertEquals(0, cmds.size());
    // Change the remaining redundancy to ensure something needs copied.
    remainingMaintenanceRedundancy = 2;
    cmds = testUnderReplicationWithMissingIndexes(emptyList(), availableReplicas, 0, 1, policy);
    assertEquals(1, cmds.size());
    // With push replication the command should always be sent to the
    // entering_maintenance source.
    DatanodeDetails target = cmds.iterator().next().getKey();
    assertEquals(maintReplica.getDatanodeDetails(), target);
}

