@Test
public void testInsufficientNodesExceptionThrown() {
    final DatanodeID origin1 = DatanodeID.randomID();
    final DatanodeID origin2 = DatanodeID.randomID();
    Set<ContainerReplica> replicas = ReplicationTestUtil.createReplicasWithOriginAndOpState(container.containerID(), StorageContainerDatanodeProtocolProtos.ContainerReplicaProto.State.QUASI_CLOSED, Pair.of(origin1, HddsProtos.NodeOperationalState.IN_SERVICE), Pair.of(origin2, HddsProtos.NodeOperationalState.IN_SERVICE));
    PlacementPolicy policy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
