@Test
void testReplicaCounts() {
    ContainerInfo container = createContainerInfo(RatisReplicationConfig.getInstance(THREE), 1L, HddsProtos.LifeCycleState.CLOSED);
    Set<ContainerReplica> replicas = createReplicas(ContainerID.valueOf(1L), State.CLOSED, 0, 0);
    replicas.add(createContainerReplica(ContainerID.valueOf(1L), 0, IN_SERVICE, CLOSING));
    replicas.add(createContainerReplica(ContainerID.valueOf(1L), 0, IN_SERVICE, UNHEALTHY));
    // First, test by not considering UNHEALTHY replicas.
    RatisContainerReplicaCount rcnt = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false);
    assertTrue(rcnt.isSufficientlyReplicated());
    assertFalse(rcnt.isOverReplicated());
    assertEquals(0, rcnt.getExcessRedundancy(true));
    // CLOSED + CLOSED + CLOSING = 3
    assertEquals(3, rcnt.getHealthyReplicaCount());
    // CLOSING = 1
    assertEquals(1, rcnt.getMisMatchedReplicaCount());
    // CLOSED + CLOSED = 2
    assertEquals(2, rcnt.getMatchingReplicaCount());
    // UNHEALTHY = 1
    assertEquals(1, rcnt.getUnhealthyReplicaCount());
    // Now, test by considering UNHEALTHY replicas
    rcnt = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, true);
    assertTrue(rcnt.isSufficientlyReplicated());
    assertTrue(rcnt.isOverReplicated());
    assertEquals(1, rcnt.getExcessRedundancy(true));
    // CLOSED + CLOSED + CLOSING = 3
    assertEquals(3, rcnt.getHealthyReplicaCount());
    // CLOSING = 1
    assertEquals(1, rcnt.getMisMatchedReplicaCount());
    // CLOSED + CLOSED = 2
    assertEquals(2, rcnt.getMatchingReplicaCount());
    // UNHEALTHY = 1
    assertEquals(1, rcnt.getUnhealthyReplicaCount());
}

