/**
 * A container is safely over replicated if:
 * 1. It is over replicated.
 * 2. Has at least replication factor number of matching replicas.
 */
@Test
void testSafelyOverReplicated() {
    /*
    First case: 3 CLOSED, 2 UNHEALTHY, 1 pending delete.
     */
    ContainerInfo container = createContainerInfo(RatisReplicationConfig.getInstance(THREE), 1L, HddsProtos.LifeCycleState.CLOSED);
    Set<ContainerReplica> replicas = createReplicas(container.containerID(), State.CLOSED, 0, 0, 0);
    Set<ContainerReplica> unhealthyReplicas = createReplicas(container.containerID(), UNHEALTHY, 0, 0);
    replicas.addAll(unhealthyReplicas);
    List<ContainerReplicaOp> ops = new ArrayList<>();
    ops.add(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.DELETE, unhealthyReplicas.iterator().next().getDatanodeDetails(), 0));
    RatisContainerReplicaCount withoutUnhealthy = new RatisContainerReplicaCount(container, replicas, ops, 2, false);
    validate(withoutUnhealthy, true, 0, false, false);
    // not safely over replicated (3 CLOSED - 1 pending delete)
    assertFalse(withoutUnhealthy.isSafelyOverReplicated());
    RatisContainerReplicaCount withUnhealthy = new RatisContainerReplicaCount(container, replicas, ops, 2, true);
    validate(withUnhealthy, true, -1, true, false);
    assertTrue(withUnhealthy.isSafelyOverReplicated());
    /*
    Second case: 2 CLOSED, 1 CLOSING, 1 UNHEALTHY
     */
    container = createContainerInfo(RatisReplicationConfig.getInstance(THREE), 1L, HddsProtos.LifeCycleState.CLOSED);
    replicas = createReplicas(container.containerID(), State.CLOSED, 0, 0);
    ContainerReplica unhealthyReplica = createContainerReplica(container.containerID(), 0, IN_SERVICE, UNHEALTHY);
    ContainerReplica misMatchedReplica = createContainerReplica(container.containerID(), 0, IN_SERVICE, CLOSING);
    replicas.add(unhealthyReplica);
    replicas.add(misMatchedReplica);
    withoutUnhealthy = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false);
    validate(withoutUnhealthy, true, 0, false, false);
    assertFalse(withoutUnhealthy.isSafelyOverReplicated());
    withUnhealthy = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, true);
    validate(withUnhealthy, true, -1, true, false);
    // Violates rule 2
    assertFalse(withUnhealthy.isSafelyOverReplicated());
    // now check by adding a CLOSED replica
    replicas.add(createContainerReplica(container.containerID(), 0, IN_SERVICE, State.CLOSED));
    withUnhealthy = new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, true);
    validate(withUnhealthy, true, -2, true, false);
    assertTrue(withUnhealthy.isSafelyOverReplicated());
}

