    final ContainerReplica quasiCloseReplica = createContainerReplica(ContainerID.valueOf(1), 0, IN_SERVICE, ContainerReplicaProto.State.QUASI_CLOSED, sequenceId - 5);
    Set<ContainerReplica> replicas = new HashSet<>();
    replicas.add(replicaOne);
