    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    List<ContainerReplicaOp> ops = containerReplicaPendingOps.getPendingOps(container.containerID());
    verify(nodeManager).addDatanodeCommand(any(), any());
    assertEquals(1, ops.size());
    assertEquals(ContainerReplicaOp.PendingOpType.DELETE, ops.get(0).getOpType());
    assertEquals(unhealthyReplica.getDatanodeDetails(), ops.get(0).getTarget());
    assertEquals(1, ops.get(0).getReplicaIndex());
    assertEquals(1, replicationManager.getMetrics().getEcDeletionCmdsSentTotal());
    assertEquals(0, replicationManager.getMetrics().getDeletionCmdsSentTotal());
    /*
    Now, remove the unhealthy replica. This leaves 5 replicas on 4 racks,
    which is mis replication. RM should queue this container as mis
    replicated now.
     */
    replicas.remove(unhealthyReplica);
    containerReplicaPendingOps.completeDeleteReplica(container.containerID(), unhealthyReplica.getDatanodeDetails(), 1);
    when(ecPlacementPolicy.validateContainerPlacement(anyList(), anyInt())).thenReturn(new ContainerPlacementStatusDefault(4, 5, 5, 1, Lists.newArrayList(2, 1, 1, 1)));
    repReport = new ReplicationManagerReport();
    replicationManager.processContainer(container, repQueue, repReport);
    assertEquals(1, repQueue.underReplicatedQueueSize());
    assertEquals(0, repQueue.overReplicatedQueueSize());
    assertEquals(1, repReport.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(0, repReport.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
}

@Test
public void testUnderReplicationQueuePopulated() {
    // Make it always return mis-replicated. Only a perfectly replicated
    // container should make it the mis-replicated state as under / over
    // replicated take precedence.
    when(ecPlacementPolicy.validateContainerPlacement(anyList(), anyInt())).thenReturn(new ContainerPlacementStatusDefault(1, 2, 3));
    ContainerInfo decomContainer = createContainerInfo(repConfig, 1, HddsProtos.LifeCycleState.CLOSED);
    addReplicas(decomContainer, ContainerReplicaProto.State.CLOSED, Pair.of(DECOMMISSIONING, 1), Pair.of(DECOMMISSIONING, 2), Pair.of(DECOMMISSIONING, 3), Pair.of(DECOMMISSIONING, 4), Pair.of(DECOMMISSIONING, 5));
    ContainerInfo underRep1 = createContainerInfo(repConfig, 2, HddsProtos.LifeCycleState.CLOSED);
    addReplicas(underRep1, ContainerReplicaProto.State.CLOSED, 1, 2, 3, 4);
    ContainerInfo underRep0 = createContainerInfo(repConfig, 3, HddsProtos.LifeCycleState.CLOSED);
    addReplicas(underRep0, ContainerReplicaProto.State.CLOSED, 1, 2, 3);
    ContainerInfo misRep = createContainerInfo(repConfig, 4, HddsProtos.LifeCycleState.CLOSED);
    addReplicas(misRep, ContainerReplicaProto.State.CLOSED, 1, 2, 3, 4, 5);
    enableProcessAll();
    replicationManager.processAll();
    ReplicationQueue queue = replicationManager.getQueue();
    // Get the first message off the queue - it should be underRep0.
    ContainerHealthResult.UnderReplicatedHealthResult res = queue.dequeueUnderReplicatedContainer();
    assertEquals(underRep0, res.getContainerInfo());
    // Now requeue it
    queue.enqueue(res);
    // Now get the next message. It should be underRep1, as it has remaining
    // redundancy 1 + zero retries. UnderRep0 will have remaining redundancy 0
    // and 1 retry. They will have the same weighted redundancy so lesser
    // retries should come first
    res = queue.dequeueUnderReplicatedContainer();
    assertEquals(underRep1, res.getContainerInfo());
    // Next message is underRep0. It starts with a weighted redundancy of 0 + 1
    // retry. The other message on the queue is a decommission only with a
    // weighted redundancy of 5 + 0. So lets dequeue and requeue the message 4
    // times. Then the weighted redundancy will be equal and the decommission
    // one will be next due to having less retries.
    for (int i = 0; i < 4; i++) {
        res = queue.dequeueUnderReplicatedContainer();
        assertEquals(underRep0, res.getContainerInfo());
        queue.enqueue(res);
    }
    res = queue.dequeueUnderReplicatedContainer();
    assertEquals(decomContainer, res.getContainerInfo());
    res = queue.dequeueUnderReplicatedContainer();
    assertEquals(underRep0, res.getContainerInfo());
    // Next is the mis-rep container, which has a remaining redundancy of 6.
    res = queue.dequeueUnderReplicatedContainer();
    assertEquals(misRep, res.getContainerInfo());
    res = queue.dequeueUnderReplicatedContainer();
    assertNull(res);
}

