@MethodSource("getTestScenarios")
public void testAllScenarios(Scenario scenario) throws IOException {
    ReplicationManagerReport repReport = new ReplicationManagerReport();
    ReplicationQueue repQueue = new ReplicationQueue();
    ReplicationManager.ReplicationManagerConfiguration conf = new ReplicationManager.ReplicationManagerConfiguration();
    conf.setMaintenanceRemainingRedundancy(scenario.getEcMaintenanceRedundancy());
    conf.setMaintenanceReplicaMinimum(scenario.getRatisMaintenanceMinimum());
    configuration.setFromObject(conf);
    ReplicationManager replicationManager = createReplicationManager();
    ContainerInfo containerInfo = scenario.buildContainerInfo();
    loadPendingOps(containerInfo, scenario);
    Set<ContainerReplica> replicas = new HashSet<>();
    for (TestReplica replica : scenario.getReplicas()) {
        replicas.add(replica.buildContainerReplica());
    }
    // Set up the maps used by the mocks passed into Replication Manager, so it
    // can find the replicas and containers created here.
    containerInfoSet.add(containerInfo);
    containerReplicaMap.put(containerInfo.containerID(), replicas);
    // Run the replication manager check phase.
    replicationManager.processContainer(containerInfo, repQueue, repReport);
    // Check the results in the report and queue against the expected results.
    assertExpectations(scenario, repReport);
    Expectation expectation = scenario.getExpectation();
    assertEquals(expectation.getUnderReplicatedQueue(), repQueue.underReplicatedQueueSize(), "Test: " + scenario + ": Unexpected count for underReplicatedQueue");
    assertEquals(expectation.getOverReplicatedQueue(), repQueue.overReplicatedQueueSize(), "Test: " + scenario + ": Unexpected count for overReplicatedQueue");
    assertExpectedCommands(scenario, scenario.getCheckCommands());
    commandsSent.clear();
    ReplicationManagerReport roReport = new ReplicationManagerReport();
    replicationManager.checkContainerStatus(containerInfo, roReport);
    assertEquals(0, commandsSent.size());
    assertExpectations(scenario, roReport);
    // Now run the replication manager execute phase, where we expect commands
    // to be sent to fix the under and over replicated containers.
    if (repQueue.underReplicatedQueueSize() > 0) {
        replicationManager.processUnderReplicatedContainer(repQueue.dequeueUnderReplicatedContainer());
    } else if (repQueue.overReplicatedQueueSize() > 0) {
        replicationManager.processOverReplicatedContainer(repQueue.dequeueOverReplicatedContainer());
    }
    assertExpectedCommands(scenario, scenario.getCommands());
}

@Test
public void testGetExcludedAndUsedNodes() throws NodeNotFoundException {
    ContainerInfo container = createContainer(HddsProtos.LifeCycleState.CLOSED, RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE));
    ContainerID cid = container.containerID();
    Set<ContainerReplica> replicas = new HashSet<>();
    ContainerReplica good = createContainerReplica(cid, 0, IN_SERVICE, ContainerReplicaProto.State.CLOSED, 1);
    replicas.add(good);
    ContainerReplica remove = createContainerReplica(cid, 0, IN_SERVICE, ContainerReplicaProto.State.CLOSED, 1);
    replicas.add(remove);
    ContainerReplica unhealthy = createContainerReplica(cid, 0, IN_SERVICE, ContainerReplicaProto.State.UNHEALTHY, 1);
    replicas.add(unhealthy);
    ContainerReplica decommissioning = createContainerReplica(cid, 0, DECOMMISSIONING, ContainerReplicaProto.State.CLOSED, 1);
    replicas.add(decommissioning);
    ContainerReplica maintenance = createContainerReplica(cid, 0, IN_MAINTENANCE, ContainerReplicaProto.State.CLOSED, 1);
    replicas.add(maintenance);
    // dead maintenance node should neither be on the used list nor on the excluded list
    ContainerReplica deadMaintenanceReplica = createContainerReplica(cid, 0, IN_MAINTENANCE, ContainerReplicaProto.State.CLOSED, 1);
    DatanodeDetails deadMaintenanceNode = deadMaintenanceReplica.getDatanodeDetails();
    replicas.add(deadMaintenanceReplica);
    // Take one of the replicas and set it to be removed. It should be on the
    // excluded list rather than the used list.
    Set<ContainerReplica> toBeRemoved = new HashSet<>();
    toBeRemoved.add(remove);
    // Finally, add a pending add and delete. The add should go onto the used
    // list and the delete added to the excluded nodes.
    DatanodeDetails pendingAdd = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails pendingDelete = MockDatanodeDetails.randomDatanodeDetails();
    List<ContainerReplicaOp> pending = new ArrayList<>();
    pending.add(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.ADD, pendingAdd, 0));
    pending.add(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.DELETE, pendingDelete, 0));
    when(replicationManager.getNodeStatus(any())).thenAnswer(invocation -> {
        final DatanodeDetails dn = invocation.getArgument(0);
        if (dn.equals(deadMaintenanceNode)) {
            return NodeStatus.valueOf(dn.getPersistedOpState(), HddsProtos.NodeState.DEAD);
        }
        for (ContainerReplica r : replicas) {
            if (r.getDatanodeDetails().equals(dn)) {
                return NodeStatus.valueOf(r.getDatanodeDetails().getPersistedOpState(), HddsProtos.NodeState.HEALTHY);
            }
        }
        throw new NodeNotFoundException(dn.getID());
    });
    ReplicationManagerUtil.ExcludedAndUsedNodes excludedAndUsedNodes = ReplicationManagerUtil.getExcludedAndUsedNodes(container, new ArrayList<>(replicas), toBeRemoved, pending, replicationManager);
    assertEquals(3, excludedAndUsedNodes.getUsedNodes().size());
    assertThat(excludedAndUsedNodes.getUsedNodes()).contains(good.getDatanodeDetails());
    assertThat(excludedAndUsedNodes.getUsedNodes()).contains(maintenance.getDatanodeDetails());
    assertThat(excludedAndUsedNodes.getUsedNodes()).contains(pendingAdd);
    assertFalse(excludedAndUsedNodes.getUsedNodes().contains(deadMaintenanceNode));
    assertEquals(4, excludedAndUsedNodes.getExcludedNodes().size());
    assertThat(excludedAndUsedNodes.getExcludedNodes()).contains(unhealthy.getDatanodeDetails());
    assertThat(excludedAndUsedNodes.getExcludedNodes()).contains(decommissioning.getDatanodeDetails());
    assertThat(excludedAndUsedNodes.getExcludedNodes()).contains(remove.getDatanodeDetails());
    assertThat(excludedAndUsedNodes.getExcludedNodes()).contains(pendingDelete);
    assertFalse(excludedAndUsedNodes.getExcludedNodes().contains(deadMaintenanceNode));
}

