    containerReplicas.addAll(getReplicas(container.containerID(), ContainerReplicaProto.State.QUASI_CLOSED, datanodeThree));
    containerStateManager.addContainer(container.getProtobuf());
    containerReplicas.forEach(containerStateManager::updateContainerReplica);
    // Generate incremental container report with replica in CLOSED state with intentional lower bcsId
    final IncrementalContainerReportProto containerReport = getIncrementalContainerReportProto(container.containerID(), CLOSED, datanodeThree.getUuidString(), false, 0, 2000L);
