    // should remain empty.
    boolean containerDataChecksumEmpty = containerManager.getContainerReplicas(contID).stream().allMatch(r -> r.getDataChecksum() == 0);
    assertTrue(containerDataChecksumEmpty, "Replicas of the container should not have any data checksums.");
}

@Test
public void testWithContainerDataChecksum() throws Exception {
    final IncrementalContainerReportHandler reportHandler = new IncrementalContainerReportHandler(nodeManager, containerManager, scmContext);
    final int numNodes = 3;
    // Create a container which will have one replica on each datanode.
    final ContainerInfo container = getContainer(LifeCycleState.CLOSED);
    ContainerID contID = container.containerID();
    List<DatanodeDetails> datanodes = new ArrayList<>();
    for (int i = 0; i < numNodes; i++) {
        DatanodeDetails dn = randomDatanodeDetails();
        nodeManager.register(dn, null, null);
        datanodes.add(dn);
    }
    containerStateManager.addContainer(container.getProtobuf());
    getReplicas(contID, ContainerReplicaProto.State.CLOSED, 0, datanodes).forEach(containerStateManager::updateContainerReplica);
    // Container manager should now be aware of 3 replicas of each container.
    assertEquals(3, containerManager.getContainerReplicas(contID).size());
    // All replicas should start with a zero data checksum in SCM.
    boolean dataChecksumsEmpty = containerManager.getContainerReplicas(contID).stream().allMatch(r -> r.getDataChecksum() == 0);
    assertTrue(dataChecksumsEmpty, "Replicas of container one should not yet have any data checksums.");
    // For each datanode, send a container report with a mismatched checksum.
    for (DatanodeDetails dn : datanodes) {
        IncrementalContainerReportProto dnReportProto = getIncrementalContainerReportProto(contID, ContainerReplicaProto.State.CLOSED, dn.getUuidString());
        ContainerReplicaProto replicaWithChecksum = dnReportProto.getReport(0).toBuilder().setDataChecksum(createUniqueDataChecksumForReplica(contID, dn.getUuidString())).build();
        IncrementalContainerReportProto reportWithChecksum = dnReportProto.toBuilder().clearReport().addReport(replicaWithChecksum).build();
        final IncrementalContainerReportFromDatanode dnReport = new IncrementalContainerReportFromDatanode(dn, reportWithChecksum);
        reportHandler.onMessage(dnReport, publisher);
    }
    // All the replicas should have different checksums.
    // Since the containers don't have any data in this test, different checksums are based on container ID and
    // datanode ID.
    int numReplicasChecked = 0;
    for (ContainerReplica replica : containerManager.getContainerReplicas(contID)) {
        long expectedChecksum = createUniqueDataChecksumForReplica(contID, replica.getDatanodeDetails().getUuidString());
        assertEquals(expectedChecksum, replica.getDataChecksum());
        numReplicasChecked++;
    }
    assertEquals(numNodes, numReplicasChecked);
    // For each datanode, send a container report with a matching checksum.
    // This simulates reconciliation running.
    for (DatanodeDetails dn : datanodes) {
        IncrementalContainerReportProto dnReportProto = getIncrementalContainerReportProto(contID, ContainerReplicaProto.State.CLOSED, dn.getUuidString());
        ContainerReplicaProto replicaWithChecksum = dnReportProto.getReport(0).toBuilder().setDataChecksum(createMatchingDataChecksumForReplica(contID)).build();
        IncrementalContainerReportProto reportWithChecksum = dnReportProto.toBuilder().clearReport().addReport(replicaWithChecksum).build();
        IncrementalContainerReportFromDatanode dnReport = new IncrementalContainerReportFromDatanode(dn, reportWithChecksum);
        reportHandler.onMessage(dnReport, publisher);
    }
    // All the replicas should now have matching checksums.
    // Since the containers don't have any data in this test, the matching checksums are based on container ID only.
    numReplicasChecked = 0;
    for (ContainerReplica replica : containerManager.getContainerReplicas(contID)) {
        long expectedChecksum = createMatchingDataChecksumForReplica(contID);
        assertEquals(expectedChecksum, replica.getDataChecksum());
        numReplicasChecked++;
    }
    assertEquals(numNodes, numReplicasChecked);
}

