@Test
public void testSequenceIDGenUponRatisWhenCurrentScmIsNotALeader() throws Exception {
    int batchSize = 100;
    OzoneConfiguration conf = SCMTestUtils.getConf(testDir);
    conf.setInt(OZONE_SCM_SEQUENCE_ID_BATCH_SIZE, batchSize);
    SCMMetadataStore scmMetadataStore = new SCMMetadataStoreImpl(conf);
    scmMetadataStore.start(conf);
    SCMHAManager scmHAManager = SCMHAManagerStub.getInstance(true, new SCMDBTransactionBufferImpl());
    SequenceIdGenerator.StateManager stateManager = spy(new SequenceIdGenerator.StateManagerImpl.Builder().setRatisServer(scmHAManager.getRatisServer()).setDBTransactionBuffer(scmHAManager.getDBTransactionBuffer()).setSequenceIdTable(scmMetadataStore.getSequenceIdTable()).build());
    SequenceIdGenerator sequenceIdGen = new SequenceIdGenerator(conf, scmHAManager, scmMetadataStore.getSequenceIdTable()) {

        @Override
        public StateManager createStateManager(SCMHAManager scmhaManager, Table<String, Long> sequenceIdTable) {
            Preconditions.checkNotNull(scmhaManager);
            return stateManager;
        }
    };
    assertEquals(1L, sequenceIdGen.getNextId("someKey"));
    // Simulation currently this SCM is not a leader node,
    // So this SCM can only allocate IDs within the current batch
    // ([1, batchSize]), does not allow the allocation of IDs for the next batch
    // ([batchSize + 1, batchSize * 2])
    when(stateManager.allocateBatch(anyString(), anyLong(), anyLong())).thenThrow(new SCMException(SCMException.ResultCodes.SCM_NOT_LEADER));
    for (int i = 0; i < batchSize * 3; i++) {
        try {
            long nextID = sequenceIdGen.getNextId("someKey");
            if (nextID > batchSize) {
                fail("Should not allocate a blockID: " + nextID + " that exceeds the current Batch: " + batchSize);
            }
        } catch (Exception e) {
            // ignore
        }
    }
}

