/**
 * In this test we ensure there are some pipelines for the node being
 * decommissioned, but there are no containers. Therefore the workflow
 * must wait until the pipelines have closed before completing the flow.
 */
@Test
public void testClosePipelinesEventFiredWhenAdminStarted() throws NodeNotFoundException {
    DatanodeDetails dn1 = MockDatanodeDetails.randomDatanodeDetails();
    nodeManager.register(dn1, NodeStatus.valueOf(HddsProtos.NodeOperationalState.DECOMMISSIONING, HddsProtos.NodeState.HEALTHY));
