    // the container's sequence id is greater than the healthy replicas'
    ContainerInfo container = ReplicationTestUtil.createContainerInfo(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), containerID.getId(), HddsProtos.LifeCycleState.QUASI_CLOSED, replicas.iterator().next().getSequenceId() + 1);
    // UNHEALTHY replica is on a unique origin and has same sequence id as
    // the container
    ContainerReplica unhealthy = ReplicationTestUtil.createContainerReplica(containerID, 0, dn1.getPersistedOpState(), State.UNHEALTHY, container.getNumberOfKeys(), container.getUsedBytes(), dn1, dn1.getID(), container.getSequenceId());
