    // add a copy of the UNHEALTHY replica on a new node, dn1 should get
    // decommissioned now
    ContainerReplica copyOfUnhealthyOnNewNode = unhealthy.toBuilder().setDatanodeDetails(MockDatanodeDetails.randomDatanodeDetails()).build();
    replicas.add(copyOfUnhealthyOnNewNode);
    when(repManager.getContainerReplicaCount(eq(containerID))).thenReturn(new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false));
    DatanodeAdminMonitorTestUtil.mockCheckContainerState(repManager, false);
    monitor.run();
    assertEquals(0, monitor.getTrackedNodeCount());
    assertEquals(HddsProtos.NodeOperationalState.DECOMMISSIONED, nodeManager.getNodeStatus(dn1).getOperationalState());
}

