    // create a container and 3 QUASI_CLOSED replicas with containerID 1 and same origin ID
    ContainerID containerID = ContainerID.valueOf(1);
    ContainerInfo container = ReplicationTestUtil.createContainerInfo(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), containerID.getId(), HddsProtos.LifeCycleState.QUASI_CLOSED);
    Set<ContainerReplica> replicas = ReplicationTestUtil.createReplicasWithSameOrigin(containerID, State.QUASI_CLOSED, 0, 0, 0);
    // UNHEALTHY replica is on a unique origin and has same sequence id as the container
    ContainerReplica unhealthy = ReplicationTestUtil.createContainerReplica(containerID, 0, dn1.getPersistedOpState(), State.UNHEALTHY, container.getNumberOfKeys(), container.getUsedBytes(), dn1, dn1.getID(), container.getSequenceId());
    replicas.add(unhealthy);
    nodeManager.setContainers(dn1, ImmutableSet.of(containerID));
    when(repManager.getContainerReplicaCount(eq(containerID))).thenReturn(new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false));
    DatanodeAdminMonitorTestUtil.mockCheckContainerState(repManager, true);
    // start monitoring dn1
    monitor.startMonitoring(dn1);
    monitor.run();
    assertEquals(1, monitor.getTrackedNodeCount());
    assertEquals(HddsProtos.NodeOperationalState.DECOMMISSIONING, nodeManager.getNodeStatus(dn1).getOperationalState());
    // Running the monitor again causes it to remain DECOMMISSIONING
    // as nothing has changed.
    monitor.run();
    assertEquals(HddsProtos.NodeOperationalState.DECOMMISSIONING, nodeManager.getNodeStatus(dn1).getOperationalState());
    // add a copy of the UNHEALTHY replica on a new node, dn1 should get
    // decommissioned now
    ContainerReplica copyOfUnhealthyOnNewNode = unhealthy.toBuilder().setDatanodeDetails(MockDatanodeDetails.randomDatanodeDetails()).build();
    replicas.add(copyOfUnhealthyOnNewNode);
    when(repManager.getContainerReplicaCount(eq(containerID))).thenReturn(new RatisContainerReplicaCount(container, replicas, Collections.emptyList(), 2, false));
    DatanodeAdminMonitorTestUtil.mockCheckContainerState(repManager, false);
    monitor.run();
    assertEquals(0, monitor.getTrackedNodeCount());
    assertEquals(HddsProtos.NodeOperationalState.DECOMMISSIONED, nodeManager.getNodeStatus(dn1).getOperationalState());
}

