/**
 * For leader SCM, ensure that a change to the operationalState of a node
 * fires a SCMCommand of type SetNodeOperationalStateCommand.
 *
 * For follower SCM, no SetNodeOperationalStateCommand should be fired, yet
 * operationalState of the node will be updated according to the heartbeat.
 */
@Test
public void testSetNodeOpStateAndCommandFired() throws IOException, NodeNotFoundException, AuthenticationException {
    final int interval = 100;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, interval, MILLISECONDS);
    // If factor 1 pipelines are auto created, registering the new node will
    // trigger a pipeline creation command which may interfere with command
    // checking in this test.
    conf.setBoolean(OZONE_SCM_PIPELINE_AUTO_CREATE_FACTOR_ONE, false);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        DatanodeDetails dn = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        long expiry = System.currentTimeMillis() / 1000 + 1000;
        nodeManager.setNodeOperationalState(dn, HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, expiry);
        // If found mismatch, leader SCM fires a SetNodeOperationalStateCommand
        // to update the opState persisted in Datanode.
        scm.getScmContext().updateLeaderAndTerm(true, 1);
        List<SCMCommand<?>> commands = nodeManager.processHeartbeat(dn);
        assertEquals(SetNodeOperationalStateCommand.class, commands.get(0).getClass());
        assertEquals(1, commands.size());
        // If found mismatch, follower SCM update its own opState according
        // to the heartbeat, and no SCMCommand will be fired.
        scm.getScmContext().updateLeaderAndTerm(false, 2);
        commands = nodeManager.processHeartbeat(dn);
        assertEquals(0, commands.size());
        NodeStatus scmStatus = nodeManager.getNodeStatus(dn);
        assertTrue(scmStatus.getOperationalState() == dn.getPersistedOpState() && scmStatus.getOpStateExpiryEpochSeconds() == dn.getPersistedOpStateExpiryEpochSec());
    }
}

/**
 * Asserts that a single node moves from Healthy to stale node, then from
 * stale node to dead node if it misses enough heartbeats.
 *
 * @throws IOException
 * @throws InterruptedException
 * @throws TimeoutException
 */
@Test
public void testScmDetectStaleAndDeadNode() throws IOException, InterruptedException, AuthenticationException {
    final int interval = 100;
    final int nodeCount = 10;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, interval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1, SECONDS);
    conf.setTimeDuration(OZONE_SCM_STALENODE_INTERVAL, 3, SECONDS);
    conf.setTimeDuration(OZONE_SCM_DEADNODE_INTERVAL, 6, SECONDS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        List<DatanodeDetails> nodeList = createNodeSet(nodeManager, nodeCount);
        DatanodeDetails staleNode = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
        // Heartbeat once
        nodeManager.processHeartbeat(staleNode);
        // Heartbeat all other nodes.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds .. and heartbeat good nodes again.
        Thread.sleep(2 * 1000);
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds, wait a total of 4 seconds to make sure that the
        // node moves into stale state.
        Thread.sleep(2 * 1000);
        List<DatanodeDetails> staleNodeList = nodeManager.getNodes(NodeStatus.inServiceStale());
        assertEquals(1, nodeManager.getNodeCount(NodeStatus.inServiceStale()), "Expected to find 1 stale node");
        assertEquals(1, staleNodeList.size(), "Expected to find 1 stale node");
        assertEquals(staleNode.getID(), staleNodeList.get(0).getID(), "Stale node is not the expected ID");
        Map<String, Map<String, Integer>> nodeCounts = nodeManager.getNodeCount();
        assertEquals(1, nodeCounts.get(HddsProtos.NodeOperationalState.IN_SERVICE.name()).get(HddsProtos.NodeState.STALE.name()).intValue());
        Thread.sleep(1000);
        // heartbeat good nodes again.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        //  6 seconds is the dead window for this test , so we wait a total of
        // 7 seconds to make sure that the node moves into dead state.
        Thread.sleep(2 * 1000);
        // the stale node has been removed
        staleNodeList = nodeManager.getNodes(NodeStatus.inServiceStale());
        nodeCounts = nodeManager.getNodeCount();
        assertEquals(0, nodeManager.getNodeCount(NodeStatus.inServiceStale()), "Expected to find 1 stale node");
        assertEquals(0, staleNodeList.size(), "Expected to find 1 stale node");
