@Test
public void testPipelineReport() throws Exception {
    try (PipelineManagerImpl pipelineManager = createPipelineManager(true)) {
        SCMSafeModeManager scmSafeModeManager = new SCMSafeModeManager(conf, mock(NodeManager.class), pipelineManager, mock(ContainerManager.class), serviceManager, new EventQueue(), scmContext);
        Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
        // pipeline is not healthy until all dns report
        List<DatanodeDetails> nodes = pipeline.getNodes();
        assertFalse(pipelineManager.getPipeline(pipeline.getId()).isHealthy());
        // get pipeline report from each dn in the pipeline
        PipelineReportHandler pipelineReportHandler = new PipelineReportHandler(scmSafeModeManager, pipelineManager, SCMContext.emptyContext(), conf);
        nodes.subList(0, 2).forEach(dn -> sendPipelineReport(dn, pipeline, pipelineReportHandler, false));
        sendPipelineReport(nodes.get(nodes.size() - 1), pipeline, pipelineReportHandler, true);
        // pipeline is healthy when all dns report
        assertTrue(pipelineManager.getPipeline(pipeline.getId()).isHealthy());
        // pipeline should now move to open state
        assertTrue(pipelineManager.getPipeline(pipeline.getId()).isOpen());
        // close the pipeline
        pipelineManager.closePipeline(pipeline.getId());
        pipelineManager.deletePipeline(pipeline.getId());
        // pipeline report for destroyed pipeline should be ignored
        nodes.subList(0, 2).forEach(dn -> sendPipelineReport(dn, pipeline, pipelineReportHandler, false));
        sendPipelineReport(nodes.get(nodes.size() - 1), pipeline, pipelineReportHandler, true);
        assertThrows(PipelineNotFoundException.class, () -> pipelineManager.getPipeline(pipeline.getId()));
    }
}

@Test
public void testPipelineCreationFailedMetric() throws Exception {
    PipelineManagerImpl pipelineManager = createPipelineManager(true);
    // No pipeline at start
    MetricsRecordBuilder metrics = getMetrics(SCMPipelineMetrics.class.getSimpleName());
    long numPipelineAllocated = getLongCounter("NumPipelineAllocated", metrics);
    assertEquals(0, numPipelineAllocated);
    // 3 DNs are unhealthy.
    // Create 5 pipelines (Use up 15 Datanodes)
    for (int i = 0; i < maxPipelineCount; i++) {
        Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
        assertNotNull(pipeline);
    }
    metrics = getMetrics(SCMPipelineMetrics.class.getSimpleName());
    numPipelineAllocated = getLongCounter("NumPipelineAllocated", metrics);
    assertEquals(maxPipelineCount, numPipelineAllocated);
    long numPipelineCreateFailed = getLongCounter("NumPipelineCreationFailed", metrics);
    assertEquals(0, numPipelineCreateFailed);
    //This should fail...
