@Test
public void testPickLowestLoadAnchor() throws IOException, TimeoutException {
    List<DatanodeDetails> healthyNodes = nodeManager.getNodes(NodeStatus.inServiceHealthy());
    int maxPipelineCount = PIPELINE_LOAD_LIMIT * healthyNodes.size() / HddsProtos.ReplicationFactor.THREE.getNumber();
    for (int i = 0; i < maxPipelineCount; i++) {
        try {
            List<DatanodeDetails> nodes = placementPolicy.chooseDatanodes(null, null, HddsProtos.ReplicationFactor.THREE.getNumber(), 0, 0);
            Pipeline pipeline = Pipeline.newBuilder().setId(PipelineID.randomId()).setState(Pipeline.PipelineState.ALLOCATED).setReplicationConfig(RatisReplicationConfig.getInstance(ReplicationFactor.THREE)).setNodes(nodes).build();
            HddsProtos.Pipeline pipelineProto = pipeline.getProtobufMessage(ClientVersion.CURRENT_VERSION);
            nodeManager.addPipeline(pipeline);
            stateManager.addPipeline(pipelineProto);
        } catch (SCMException e) {
            throw e;
            //break;
        }
    }
    // Every node should be evenly used.
    int averageLoadOnNode = maxPipelineCount * HddsProtos.ReplicationFactor.THREE.getNumber() / healthyNodes.size();
    for (DatanodeDetails node : healthyNodes) {
        assertThat(nodeManager.getPipelinesCount(node)).isGreaterThanOrEqualTo(averageLoadOnNode);
    }
    // Should max out pipeline usage.
    assertEquals(maxPipelineCount, stateManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE)).size());
}

