@Test
public void testQueryPipeline() throws IOException, TimeoutException {
    Pipeline pipeline = createDummyPipeline(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, 3);
    // pipeline in allocated state should not be reported
    HddsProtos.Pipeline pipelineProto = pipeline.getProtobufMessage(ClientVersion.CURRENT_VERSION);
    stateManager.addPipeline(pipelineProto);
    assertEquals(0, stateManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).size());
    // pipeline in open state should be reported
    openPipeline(pipelineProto);
    assertEquals(1, stateManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).size());
