    pipeline2 = pipeline2.toBuilder().setState(Pipeline.PipelineState.OPEN).build();
    HddsProtos.Pipeline pipelineProto2 = pipeline2.getProtobufMessage(ClientVersion.CURRENT_VERSION);
    // pipeline in open state should be reported
    stateManager.addPipeline(pipelineProto2);
    assertEquals(2, stateManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).size());
    // pipeline in closed state should not be reported
    finalizePipeline(pipelineProto2);
    assertEquals(1, stateManager.getPipelines(RatisReplicationConfig.getInstance(ReplicationFactor.THREE), Pipeline.PipelineState.OPEN).size());
    // clean up
    finalizePipeline(pipelineProto);
    removePipeline(pipelineProto);
    finalizePipeline(pipelineProto2);
    removePipeline(pipelineProto2);
}

