@Test
public void testSafeModeExitRule() throws Exception {
    containers = new ArrayList<>();
    int numContainers = 100;
    containers.addAll(HddsTestUtils.getContainerInfo(numContainers));
    // Assign open state to containers to be included in the safe mode
    // container list
    for (ContainerInfo container : containers) {
        container.setState(HddsProtos.LifeCycleState.CLOSED);
        container.setNumberOfKeys(10);
    }
    ContainerManager containerManager = mock(ContainerManager.class);
    when(containerManager.getContainers(ReplicationType.RATIS)).thenReturn(containers);
    scmSafeModeManager = new SCMSafeModeManager(config, null, null, containerManager, serviceManager, queue, scmContext);
    scmSafeModeManager.start();
    long cutOff = (long) Math.ceil(numContainers * config.getDouble(HddsConfigKeys.HDDS_SCM_SAFEMODE_THRESHOLD_PCT, HddsConfigKeys.HDDS_SCM_SAFEMODE_THRESHOLD_PCT_DEFAULT));
    assertEquals(cutOff, scmSafeModeManager.getSafeModeMetrics().getNumContainerWithOneReplicaReportedThreshold().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    validateRuleStatus("ContainerSafeModeRule", "0.00% of [Ratis] Containers(0 / 100) with at least one reported");
    testContainerThreshold(containers.subList(0, 25), 0.25);
    assertEquals(25, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(25, 50), 0.50);
    assertEquals(50, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(50, 75), 0.75);
    assertEquals(75, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(75, 100), 1.0);
    assertEquals(100, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    GenericTestUtils.waitFor(() -> !scmSafeModeManager.getInSafeMode(), 100, 1000 * 5);
}

