/**
 * Tests that the correct checkpoint is returned based on the value of
 * SCM's layout version and the presence of the finalizing key.
 */
@Test
public void testUpgradeStateToCheckpointMapping() throws Exception {
    HDDSLayoutVersionManager versionManager = new HDDSLayoutVersionManager(HDDSLayoutFeature.INITIAL_VERSION.layoutVersion());
    PipelineManager pipelineManager = getMockPipelineManager(FinalizationCheckpoint.FINALIZATION_REQUIRED);
    // State manager keeps upgrade information in memory as well as writing
    // it to disk, so we can mock the classes that handle disk ops for this
    // test.
    FinalizationStateManager stateManager = new FinalizationStateManagerTestImpl.Builder().setFinalizationStore(mock(Table.class)).setRatisServer(mock(SCMRatisServer.class)).setTransactionBuffer(mock(DBTransactionBuffer.class)).setUpgradeFinalizer(new SCMUpgradeFinalizer(versionManager)).build();
    // In the actual flow, this would be handled by the FinalizationManager.
    SCMContext scmContext = SCMContext.emptyContext();
    scmContext.setFinalizationCheckpoint(stateManager.getFinalizationCheckpoint());
    SCMUpgradeFinalizationContext context = new SCMUpgradeFinalizationContext.Builder().setConfiguration(new OzoneConfiguration()).setFinalizationStateManager(stateManager).setStorage(mock(SCMStorageConfig.class)).setLayoutVersionManager(versionManager).setSCMContext(scmContext).setPipelineManager(pipelineManager).setNodeManager(mock(NodeManager.class)).build();
    stateManager.setUpgradeContext(context);
    assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.FINALIZATION_REQUIRED);
    stateManager.addFinalizingMark();
    assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.FINALIZATION_STARTED);
    for (HDDSLayoutFeature feature : HDDSLayoutFeature.values()) {
        // Cannot finalize initial version since we are already there.
        if (!feature.equals(HDDSLayoutFeature.INITIAL_VERSION)) {
            stateManager.finalizeLayoutFeature(feature.layoutVersion());
            if (versionManager.needsFinalization()) {
                assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.FINALIZATION_STARTED);
            } else {
                assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.MLV_EQUALS_SLV);
            }
        }
    }
    // Make sure we reached this checkpoint if we finished finalizing all
    // layout features.
    assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.MLV_EQUALS_SLV);
    stateManager.removeFinalizingMark();
    assertCurrentCheckpoint(scmContext, stateManager, FinalizationCheckpoint.FINALIZATION_COMPLETE);
}

/**
 * Tests resuming finalization after a failure or leader change, where the
 * disk state will indicate which finalization checkpoint (and therefore
 * set of steps) the SCM must resume from.
 */
@ParameterizedTest
@EnumSource(FinalizationCheckpoint.class)
public void testResumeFinalizationFromCheckpoint(FinalizationCheckpoint initialCheckpoint) throws Exception {
    LOG.info("Testing finalization beginning at checkpoint {}", initialCheckpoint);
    // Create the table and version manager to appear as if we left off from in
    // progress finalization.
    Table<String, String> finalizationStore = getMockTableFromCheckpoint(initialCheckpoint);
    HDDSLayoutVersionManager versionManager = getMockVersionManagerFromCheckpoint(initialCheckpoint);
    SCMHAManager haManager = mock(SCMHAManager.class);
    DBTransactionBuffer buffer = mock(DBTransactionBuffer.class);
    when(haManager.getDBTransactionBuffer()).thenReturn(buffer);
    NodeManager nodeManager = mock(NodeManager.class);
    SCMStorageConfig storage = mock(SCMStorageConfig.class);
    SCMContext scmContext = SCMContext.emptyContext();
    scmContext.setFinalizationCheckpoint(initialCheckpoint);
    PipelineManager pipelineManager = getMockPipelineManager(initialCheckpoint);
    FinalizationStateManager stateManager = new FinalizationStateManagerTestImpl.Builder().setFinalizationStore(finalizationStore).setRatisServer(mock(SCMRatisServer.class)).setTransactionBuffer(buffer).setUpgradeFinalizer(new SCMUpgradeFinalizer(versionManager)).build();
    FinalizationManager manager = new FinalizationManagerTestImpl.Builder().setFinalizationStateManager(stateManager).setConfiguration(new OzoneConfiguration()).setLayoutVersionManager(versionManager).setStorage(storage).setHAManager(SCMHAManagerStub.getInstance(true)).setFinalizationStore(finalizationStore).build();
    manager.buildUpgradeContext(nodeManager, pipelineManager, scmContext);
    // Execute upgrade finalization, then check that events happened in the
    // correct order.
    StatusAndMessages status = manager.finalizeUpgrade(UUID.randomUUID().toString());
    assertEquals(getStatusFromCheckpoint(initialCheckpoint).status(), status.status());
    InOrder inOrder = inOrder(buffer, pipelineManager, nodeManager, storage);
    // Once the initial checkpoint's operations are crossed, this count will
    // be increased to 1 to indicate where finalization should have resumed
    // from.
    VerificationMode count = never();
    if (initialCheckpoint == FinalizationCheckpoint.FINALIZATION_REQUIRED) {
        count = times(1);
    }
    // First, SCM should mark that it is beginning finalization.
    inOrder.verify(buffer, count).addToBuffer(eq(finalizationStore), matches(OzoneConsts.FINALIZING_KEY), matches(""));
    // Next, all pipeline creation should be stopped.
    inOrder.verify(pipelineManager, count).freezePipelineCreation();
    if (initialCheckpoint == FinalizationCheckpoint.FINALIZATION_STARTED) {
        count = times(1);
    }
    // Next, each layout feature should be finalized.
    for (HDDSLayoutFeature feature : HDDSLayoutFeature.values()) {
        // Cannot finalize initial version since we are already there.
        if (!feature.equals(HDDSLayoutFeature.INITIAL_VERSION)) {
            inOrder.verify(storage, count).setLayoutVersion(feature.layoutVersion());
            inOrder.verify(storage, count).persistCurrentState();
            // After MLV == SLV, all datanodes should be moved to healthy readonly.
            if (feature.layoutVersion() == HDDSLayoutVersionManager.maxLayoutVersion()) {
                inOrder.verify(nodeManager, count).forceNodesToHealthyReadOnly();
            }
            inOrder.verify(buffer, count).addToBuffer(eq(finalizationStore), matches(OzoneConsts.LAYOUT_VERSION_KEY), eq(String.valueOf(feature.layoutVersion())));
        }
    }
    // If this was not called in the loop, there was an error. To detect this
    // mistake, verify again here.
    verify(nodeManager, count).forceNodesToHealthyReadOnly();
    if (initialCheckpoint == FinalizationCheckpoint.MLV_EQUALS_SLV) {
        count = times(1);
    }
    // Last, the finalizing mark is removed to indicate finalization is
    // complete.
    inOrder.verify(buffer, count).removeFromBuffer(eq(finalizationStore), matches(OzoneConsts.FINALIZING_KEY));
    // If the initial checkpoint was FINALIZATION_COMPLETE, no mocks should
    // have been invoked.
}

@Test
public void testStartupSlvLessThanMlv(@TempDir Path tempDir) throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    File scmSubdir = tempDir.resolve("scm").resolve("current").toFile();
    assertTrue(scmSubdir.mkdirs());
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(ScmConfigKeys.OZONE_SCM_DB_DIRS, tempDir.toAbsolutePath().toString());
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, tempDir.toAbsolutePath().toString());
    // Set metadata layout version larger then software layout version.
    int largestSlv = 0;
    for (LayoutFeature f : HDDSLayoutFeature.values()) {
        largestSlv = Math.max(largestSlv, f.layoutVersion());
    }
    int mlv = largestSlv + 1;
    Properties properties = new Properties();
    properties.setProperty(SCM_ID, "scm");
    properties.setProperty(SCM_HA, "true");
    // Create version file with MLV > SLV, which should fail the SCM
    // construction.
    UpgradeTestUtils.createVersionFile(scmSubdir, HddsProtos.NodeType.SCM, mlv, properties);
    Throwable t = assertThrows(IOException.class, () -> new StorageContainerManager(conf));
    String expectedMessage = String.format("Cannot initialize VersionManager." + " Metadata layout version (%s) > software layout version (%s)", mlv, largestSlv);
    assertEquals(expectedMessage, t.getMessage());
}

