@Test
public void testMultipleChunksWithPartialChunkInSingleWriteOp() throws IOException {
    final int partialChunkLen = 10;
    final int numFullChunks = 9;
    final int inputBuffLen = (numFullChunks * chunkSize) + partialChunkLen;
    byte[] inputData = new byte[inputBuffLen];
    for (int i = 0; i < numFullChunks; i++) {
        int start = (i * chunkSize);
        Arrays.fill(inputData, start, start + chunkSize - 1, String.valueOf(i).getBytes(UTF_8)[0]);
    }
    //fill the last partial chunk as well.
    Arrays.fill(inputData, (numFullChunks * chunkSize), ((numFullChunks * chunkSize)) + partialChunkLen - 1, (byte) 1);
    final OzoneBucket bucket = writeIntoECKey(inputData, keyName, new DefaultReplicationConfig(new ECReplicationConfig(dataBlocks, parityBlocks, ECReplicationConfig.EcCodec.RS, chunkSize)));
    OzoneKey key = bucket.getKey(keyName);
    validateContent(inputData, bucket, key);
}

@Test
public void testCommitKeyInfo() throws IOException {
    final OzoneBucket bucket = writeIntoECKey(inputChunks, keyName, new DefaultReplicationConfig(new ECReplicationConfig(dataBlocks, parityBlocks, ECReplicationConfig.EcCodec.RS, chunkSize)));
    // create key without mentioning replication config. Since we set EC
    // replication in bucket, key should be EC key.
    try (OzoneOutputStream out = bucket.createKey("mykey", 6 * inputSize)) {
        assertInstanceOf(ECKeyOutputStream.class, out.getOutputStream());
        // Block Size is 2kb, so to create 3 blocks we need 6 iterations here
        for (int j = 0; j < 6; j++) {
            for (byte[] inputChunk : inputChunks) {
                out.write(inputChunk);
            }
        }
    }
    OzoneManagerProtocolProtos.KeyLocationList blockList = transportStub.getKeys().get(volumeName).get(bucketName).get("mykey").getKeyLocationListList().get(0);
    assertEquals(3, blockList.getKeyLocationsCount());
    // As the mock allocator allocates block with id's increasing sequentially
    // from 1. Therefore the block should be in the order with id starting 1, 2
    // and then 3.
    for (int i = 0; i < 3; i++) {
        long localId = blockList.getKeyLocationsList().get(i).getBlockID().getContainerBlockID().getLocalID();
        assertEquals(i + 1, localId);
    }
    assertEquals(1, transportStub.getKeys().get(volumeName).get(bucketName).get("mykey").getKeyLocationListCount());
    assertEquals(inputChunks[0].length * 3 * 6, transportStub.getKeys().get(volumeName).get(bucketName).get("mykey").getDataSize());
}

