@Test
public void testPartialStripeWithPartialLastChunk() throws IOException {
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    // Last chunk is one byte short of the others.
    byte[] lastChunk = Arrays.copyOf(inputChunks[inputChunks.length - 1], inputChunks[inputChunks.length - 1].length - 1);
    int inSize = chunkSize * (inputChunks.length - 1) + lastChunk.length;
    try (OzoneOutputStream out = bucket.createKey(keyName, inSize, new ECReplicationConfig(dataBlocks, parityBlocks, ECReplicationConfig.EcCodec.RS, chunkSize), new HashMap<>())) {
        for (int i = 0; i < inputChunks.length - 1; i++) {
            out.write(inputChunks[i]);
        }
        for (byte chunkData : lastChunk) {
            out.write(chunkData);
        }
    }
    try (OzoneInputStream is = bucket.readKey(keyName)) {
        byte[] fileContent = new byte[chunkSize];
        for (int i = 0; i < 2; i++) {
            assertEquals(inputChunks[i].length, is.read(fileContent));
            assertArrayEquals(inputChunks[i], fileContent);
        }
        assertEquals(lastChunk.length, is.read(fileContent));
        assertArrayEquals(lastChunk, Arrays.copyOf(fileContent, lastChunk.length));
        // A further read should give EOF
        assertEquals(-1, is.read(fileContent));
    }
}

@Test
public void test10D4PConfigWithPartialStripe() throws IOException {
    // A large block size try to trigger potential overflow
    // refer to: HDDS-6295
    conf.set(OzoneConfigKeys.OZONE_SCM_BLOCK_SIZE, OzoneConfigKeys.OZONE_SCM_BLOCK_SIZE_DEFAULT);
    int dataBlks = 10;
    int parityBlks = 4;
    MultiNodePipelineBlockAllocator blkAllocator = new MultiNodePipelineBlockAllocator(conf, dataBlks + parityBlks, 14);
    createNewClient(conf, blkAllocator);
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    // A partial chunk to trigger partialStripe check
    // in ECKeyOutputStream.close()
    int inSize = chunkSize - 1;
    byte[] partialChunk = new byte[inSize];
    try (OzoneOutputStream out = bucket.createKey(keyName, inSize, new ECReplicationConfig(dataBlks, parityBlks, ECReplicationConfig.EcCodec.RS, chunkSize), new HashMap<>())) {
        out.write(partialChunk);
    }
    try (OzoneInputStream is = bucket.readKey(keyName)) {
        byte[] fileContent = new byte[chunkSize];
        assertEquals(inSize, is.read(fileContent));
        assertArrayEquals(partialChunk, Arrays.copyOf(fileContent, inSize));
    }
}

