@Test
public void testClone() {
    OmBucketInfo omBucketInfo = OmBucketInfo.newBuilder().setBucketName("bucket").setVolumeName("vol1").setCreationTime(Time.now()).setIsVersionEnabled(false).setStorageType(StorageType.ARCHIVE).setAcls(Collections.singletonList(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "defaultUser", OzoneAcl.AclScope.ACCESS, IAccessAuthorizer.ACLType.WRITE_ACL))).build();
    /* Clone an omBucketInfo. */
    OmBucketInfo cloneBucketInfo = omBucketInfo.copyObject();
    assertNotSame(omBucketInfo, cloneBucketInfo);
    assertEquals(omBucketInfo, cloneBucketInfo, "Expected " + omBucketInfo + " and " + cloneBucketInfo + " to be equal");
    /* Reset acl & check not equal. */
    omBucketInfo.setAcls(Collections.singletonList(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "newUser", OzoneAcl.AclScope.ACCESS, IAccessAuthorizer.ACLType.WRITE_ACL)));
    assertNotEquals(omBucketInfo.getAcls().get(0), cloneBucketInfo.getAcls().get(0));
    /* Clone acl & check equal. */
    cloneBucketInfo = omBucketInfo.copyObject();
    assertEquals(omBucketInfo, cloneBucketInfo);
    assertEquals(omBucketInfo.getAcls().get(0), cloneBucketInfo.getAcls().get(0));
    /* Remove acl & check. */
    omBucketInfo.removeAcl(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "newUser", OzoneAcl.AclScope.ACCESS, IAccessAuthorizer.ACLType.WRITE_ACL));
    assertEquals(0, omBucketInfo.getAcls().size());
    assertEquals(1, cloneBucketInfo.getAcls().size());
}

