@Test
public void testClone() throws Exception {
    String volumeName = "vol1";
    String admin = "admin";
    String owner = UserGroupInformation.getCurrentUser().getUserName();
    OmVolumeArgs omVolumeArgs = new OmVolumeArgs.Builder().setVolume(volumeName).setAdminName(admin).setCreationTime(Time.now()).setOwnerName(owner).setObjectID(1L).setUpdateID(1L).setQuotaInBytes(Long.MAX_VALUE).addMetadata("key1", "value1").addMetadata("key2", "value2").addOzoneAcls(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "user1", ACCESS, IAccessAuthorizer.ACLType.READ)).build();
    OmVolumeArgs cloneVolumeArgs = omVolumeArgs.copyObject();
    assertEquals(omVolumeArgs, cloneVolumeArgs);
    // add user acl to write.
    omVolumeArgs.addAcl(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "user1", ACCESS, IAccessAuthorizer.ACLType.WRITE));
    // Now check clone acl
    assertNotEquals(cloneVolumeArgs.getAcls().get(0), omVolumeArgs.getAcls().get(0));
    // Set user acl to Write_ACL.
    omVolumeArgs.setAcls(Collections.singletonList(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "user1", ACCESS, IAccessAuthorizer.ACLType.WRITE_ACL)));
    assertNotEquals(cloneVolumeArgs.getAcls().get(0), omVolumeArgs.getAcls().get(0));
    // Now clone and check. It should have same as original acl.
    cloneVolumeArgs = (OmVolumeArgs) omVolumeArgs.copyObject();
    assertEquals(omVolumeArgs, cloneVolumeArgs);
    assertEquals(cloneVolumeArgs.getAcls().get(0), omVolumeArgs.getAcls().get(0));
    omVolumeArgs.removeAcl(OzoneAcl.of(IAccessAuthorizer.ACLIdentityType.USER, "user1", ACCESS, IAccessAuthorizer.ACLType.WRITE_ACL));
    // Removing acl, in original omVolumeArgs it should have no acls.
    assertEquals(0, omVolumeArgs.getAcls().size());
    assertEquals(1, cloneVolumeArgs.getAcls().size());
}

