@Test
void testBitSetToListConversion() {
    OzoneAcl acl = OzoneAcl.parseAcl("user:bilbo:rw");
    List<ACLType> rights = acl.getAclList();
    assertEquals(2, rights.size());
    assertTrue(rights.contains(READ));
