@Test
public void testEtagConsistencyAcrossListAndHead() throws Throwable {
    describe("Etag values must be non-empty and consistent across LIST and HEAD Calls.");
    final Path path = methodPath();
    final FileSystem fs = getFileSystem();
    Assertions.assertThat(fs.hasPathCapability(path, ETAGS_AVAILABLE)).describedAs("path capability %s of %s", ETAGS_AVAILABLE, path).isTrue();
    ContractTestUtils.touch(fs, path);
    final FileStatus st = fs.getFileStatus(path);
    final String etag = etagFromStatus(st);
    LOG.info("etag of empty file is \"{}\"", etag);
    final FileStatus[] statuses = fs.listStatus(path);
    Assertions.assertThat(statuses).describedAs("List(%s)", path).hasSize(1);
    final FileStatus lsStatus = statuses[0];
    Assertions.assertThat(etagFromStatus(lsStatus)).describedAs("etag of list status (%s) compared to HEAD value of %s", lsStatus, st).isEqualTo(etag);
}

