@Test
public void testTrash() throws Exception {
    String testKeyName = "testKey2";
    Path path = new Path(OZONE_URI_DELIMITER, testKeyName);
    ContractTestUtils.touch(fs, path);
    assertTrue(trash.getConf().getClass("fs.trash.classname", TrashPolicy.class).isAssignableFrom(OzoneTrashPolicy.class));
    assertEquals(TRASH_INTERVAL, trash.getConf().getFloat(OMConfigKeys.OZONE_FS_TRASH_INTERVAL_KEY, 0), 0);
    // Construct paths
    String username = UserGroupInformation.getCurrentUser().getShortUserName();
    Path userTrash = new Path(TRASH_ROOT, username);
    Path userTrashCurrent = new Path(userTrash, "Current");
    Path trashPath = new Path(userTrashCurrent, testKeyName);
    assertFalse(o3fs.exists(userTrash));
    // Call moveToTrash. We can't call protected fs.rename() directly
    trash.moveToTrash(path);
    assertTrue(o3fs.exists(userTrash));
    assertTrue(o3fs.exists(trashPath) || o3fs.listStatus(o3fs.listStatus(userTrash)[0].getPath()).length > 0);
    // Wait until the TrashEmptier purges the key
    GenericTestUtils.waitFor(() -> {
        try {
            return !o3fs.exists(trashPath);
        } catch (IOException e) {
            LOG.error("Delete from Trash Failed");
            fail("Delete from Trash Failed");
            return false;
        }
    }, 100, 120000);
    // wait for deletion of checkpoint dir
    GenericTestUtils.waitFor(() -> {
        try {
            return o3fs.listStatus(userTrash).length == 0;
        } catch (IOException e) {
            LOG.error("Delete from Trash Failed", e);
            fail("Delete from Trash Failed");
            return false;
        }
    }, 1000, 120000);
}

@Test
public void testListStatusOnLargeDirectoryForACLCheck() throws Exception {
    String keyName = "dir1/dir2/testListStatusOnLargeDirectoryForACLCheck";
    Path root = new Path(OZONE_URI_DELIMITER, keyName);
    Set<String> paths = new TreeSet<>();
    int numDirs = LISTING_PAGE_SIZE + LISTING_PAGE_SIZE / 2;
    for (int i = 0; i < numDirs; i++) {
        Path p = new Path(root, String.valueOf(i));
        getFs().mkdirs(p);
        paths.add(keyName + OM_KEY_PREFIX + p.getName());
    }
    // unknown keyName
    OMException ome = assertThrows(OMException.class, () -> new OzonePrefixPathImpl(getVolumeName(), getBucketName(), "invalidKey", cluster.getOzoneManager().getKeyManager()));
    assertEquals(KEY_NOT_FOUND, ome.getResult());
    OzonePrefixPathImpl ozonePrefixPath = new OzonePrefixPathImpl(getVolumeName(), getBucketName(), keyName, cluster.getOzoneManager().getKeyManager());
    OzoneFileStatus status = ozonePrefixPath.getOzoneFileStatus();
    assertNotNull(status);
    assertEquals(keyName, status.getTrimmedName());
    assertTrue(status.isDirectory());
    Iterator<? extends OzoneFileStatus> pathItr = ozonePrefixPath.getChildren(keyName);
    assertTrue(pathItr.hasNext(), "Failed to list keyPath:" + keyName);
    Set<String> actualPaths = new TreeSet<>();
    while (pathItr.hasNext()) {
        String pathname = pathItr.next().getTrimmedName();
        actualPaths.add(pathname);
        // no subpaths, expected an empty list
        Iterator<? extends OzoneFileStatus> subPathItr = ozonePrefixPath.getChildren(pathname);
        assertNotNull(subPathItr);
        assertFalse(subPathItr.hasNext(), "Failed to list keyPath: " + pathname);
    }
    assertEquals(paths.size(), actualPaths.size(), "ListStatus failed");
    for (String pathname : actualPaths) {
        paths.remove(pathname);
    }
    assertTrue(paths.isEmpty(), "ListStatus failed:" + paths);
}

