    ByteBuffer byteBuffer = ByteBuffer.allocate(bufferSize);
    try (OzoneOutputStream out = bucket.createKey(keyName, fileSize, ReplicationConfig.getDefault(CONF), new HashMap<>())) {
        for (int i = 0; i < count; i++) {
