    scmClient.recommissionNodes(ecMaintenance.stream().map(TestNodeUtil::getDNHostAndPort).collect(Collectors.toList()));
    // Ensure the 2 DNs go to IN_SERVICE
    for (DatanodeDetails dn : ecMaintenance) {
