@Test
public void testContainerChecksumForClosedContainer() throws Exception {
    // Create some keys to write data into the open containers
    ReplicationConfig repConfig = RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE);
    TestDataUtil.createKey(bucket, "key1", repConfig, "this is the content".getBytes(UTF_8));
    StorageContainerManager scm = cluster.getStorageContainerManager();
    ContainerInfo containerInfo1 = scm.getContainerManager().getContainers().get(0);
    // Checksum file doesn't exist before container close
    List<HddsDatanodeService> hddsDatanodes = cluster.getHddsDatanodes();
    for (HddsDatanodeService hddsDatanode : hddsDatanodes) {
        assertFalse(containerChecksumFileExists(hddsDatanode, containerInfo1.getContainerID()));
    }
    // Close container.
    OzoneTestUtils.closeContainer(scm, containerInfo1);
    ContainerProtos.ContainerChecksumInfo prevExpectedChecksumInfo1 = null;
    // Checksum file exists after container close and matches the expected container
    // merkle tree for all the datanodes
    for (HddsDatanodeService hddsDatanode : hddsDatanodes) {
        GenericTestUtils.waitFor(() -> checkContainerCloseInDatanode(hddsDatanode, containerInfo1) && containerChecksumFileExists(hddsDatanode, containerInfo1.getContainerID()), 100, 5000);
        OzoneContainer ozoneContainer = hddsDatanode.getDatanodeStateMachine().getContainer();
        Container<?> container1 = ozoneContainer.getController().getContainer(containerInfo1.getContainerID());
        ContainerProtos.ContainerChecksumInfo containerChecksumInfo = ContainerMerkleTreeTestUtils.readChecksumFile(container1.getContainerData());
        assertNotNull(containerChecksumInfo);
        if (prevExpectedChecksumInfo1 != null) {
            ContainerMerkleTreeTestUtils.assertTreesSortedAndMatch(prevExpectedChecksumInfo1.getContainerMerkleTree(), containerChecksumInfo.getContainerMerkleTree());
        }
        prevExpectedChecksumInfo1 = containerChecksumInfo;
    }
    // Create 2nd container and check the checksum doesn't match with 1st container
    TestDataUtil.createKey(bucket, "key2", repConfig, "this is the different content".getBytes(UTF_8));
    ContainerInfo containerInfo2 = scm.getContainerManager().getContainers().get(1);
    for (HddsDatanodeService hddsDatanode : hddsDatanodes) {
        assertFalse(containerChecksumFileExists(hddsDatanode, containerInfo2.getContainerID()));
    }
    // Close container.
    OzoneTestUtils.closeContainer(scm, containerInfo2);
    ContainerProtos.ContainerChecksumInfo prevExpectedChecksumInfo2 = null;
    // Checksum file exists after container close and matches the expected container
    // merkle tree for all the datanodes
    for (HddsDatanodeService hddsDatanode : hddsDatanodes) {
        GenericTestUtils.waitFor(() -> checkContainerCloseInDatanode(hddsDatanode, containerInfo2) && containerChecksumFileExists(hddsDatanode, containerInfo2.getContainerID()), 100, 5000);
        OzoneContainer ozoneContainer = hddsDatanode.getDatanodeStateMachine().getContainer();
        Container<?> container2 = ozoneContainer.getController().getContainer(containerInfo2.getContainerID());
        ContainerProtos.ContainerChecksumInfo containerChecksumInfo = ContainerMerkleTreeTestUtils.readChecksumFile(container2.getContainerData());
        assertNotNull(containerChecksumInfo);
        if (prevExpectedChecksumInfo2 != null) {
            ContainerMerkleTreeTestUtils.assertTreesSortedAndMatch(prevExpectedChecksumInfo2.getContainerMerkleTree(), containerChecksumInfo.getContainerMerkleTree());
        }
        prevExpectedChecksumInfo2 = containerChecksumInfo;
    }
    // Container merkle tree for different container should not match.
    assertNotEquals(prevExpectedChecksumInfo1.getContainerID(), prevExpectedChecksumInfo2.getContainerID());
    assertNotEquals(prevExpectedChecksumInfo1.getContainerMerkleTree().getDataChecksum(), prevExpectedChecksumInfo2.getContainerMerkleTree().getDataChecksum());
    // Wait for SCM to receive container reports with non-zero checksums for all replicas
    GenericTestUtils.waitFor(() -> getContainerReplicas(containerInfo1).stream().allMatch(r -> r.getDataChecksum() != 0), 200, 5000);
    GenericTestUtils.waitFor(() -> getContainerReplicas(containerInfo2).stream().allMatch(r -> r.getDataChecksum() != 0), 200, 5000);
}

@ParameterizedTest
@EnumSource(value = RaftProtos.ReplicationLevel.class, names = { "MAJORITY_COMMITTED", "ALL_COMMITTED" })
public void test2WayCommitForRetryfailure(RaftProtos.ReplicationLevel watchType) throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    RatisClientConfig ratisClientConfig = conf.getObject(RatisClientConfig.class);
    ratisClientConfig.setWatchType(watchType.toString());
    conf.setFromObject(ratisClientConfig);
    startCluster(conf);
    LogCapturer logCapturer = LogCapturer.captureLogs(XceiverClientRatis.class);
    XceiverClientManager clientManager = new XceiverClientManager(conf);
    ContainerWithPipeline container1 = storageContainerLocationClient.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, OzoneConsts.OZONE);
    XceiverClientSpi xceiverClient = clientManager.acquireClient(container1.getPipeline());
    assertEquals(1, xceiverClient.getRefcount());
    assertEquals(container1.getPipeline(), xceiverClient.getPipeline());
    Pipeline pipeline = xceiverClient.getPipeline();
    XceiverClientRatis ratisClient = (XceiverClientRatis) xceiverClient;
    XceiverClientReply reply = xceiverClient.sendCommandAsync(ContainerTestHelper.getCreateContainerRequest(container1.getContainerInfo().getContainerID(), xceiverClient.getPipeline()));
    reply.getResponse().get();
    assertEquals(3, ratisClient.getCommitInfoMap().size());
    // wait for the container to be created on all the nodes
    xceiverClient.watchForCommit(reply.getLogIndex()).get();
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        // shutdown the ratis follower
        if (RatisTestHelper.isRatisFollower(dn, pipeline)) {
            cluster.shutdownHddsDatanode(dn.getDatanodeDetails());
            break;
        }
    }
    reply = xceiverClient.sendCommandAsync(ContainerTestHelper.getCloseContainer(pipeline, container1.getContainerInfo().getContainerID()));
    reply.getResponse().get();
    xceiverClient.watchForCommit(reply.getLogIndex()).get();
    if (watchType == RaftProtos.ReplicationLevel.ALL_COMMITTED) {
        // commitInfo Map will be reduced to 2 here
        assertEquals(2, ratisClient.getCommitInfoMap().size());
        assertThat(logCapturer.getOutput()).contains("ALL_COMMITTED way commit failed");
        assertThat(logCapturer.getOutput()).contains("Committed by majority");
    } else {
        // there will still be 3 here for MAJORITY_COMMITTED
        assertEquals(3, ratisClient.getCommitInfoMap().size());
    }
    clientManager.releaseClient(xceiverClient, false);
    logCapturer.stopCapturing();
    shutdown();
}

@Test
void testContainerStateMachineIdempotency() throws Exception {
    ContainerWithPipeline container = storageClient.createContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE);
    long containerID = container.getContainerInfo().getContainerID();
    Pipeline pipeline = container.getPipeline();
    XceiverClientSpi client = xceiverClientManager.acquireClient(pipeline);
    // call create Container again
    BlockID blockID = ContainerTestHelper.getTestBlockID(containerID);
    byte[] data = RandomStringUtils.secure().next(RandomUtils.secure().randomInt(0, 1024)).getBytes(UTF_8);
    ContainerProtos.ContainerCommandRequestProto writeChunkRequest = ContainerTestHelper.getWriteChunkRequest(container.getPipeline(), blockID, data.length);
    client.sendCommand(writeChunkRequest);
    //Make the write chunk request again without requesting for overWrite
    client.sendCommand(writeChunkRequest);
    // Now, explicitly make a putKey request for the block.
    ContainerProtos.ContainerCommandRequestProto putKeyRequest = ContainerTestHelper.getPutBlockRequest(pipeline, writeChunkRequest.getWriteChunk());
    client.sendCommand(putKeyRequest);
    // send the putBlock again
    client.sendCommand(putKeyRequest);
    // close container call
    ContainerProtocolCalls.closeContainer(client, containerID, null);
    ContainerProtocolCalls.closeContainer(client, containerID, null);
    xceiverClientManager.releaseClient(client, false);
}

