    exception = assertThrows(IllegalArgumentException.class, () -> store.getVolume(volumeName).setQuota(OzoneQuota.parseQuota("0GB", "10")));
    assertTrue(exception.getMessage().startsWith("Invalid value for space quota"));
    exception = assertThrows(IllegalArgumentException.class, () -> store.getVolume(volumeName).setQuota(OzoneQuota.parseQuota("10GB", "0")));
    assertTrue(exception.getMessage().startsWith("Invalid value for namespace quota"));
    // The unit should be legal.
    exception = assertThrows(IllegalArgumentException.class, () -> store.getVolume(volumeName).setQuota(OzoneQuota.parseQuota("1TEST", "1000")));
    assertTrue(exception.getMessage().startsWith("1TEST is invalid."));
    // The setting value cannot be greater than LONG.MAX_VALUE BYTES.
    exception = assertThrows(IllegalArgumentException.class, () -> store.getVolume(volumeName).setQuota(OzoneQuota.parseQuota("9223372036854775808 B", "1000")));
    assertTrue(exception.getMessage().startsWith("9223372036854775808 B is invalid."));
    // The value cannot be negative.
    exception = assertThrows(IllegalArgumentException.class, () -> store.getVolume(volumeName).setQuota(OzoneQuota.parseQuota("-10GB", "1000")));
    assertTrue(exception.getMessage().startsWith("Invalid value for space quota"));
}

