        key.close();
    }
    RatisServerConfiguration ratisServerConfiguration = conf.getObject(RatisServerConfiguration.class);
    Path parentPath = getSnapshotPath(storage).getParent();
    assertThat(parentPath).isNotNull();
    File[] files = parentPath.toFile().listFiles();
    assertThat(files).isNotNull();
    int numSnapshots = files.length;
    assertThat(Math.abs(ratisServerConfiguration.getNumSnapshotsRetained() - numSnapshots)).isLessThanOrEqualTo(1);
    // Write 10 more keys. Num Snapshots should remain the same.
    for (int i = 11; i <= 20; i++) {
        OzoneOutputStream key = objectStore.getVolume(volumeName).getBucket(bucketName).createKey(("ratis" + i), 1024, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.ONE), new HashMap<>());
