@ParameterizedTest
@ValueSource(booleans = { false, true })
public void testFileRecovery(boolean forceRecovery) throws Exception {
    OzoneConfiguration conf = getCluster().getConf();
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = "sample value";
    getStore().createVolume(volumeName);
    OzoneVolume volume = getStore().getVolume(volumeName);
    volume.createBucket(bucketName, new BucketArgs.Builder().setBucketLayout(FILE_SYSTEM_OPTIMIZED).build());
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    final String dir = OZONE_ROOT + bucket.getVolumeName() + OZONE_URI_DELIMITER + bucket.getName();
    final Path file = new Path(dir, keyName);
    // Set the fs.defaultFS
    final String rootPath = String.format("%s://%s/", OZONE_OFS_URI_SCHEME, conf.get(OZONE_OM_ADDRESS_KEY));
    conf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    // force recovery file
    System.setProperty(FORCE_LEASE_RECOVERY_ENV, String.valueOf(forceRecovery));
    conf.setBoolean(String.format("fs.%s.impl.disable.cache", OZONE_OFS_URI_SCHEME), true);
    try (RootedOzoneFileSystem fs = (RootedOzoneFileSystem) FileSystem.get(conf)) {
        OzoneOutputStream out = null;
        try {
            out = bucket.createKey(keyName, value.getBytes(UTF_8).length, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
            out.write(value.getBytes(UTF_8));
            out.hsync();
            if (forceRecovery) {
                fs.recoverLease(file);
            } else {
                assertThrows(OMException.class, () -> fs.recoverLease(file));
            }
        } finally {
            if (out != null) {
                if (forceRecovery) {
                    // close failure because the key is already committed
                    assertThrows(OMException.class, out::close);
                } else {
                    out.close();
                }
            }
        }
    }
}

@ParameterizedTest
@ValueSource(ints = { 1 << 24, (1 << 24) + 1, (1 << 24) - 1 })
public void testPreallocateFileRecovery(long dataSize) throws Exception {
    OzoneConfiguration conf = getCluster().getConf();
    cleanupDeletedTable(getCluster().getOzoneManager());
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    final byte[] data = new byte[(int) dataSize];
    ThreadLocalRandom.current().nextBytes(data);
    getStore().createVolume(volumeName);
    OzoneVolume volume = getStore().getVolume(volumeName);
    long nsQuota = 100;
    long spaceQuota = 1 * 1024 * 1024 * 1024;
    volume.createBucket(bucketName, new BucketArgs.Builder().setBucketLayout(FILE_SYSTEM_OPTIMIZED).setQuotaInNamespace(nsQuota).setQuotaInBytes(spaceQuota).build());
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    final String dir = OZONE_ROOT + bucket.getVolumeName() + OZONE_URI_DELIMITER + bucket.getName();
    final Path file = new Path(dir, keyName);
    // Set the fs.defaultFS
    final String rootPath = String.format("%s://%s/", OZONE_OFS_URI_SCHEME, conf.get(OZONE_OM_ADDRESS_KEY));
    conf.set(CommonConfigurationKeysPublic.FS_DEFAULT_NAME_KEY, rootPath);
    try (RootedOzoneFileSystem fs = (RootedOzoneFileSystem) FileSystem.get(conf)) {
        OzoneOutputStream out = null;
        long totalBlock = 10;
        long usedBlock = (dataSize - 1) / fs.getDefaultBlockSize() + 1;
        long fileSize = fs.getDefaultBlockSize() * totalBlock;
        OMMetrics metrics = getCluster().getOzoneManager().getMetrics();
        long committedBytes = metrics.getDataCommittedBytes();
        try {
            out = bucket.createKey(keyName, fileSize, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
            // init used quota check
            bucket = volume.getBucket(bucketName);
            assertEquals(0, bucket.getUsedNamespace());
            assertEquals(0, bucket.getUsedBytes());
            out.write(data);
            out.hsync();
            fs.recoverLease(file);
            // check file length
            FileStatus fileStatus = fs.getFileStatus(file);
            assertEquals(dataSize, fileStatus.getLen());
            // check committed bytes
            assertEquals(committedBytes + dataSize, getCluster().getOzoneManager().getMetrics().getDataCommittedBytes());
            // check used quota
            GenericTestUtils.waitFor((CheckedSupplier<Boolean, ? extends Exception>) () -> 1 == volume.getBucket(bucketName).getUsedNamespace(), 1000, 30000);
            GenericTestUtils.waitFor((CheckedSupplier<Boolean, ? extends Exception>) () -> dataSize * ReplicationFactor.THREE.getValue() == volume.getBucket(bucketName).getUsedBytes(), 1000, 30000);
            // check unused pre-allocated blocks are reclaimed
            Table<String, RepeatedOmKeyInfo> deletedTable = getCluster().getOzoneManager().getMetadataManager().getDeletedTable();
            try (Table.KeyValueIterator<String, RepeatedOmKeyInfo> keyIter = deletedTable.iterator()) {
                while (keyIter.hasNext()) {
                    Table.KeyValue<String, RepeatedOmKeyInfo> kv = keyIter.next();
                    OmKeyInfo key = kv.getValue().getOmKeyInfoList().get(0);
                    assertEquals(totalBlock - usedBlock, key.getKeyLocationVersions().get(0).getLocationListCount());
                }
            }
        } finally {
            if (out != null) {
                // close failure because the key is already committed
                assertThrows(OMException.class, out::close);
            }
        }
    }
}

@Test
public void testS3Auth() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String strToSign = "AWS4-HMAC-SHA256\n" + "20150830T123600Z\n" + "20150830/us-east-1/iam/aws4_request\n" + "f536975d06c0309214f805bb90ccff089219ecd68b2" + "577efef23edd43b7e1a59";
    String signature = "5d672d79c15b13162d9279b0855cfba" + "6789a8edb4c82c400e06b5924a6f2b5d7";
    String secret = "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY";
    String accessKey = UserGroupInformation.getCurrentUser().getUserName();
    S3SecretManager s3SecretManager = getCluster().getOzoneManager().getS3SecretManager();
    // Add secret to S3Secret table.
    s3SecretManager.storeSecret(accessKey, S3SecretValue.of(accessKey, secret));
    OMRequest writeRequest = OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.CreateVolume).setVersion(ClientVersion.CURRENT_VERSION).setClientId(UUID.randomUUID().toString()).setCreateVolumeRequest(CreateVolumeRequest.newBuilder().setVolumeInfo(VolumeInfo.newBuilder().setVolume(volumeName).setAdminName(accessKey).setOwnerName(accessKey).build()).build()).setS3Authentication(S3Authentication.newBuilder().setAccessId(accessKey).setSignature(signature).setStringToSign(strToSign)).build();
    GenericTestUtils.waitFor(() -> getCluster().getOzoneManager().isLeaderReady(), 100, 120000);
    OMResponse omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, writeRequest);
    // Verify response.
    assertEquals(Status.OK, omResponse.getStatus());
    // Read Request
    OMRequest readRequest = OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.InfoVolume).setVersion(ClientVersion.CURRENT_VERSION).setClientId(UUID.randomUUID().toString()).setInfoVolumeRequest(InfoVolumeRequest.newBuilder().setVolumeName(volumeName).build()).setS3Authentication(S3Authentication.newBuilder().setAccessId(accessKey).setSignature(signature).setStringToSign(strToSign)).build();
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, readRequest);
    // Verify response.
    assertEquals(Status.OK, omResponse.getStatus());
    VolumeInfo volumeInfo = omResponse.getInfoVolumeResponse().getVolumeInfo();
    assertNotNull(volumeInfo);
    assertEquals(volumeName, volumeInfo.getVolume());
    assertEquals(accessKey, volumeInfo.getAdminName());
    assertEquals(accessKey, volumeInfo.getOwnerName());
    // Override secret to S3Secret store with some dummy value
    s3SecretManager.storeSecret(accessKey, S3SecretValue.of(accessKey, "dummy"));
    // Write request with invalid credentials.
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, writeRequest);
    assertEquals(Status.INVALID_TOKEN, omResponse.getStatus());
    // Read request with invalid credentials.
    omResponse = getCluster().getOzoneManager().getOmServerProtocol().submitRequest(null, readRequest);
    assertEquals(Status.INVALID_TOKEN, omResponse.getStatus());
}

