@Test
public void testValidateBCSIDOnDnRestart() throws Exception {
    OzoneOutputStream key = objectStore.getVolume(volumeName).getBucket(bucketName).createKey("ratis", 1024, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.ONE), new HashMap<>());
    // First write and flush creates a container in the datanode
    key.write("ratis".getBytes(UTF_8));
    key.flush();
    key.write("ratis".getBytes(UTF_8));
    KeyOutputStream groupOutputStream = (KeyOutputStream) key.getOutputStream();
    List<OmKeyLocationInfo> locationInfoList = groupOutputStream.getLocationInfoList();
    assertEquals(1, locationInfoList.size());
    OmKeyLocationInfo omKeyLocationInfo = locationInfoList.get(0);
    HddsDatanodeService dn = TestHelper.getDatanodeService(omKeyLocationInfo, cluster);
    ContainerData containerData = TestHelper.getDatanodeService(omKeyLocationInfo, cluster).getDatanodeStateMachine().getContainer().getContainerSet().getContainer(omKeyLocationInfo.getContainerID()).getContainerData();
    KeyValueContainerData keyValueContainerData = assertInstanceOf(KeyValueContainerData.class, containerData);
    key.close();
    long containerID = omKeyLocationInfo.getContainerID();
    int index = cluster.getHddsDatanodeIndex(dn.getDatanodeDetails());
    // delete the container db file
    FileUtil.fullyDelete(new File(keyValueContainerData.getContainerPath()));
    HddsDatanodeService dnService = cluster.getHddsDatanodes().get(index);
    OzoneContainer ozoneContainer = dnService.getDatanodeStateMachine().getContainer();
    ozoneContainer.getContainerSet().removeContainer(containerID);
    ContainerStateMachine stateMachine = (ContainerStateMachine) TestHelper.getStateMachine(cluster.getHddsDatanodes().get(index), omKeyLocationInfo.getPipeline());
    SimpleStateMachineStorage storage = (SimpleStateMachineStorage) stateMachine.getStateMachineStorage();
    stateMachine.takeSnapshot();
    final Path parentPath = StatemachineImplTestUtil.findLatestSnapshot(storage).getFile().getPath();
    stateMachine.buildMissingContainerSet(parentPath.toFile());
    // Since the snapshot threshold is set to 1, since there are
    // applyTransactions, we should see snapshots
    assertThat(parentPath.getParent().toFile().listFiles().length).isGreaterThan(0);
    // make sure the missing containerSet is not empty
    HddsDispatcher dispatcher = (HddsDispatcher) ozoneContainer.getDispatcher();
    assertThat(dispatcher.getMissingContainerSet()).isNotEmpty();
    assertThat(dispatcher.getMissingContainerSet()).contains(containerID);
    // write a new key
    key = objectStore.getVolume(volumeName).getBucket(bucketName).createKey("ratis", 1024, ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.ONE), new HashMap<>());
    // First write and flush creates a container in the datanode
    key.write("ratis1".getBytes(UTF_8));
    key.flush();
    groupOutputStream = (KeyOutputStream) key.getOutputStream();
    locationInfoList = groupOutputStream.getLocationInfoList();
    assertEquals(1, locationInfoList.size());
    omKeyLocationInfo = locationInfoList.get(0);
    key.close();
    containerID = omKeyLocationInfo.getContainerID();
    dn = TestHelper.getDatanodeService(omKeyLocationInfo, cluster);
    containerData = dn.getDatanodeStateMachine().getContainer().getContainerSet().getContainer(omKeyLocationInfo.getContainerID()).getContainerData();
    keyValueContainerData = assertInstanceOf(KeyValueContainerData.class, containerData);
    try (DBHandle db = BlockUtils.getDB(keyValueContainerData, conf)) {
        // modify the bcsid for the container in the ROCKS DB thereby inducing
        // corruption
        db.getStore().getMetadataTable().put(keyValueContainerData.getBcsIdKey(), 0L);
    }
    // after the restart, there will be a mismatch in BCSID of what is recorded
    // in the and what is there in RockSDB and hence the container would be
    // marked unhealthy
    index = cluster.getHddsDatanodeIndex(dn.getDatanodeDetails());
    cluster.restartHddsDatanode(dn.getDatanodeDetails(), true);
    // Make sure the container is marked unhealthy
    assertSame(cluster.getHddsDatanodes().get(index).getDatanodeStateMachine().getContainer().getContainerSet().getContainer(containerID).getContainerState(), ContainerProtos.ContainerDataProto.State.UNHEALTHY);
}

@ParameterizedTest
@MethodSource("replicationConfigs")
@Flaky("HDDS-9962")
public void testBlockDeletion(ReplicationConfig repConfig) throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    LogCapturer logCapturer = LogCapturer.captureLogs(DeleteBlocksCommandHandler.class);
    String value = RandomStringUtils.secure().next(1024 * 1024);
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    OzoneOutputStream out = bucket.createKey(keyName, value.getBytes(UTF_8).length, repConfig, new HashMap<>());
    for (int i = 0; i < 10; i++) {
        out.write(value.getBytes(UTF_8));
    }
    out.close();
    OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(keyName).setDataSize(0).setReplicationConfig(repConfig).build();
    List<OmKeyLocationInfoGroup> omKeyLocationInfoGroupList = om.lookupKey(keyArgs).getKeyLocationVersions();
    // verify key blocks were created in DN.
    GenericTestUtils.waitFor(() -> {
        try {
            scm.getScmHAManager().asSCMHADBTransactionBuffer().flush();
            verifyBlocksCreated(omKeyLocationInfoGroupList);
            return true;
        } catch (Throwable t) {
            LOG.warn("Verify blocks creation failed", t);
            return false;
        }
    }, 1000, 10000);
    // No containers with deleted blocks
    assertThat(containerIdsWithDeletedBlocks).isEmpty();
    // Delete transactionIds for the containers should be 0.
    // NOTE: this test assumes that all the container is KetValueContainer. If
    // other container types is going to be added, this test should be checked.
    matchContainerTransactionIds();
    assertEquals(0L, metrics.getNumBlockDeletionTransactionCreated());
    writeClient.deleteKey(keyArgs);
    Thread.sleep(5000);
    // The blocks should not be deleted in the DN as the container is open
    Throwable e = assertThrows(AssertionError.class, () -> verifyBlocksDeleted(omKeyLocationInfoGroupList));
    assertTrue(e.getMessage().startsWith("expected: <null> but was:"));
    assertEquals(0L, metrics.getNumBlockDeletionTransactionsOnDatanodes());
    // close the containers which hold the blocks for the key
    OzoneTestUtils.closeAllContainers(scm.getEventQueue(), scm);
    // If any container present as not closed, i.e. matches some entry
    // not closed, then return false for wait
    ContainerSet containerSet = cluster.getHddsDatanodes().get(0).getDatanodeStateMachine().getContainer().getContainerSet();
    GenericTestUtils.waitFor(() -> {
        return !(omKeyLocationInfoGroupList.stream().anyMatch((group) -> group.getLocationList().stream().anyMatch((info) -> containerSet.getContainer(info.getContainerID()).getContainerData().getState() != ContainerProtos.ContainerDataProto.State.CLOSED)));
    }, 1000, 30000);
    // The blocks should be deleted in the DN.
    GenericTestUtils.waitFor(() -> {
        try {
            scm.getScmHAManager().asSCMHADBTransactionBuffer().flush();
            verifyBlocksDeleted(omKeyLocationInfoGroupList);
            return true;
        } catch (Throwable t) {
            LOG.warn("Verify blocks deletion failed", t);
            return false;
        }
    }, 2000, 30000);
    // Few containers with deleted blocks
    assertThat(containerIdsWithDeletedBlocks).isNotEmpty();
    // Containers in the DN and SCM should have same delete transactionIds
    matchContainerTransactionIds();
    // Verify transactions committed
    GenericTestUtils.waitFor(() -> {
        try {
            scm.getScmHAManager().asSCMHADBTransactionBuffer().flush();
            verifyTransactionsCommitted();
            return true;
        } catch (Throwable t) {
            LOG.warn("Container closing failed", t);
            return false;
        }
    }, 500, 10000);
    // Containers in the DN and SCM should have same delete transactionIds
    // after DN restart. The assertion is just to verify that the state of
    // containerInfos in dn and scm is consistent after dn restart.
    cluster.restartHddsDatanode(0, true);
    matchContainerTransactionIds();
    assertEquals(metrics.getNumBlockDeletionTransactionCreated(), metrics.getNumBlockDeletionTransactionCompleted());
    assertEquals(metrics.getNumBlockDeletionCommandSent(), metrics.getNumCommandsDatanodeSent());
    assertEquals(metrics.getNumBlockDeletionCommandSuccess(), metrics.getNumCommandsDatanodeSuccess());
    assertEquals(metrics.getBNumBlockDeletionCommandFailure(), metrics.getNumCommandsDatanodeFailed());
    assertThat(metrics.getNumBlockDeletionCommandSent()).isGreaterThanOrEqualTo(metrics.getNumBlockDeletionCommandSuccess() + metrics.getBNumBlockDeletionCommandFailure());
    assertThat(metrics.getNumBlockDeletionTransactionsOnDatanodes()).isGreaterThanOrEqualTo(metrics.getNumBlockDeletionTransactionFailureOnDatanodes() + metrics.getNumBlockDeletionTransactionSuccessOnDatanodes());
    LOG.info(metrics.toString());
    // Datanode should receive retried requests with continuous retry counts.
    for (int i = 5; i >= 0; i--) {
        if (logCapturer.getOutput().contains("1(" + i + ")")) {
            for (int j = 0; j <= i; j++) {
                assertThat(logCapturer.getOutput()).contains("1(" + i + ")");
            }
            break;
        }
    }
}

