public void testContainerStateAfterDNRestart() throws Exception {
    ReplicationManager replicationManager = scm.getReplicationManager();
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = RandomStringUtils.secure().next(10 * 10);
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    OzoneOutputStream out = bucket.createKey(keyName, value.getBytes(UTF_8).length, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
    out.write(value.getBytes(UTF_8));
    out.close();
    OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName(volumeName).setBucketName(bucketName).setKeyName(keyName).setDataSize(0).setReplicationConfig(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE)).build();
    List<OmKeyLocationInfoGroup> omKeyLocationInfoGroupList = om.lookupKey(keyArgs).getKeyLocationVersions();
    Thread.sleep(5000);
    List<ContainerInfo> containerInfos = scm.getContainerManager().getContainers();
    final int valueSize = value.getBytes(UTF_8).length;
    final int keyCount = 1;
    List<Long> containerIdList = new ArrayList<>();
    containerInfos.stream().forEach(container -> {
        assertEquals(valueSize, container.getUsedBytes());
        assertEquals(keyCount, container.getNumberOfKeys());
        containerIdList.add(container.getContainerID());
    });
    OzoneTestUtils.closeAllContainers(scm.getEventQueue(), scm);
    // Wait for container to close
    TestHelper.waitForContainerClose(cluster, containerIdList.toArray(new Long[0]));
    // make sure the containers are closed on the dn
    omKeyLocationInfoGroupList.forEach((group) -> {
        List<OmKeyLocationInfo> locationInfo = group.getLocationList();
        locationInfo.forEach((info) -> cluster.getHddsDatanodes().get(0).getDatanodeStateMachine().getContainer().getContainerSet().getContainer(info.getContainerID()).getContainerData().setState(ContainerProtos.ContainerDataProto.State.CLOSED));
    });
    ContainerID containerId = ContainerID.valueOf(containerInfos.get(0).getContainerID());
    // Before restart container state is non-empty
    assertFalse(getContainerFromDN(cluster.getHddsDatanodes().get(0), containerId.getId()).getContainerData().isEmpty());
    // Restart DataNode
    cluster.restartHddsDatanode(0, true);
    // After restart also container state remains non-empty.
    assertFalse(getContainerFromDN(cluster.getHddsDatanodes().get(0), containerId.getId()).getContainerData().isEmpty());
    // Delete key
    writeClient.deleteKey(keyArgs);
    Thread.sleep(10000);
    GenericTestUtils.waitFor(() -> {
        try {
            scm.getScmHAManager().asSCMHADBTransactionBuffer().flush();
            return scm.getContainerManager().getContainerReplicas(containerId).stream().allMatch(replica -> replica.isEmpty());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }, 100, 10 * 1000);
    // Container state should be empty now as key got deleted
    assertTrue(getContainerFromDN(cluster.getHddsDatanodes().get(0), containerId.getId()).getContainerData().isEmpty());
    // Restart DataNode
    cluster.restartHddsDatanode(0, true);
    // Container state should be empty even after restart
    assertTrue(getContainerFromDN(cluster.getHddsDatanodes().get(0), containerId.getId()).getContainerData().isEmpty());
    GenericTestUtils.waitFor(() -> {
        replicationManager.processAll();
        ((EventQueue) scm.getEventQueue()).processAll(1000);
        List<ContainerInfo> infos = scm.getContainerManager().getContainers();
        try {
            infos.stream().forEach(container -> {
                assertEquals(HddsProtos.LifeCycleState.DELETED, container.getState());
                try {
                    scm.getScmHAManager().asSCMHADBTransactionBuffer().flush();
                    assertEquals(HddsProtos.LifeCycleState.DELETED, scm.getScmMetadataStore().getContainerTable().get(container.containerID()).getState());
                } catch (IOException e) {
                    fail("Container from SCM DB should be marked as DELETED");
                }
            });
        } catch (Throwable e) {
            LOG.info(e.getMessage());
            return false;
        }
        return true;
    }, 500, 30000);
}

