@Test
public void testCloseContainerViaRatis() throws IOException, TimeoutException, InterruptedException {
    OzoneOutputStream key = objectStore.getVolume("test").getBucket("test").createKey("ratis", 1024, ReplicationType.RATIS, ReplicationFactor.THREE, new HashMap<>());
    key.write("ratis".getBytes(UTF_8));
    key.close();
    //get the name of a valid container
    OmKeyArgs keyArgs = new OmKeyArgs.Builder().setVolumeName("test").setBucketName("test").setReplicationConfig(RatisReplicationConfig.getInstance(THREE)).setDataSize(1024).setKeyName("ratis").build();
    OmKeyLocationInfo omKeyLocationInfo = cluster.getOzoneManager().lookupKey(keyArgs).getKeyLocationVersions().get(0).getBlocksLatestVersionOnly().get(0);
    long containerID = omKeyLocationInfo.getContainerID();
    ContainerInfo container = cluster.getStorageContainerManager().getContainerManager().getContainer(ContainerID.valueOf(containerID));
    Pipeline pipeline = cluster.getStorageContainerManager().getPipelineManager().getPipeline(container.getPipelineID());
    List<DatanodeDetails> datanodes = pipeline.getNodes();
    assertEquals(3, datanodes.size());
    List<DBHandle> metadataStores = new ArrayList<>(datanodes.size());
    for (DatanodeDetails details : datanodes) {
        assertFalse(isContainerClosed(cluster, containerID, details));
        //send the order to close the container
        SCMCommand<?> command = new CloseContainerCommand(containerID, pipeline.getId());
        command.setTerm(cluster.getStorageContainerManager().getScmContext().getTermOfLeader());
        cluster.getStorageContainerManager().getScmNodeManager().addDatanodeCommand(details.getID(), command);
        int index = cluster.getHddsDatanodeIndex(details);
        Container dnContainer = cluster.getHddsDatanodes().get(index).getDatanodeStateMachine().getContainer().getContainerSet().getContainer(containerID);
        try (DBHandle store = BlockUtils.getDB((KeyValueContainerData) dnContainer.getContainerData(), conf)) {
            metadataStores.add(store);
        }
    }
    // There should be as many rocks db as the number of datanodes in pipeline.
    assertEquals(datanodes.size(), metadataStores.stream().distinct().count());
    // Make sure that it is CLOSED
    for (DatanodeDetails datanodeDetails : datanodes) {
        GenericTestUtils.waitFor(() -> isContainerClosed(cluster, containerID, datanodeDetails), 500, 15 * 1000);
        //double check if it's really closed (waitFor also throws an exception)
        assertTrue(isContainerClosed(cluster, containerID, datanodeDetails));
    }
}

