public void testECContainerRecoveryWithTimedOutRecovery() throws Exception {
    byte[] inputData = getInputBytes(3);
    final OzoneBucket bucket = getOzoneBucket();
    String keyName = UUID.randomUUID().toString();
    final Pipeline pipeline;
    ECReplicationConfig repConfig = new ECReplicationConfig(3, 2, ECReplicationConfig.EcCodec.RS, CHUNK_SIZE);
    try (OzoneOutputStream out = bucket.createKey(keyName, 1024, repConfig, new HashMap<>())) {
        out.write(inputData);
        pipeline = ((ECKeyOutputStream) out.getOutputStream()).getStreamEntries().get(0).getPipeline();
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    List<ContainerInfo> containers = cluster.getStorageContainerManager().getContainerManager().getContainers();
    ContainerInfo container = null;
    for (ContainerInfo info : containers) {
        if (info.getPipelineID().getId().equals(pipeline.getId().getId())) {
            container = info;
        }
    }
    StorageContainerManager scm = cluster.getStorageContainerManager();
    AtomicReference<HddsDatanodeService> reconstructedDN = new AtomicReference<>();
    ContainerInfo finalContainer = container;
    Map<HddsDatanodeService, Long> recoveryTimeoutMap = new HashMap<>();
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        recoveryTimeoutMap.put(dn, dn.getDatanodeStateMachine().getConf().getTimeDuration(OZONE_RECOVERING_CONTAINER_TIMEOUT, OZONE_RECOVERING_CONTAINER_TIMEOUT_DEFAULT, TimeUnit.MILLISECONDS));
        dn.getDatanodeStateMachine().getContainer().getContainerSet().setRecoveringTimeout(100);
        ReconstructECContainersCommandHandler handler = GenericTestUtils.getFieldReflection(dn.getDatanodeStateMachine(), "reconstructECContainersCommandHandler");
        ECReconstructionCoordinator coordinator = GenericTestUtils.mockFieldReflection(handler, "coordinator");
        doAnswer(invocation -> {
            GenericTestUtils.waitFor(() -> dn.getDatanodeStateMachine().getContainer().getContainerSet().getContainer(finalContainer.getContainerID()).getContainerState() == ContainerProtos.ContainerDataProto.State.UNHEALTHY, 1000, 100000);
            reconstructedDN.set(dn);
            invocation.callRealMethod();
            return null;
        }).when(coordinator).reconstructECBlockGroup(any(), any(), any(), any());
    }
    // Shutting down DN triggers close pipeline and close container.
    cluster.shutdownHddsDatanode(pipeline.getFirstNode());
    // Make sure container closed.
    waitForSCMContainerState(StorageContainerDatanodeProtocolProtos.ContainerReplicaProto.State.CLOSED, container.containerID());
    //Temporarily stop the RM process.
    scm.getReplicationManager().stop();
    waitForReplicationManagerStopped(scm.getReplicationManager());
    // Wait for the lower replication.
    waitForContainerCount(4, container.containerID(), scm);
    // Start the RM to resume the replication process and wait for the
    // reconstruction.
    scm.getReplicationManager().start();
    GenericTestUtils.waitFor(() -> reconstructedDN.get() != null, 10000, 100000);
    GenericTestUtils.waitFor(() -> reconstructedDN.get().getDatanodeStateMachine().getContainer().getContainerSet().getContainer(finalContainer.getContainerID()) == null, 10000, 100000);
    for (HddsDatanodeService dn : cluster.getHddsDatanodes()) {
        dn.getDatanodeStateMachine().getContainer().getContainerSet().setRecoveringTimeout(recoveryTimeoutMap.get(dn));
    }
}

