/**
 * {@link BackgroundContainerDataScanner} should detect corrupted blocks
 * in a closed container without client interaction.
 */
@ParameterizedTest
// Background container data scanner should be able to detect all errors.
@EnumSource
void testCorruptionDetected(TestContainerCorruptions corruption) throws Exception {
    pauseScanner();
    long containerID = writeDataThenCloseContainer();
    // Container corruption has not yet been introduced.
    Container<?> container = getDnContainer(containerID);
    assertEquals(State.CLOSED, container.getContainerState());
    assertTrue(containerChecksumFileExists(containerID));
    assertFalse(container.getContainerData().needsDataChecksum());
    assertNotEquals(0, container.getContainerData().getDataChecksum());
    waitForScmToSeeReplicaState(containerID, CLOSED);
    long initialReportedDataChecksum = getContainerReplica(containerID).getDataChecksum();
    assertNotEquals(0, initialReportedDataChecksum);
    corruption.applyTo(container);
    resumeScanner();
    // Wait for the scanner to detect corruption.
    GenericTestUtils.waitFor(() -> container.getContainerState() == State.UNHEALTHY, 500, 15_000);
    // Wait for SCM to get a report of the unhealthy replica with a different checksum than before.
    waitForScmToSeeReplicaState(containerID, UNHEALTHY);
    long newReportedDataChecksum = getContainerReplica(containerID).getDataChecksum();
    if (corruption == TestContainerCorruptions.MISSING_METADATA_DIR || corruption == TestContainerCorruptions.MISSING_CONTAINER_DIR) {
        // In these cases, the new tree will not be able to be written since it exists in the metadata directory.
        // When the tree write fails, the in-memory checksum should remain at its original value.
        assertEquals(checksumToString(initialReportedDataChecksum), checksumToString(newReportedDataChecksum));
    } else {
        assertNotEquals(checksumToString(initialReportedDataChecksum), checksumToString(newReportedDataChecksum));
        // Test that the scanner wrote updated checksum info to the disk.
        assertReplicaChecksumMatches(container, newReportedDataChecksum);
        assertFalse(container.getContainerData().needsDataChecksum());
        KeyValueContainerData containerData = (KeyValueContainerData) container.getContainerData();
        verifyAllDataChecksumsMatch(containerData, getConf());
    }
    if (corruption == TestContainerCorruptions.TRUNCATED_BLOCK || corruption == TestContainerCorruptions.CORRUPT_BLOCK) {
        // These errors will affect multiple chunks and result in multiple log messages.
        corruption.assertLogged(containerID, getContainerLogCapturer());
    } else {
        // Other corruption types will only lead to a single error.
        corruption.assertLogged(containerID, 1, getContainerLogCapturer());
    }
}

/**
 * {@link BackgroundContainerMetadataScanner} should detect corrupted metadata
 * in open or closed containers without client interaction.
 */
@ParameterizedTest
@MethodSource("supportedCorruptionTypes")
void testCorruptionDetected(TestContainerCorruptions corruption) throws Exception {
    // Write data to an open and closed container.
    long closedContainerID = writeDataThenCloseContainer();
    Container<?> closedContainer = getDnContainer(closedContainerID);
    assertEquals(State.CLOSED, closedContainer.getContainerState());
    assertTrue(containerChecksumFileExists(closedContainerID));
    waitForScmToSeeReplicaState(closedContainerID, CLOSED);
    long initialClosedChecksum = getContainerReplica(closedContainerID).getDataChecksum();
    assertNotEquals(0, initialClosedChecksum);
    long openContainerID = writeDataToOpenContainer();
    Container<?> openContainer = getDnContainer(openContainerID);
    assertEquals(State.OPEN, openContainer.getContainerState());
    waitForScmToSeeReplicaState(openContainerID, OPEN);
    // Open containers should not yet have a checksum generated.
    assertEquals(0, getContainerReplica(openContainerID).getDataChecksum());
    // Corrupt both containers.
    corruption.applyTo(closedContainer);
    corruption.applyTo(openContainer);
    // Wait for the scanner to detect corruption.
    GenericTestUtils.waitFor(() -> closedContainer.getContainerState() == State.UNHEALTHY, 500, 5000);
    GenericTestUtils.waitFor(() -> openContainer.getContainerState() == State.UNHEALTHY, 500, 5000);
    // Wait for SCM to get reports of the unhealthy replicas.
    // The metadata scanner does not generate data checksums and the other scanners have been turned off for this
    // test, so the data checksums should not change.
    waitForScmToSeeReplicaState(closedContainerID, UNHEALTHY);
    assertEquals(initialClosedChecksum, getContainerReplica(closedContainerID).getDataChecksum());
    waitForScmToSeeReplicaState(openContainerID, UNHEALTHY);
    if (corruption == MISSING_METADATA_DIR || corruption == MISSING_CONTAINER_DIR) {
        // In these cases the tree cannot be generated when the container is marked unhealthy and the checksum should
        // remain at 0.
        // The tree is generated from metadata by the container changing to unhealthy, not by the metadata scanner.
        assertEquals(0, getContainerReplica(openContainerID).getDataChecksum());
    } else {
        // The checksum will be generated for the first time when the container is marked unhealthy.
        // The tree is generated from metadata by the container changing to unhealthy, not by the metadata scanner.
        assertNotEquals(0, getContainerReplica(openContainerID).getDataChecksum());
    }
    // Once the unhealthy replica is reported, the open container's lifecycle
    // state in SCM should move to closed.
    waitForScmToCloseContainer(openContainerID);
    corruption.assertLogged(openContainerID, 1, logCapturer);
    corruption.assertLogged(closedContainerID, 1, logCapturer);
}

