@Test
public void testSnapdiffWithFilesystemCreate() throws IOException, URISyntaxException, InterruptedException, TimeoutException {
    assumeTrue(!bucketLayout.isObjectStore(enabledFileSystemPaths));
    String testVolumeName = "vol" + counter.incrementAndGet();
    String testBucketName = "bucket" + counter.incrementAndGet();
    store.createVolume(testVolumeName);
    OzoneVolume volume = store.getVolume(testVolumeName);
    createBucket(volume, testBucketName);
    String rootPath = String.format("%s://%s.%s/", OzoneConsts.OZONE_URI_SCHEME, testBucketName, testVolumeName);
    try (FileSystem fs = FileSystem.get(new URI(rootPath), cluster.getConf())) {
        String snap1 = "snap1";
        String key = "/dir1/dir2/key1";
        createSnapshot(testVolumeName, testBucketName, snap1);
        createFileKey(fs, key);
        String snap2 = "snap2";
        createSnapshot(testVolumeName, testBucketName, snap2);
        SnapshotDiffReport diff = getSnapDiffReport(testVolumeName, testBucketName, snap1, snap2);
        int idx = bucketLayout.isFileSystemOptimized() ? 0 : diff.getDiffList().size() - 1;
        Path p = new Path("/");
        while (true) {
            FileStatus[] fileStatuses = fs.listStatus(p);
            assertEquals(fileStatuses[0].isDirectory(), bucketLayout.isFileSystemOptimized() && idx < diff.getDiffList().size() - 1 || !bucketLayout.isFileSystemOptimized() && idx > 0);
            p = fileStatuses[0].getPath();
            assertEquals(diff.getDiffList().get(idx), SnapshotDiffReportOzone.getDiffReportEntry(SnapshotDiffReport.DiffType.CREATE, p.toUri().getPath().substring(1)));
            if (fileStatuses[0].isFile()) {
                break;
            }
            idx += bucketLayout.isFileSystemOptimized() ? 1 : -1;
        }
    }
}

