    OzoneVolume ozoneVolume = store.getVolume(volume1);
    createBucket(ozoneVolume, bucket1);
    OzoneBucket ozoneBucket1 = ozoneVolume.getBucket(bucket1);
    DBStore activeDbStore = ozoneManager.getMetadataManager().getStore();
    for (int i = 0; i < 100; i++) {
        String keyName = "/dir1/dir2/dir3/key-" + getKeySuffix(i);
        createFileKey(ozoneBucket1, keyName);
    }
    createSnapshot(volume1, bucket1, "bucket1-snap1");
    activeDbStore.compactDB();
    createBucket(ozoneVolume, bucket2);
    OzoneBucket ozoneBucket2 = ozoneVolume.getBucket(bucket2);
    for (int i = 100; i < 200; i++) {
        String keyName = "/dir1/dir2/dir3/key-" + getKeySuffix(i);
        createFileKey(ozoneBucket1, keyName);
        createFileKey(ozoneBucket2, keyName);
    }
    createSnapshot(volume1, bucket1, "bucket1-snap2");
    createSnapshot(volume1, bucket2, "bucket2-snap1");
    activeDbStore.compactDB();
    createBucket(ozoneVolume, bucket3);
    OzoneBucket ozoneBucket3 = ozoneVolume.getBucket(bucket3);
    for (int i = 200; i < 300; i++) {
        String keyName = "/dir1/dir2/dir3/key-" + getKeySuffix(i);
        createFileKey(ozoneBucket1, keyName);
        createFileKey(ozoneBucket2, keyName);
        createFileKey(ozoneBucket3, keyName);
    }
    createSnapshot(volume1, bucket1, "bucket1-snap3");
    createSnapshot(volume1, bucket2, "bucket2-snap2");
    createSnapshot(volume1, bucket3, "bucket3-snap1");
    activeDbStore.compactDB();
    for (int i = 300; i < 400; i++) {
        String keyName = "/dir1/dir2/dir3/key-" + getKeySuffix(i);
        createFileKey(ozoneBucket3, keyName);
        createFileKey(ozoneBucket2, keyName);
    }
    createSnapshot(volume1, bucket2, "bucket2-snap3");
    createSnapshot(volume1, bucket3, "bucket3-snap2");
    activeDbStore.compactDB();
    for (int i = 400; i < 500; i++) {
        String keyName = "/dir1/dir2/dir3/key-" + getKeySuffix(i);
        createFileKey(ozoneBucket3, keyName);
    }
    createSnapshot(volume1, bucket3, "bucket3-snap3");
    List<CompactionNode> filteredNodes = ozoneManager.getMetadataManager().getStore().getRocksDBCheckpointDiffer().getCompactionNodeMap().values().stream().filter(node -> !COLUMN_FAMILIES_TO_TRACK_IN_DAG.contains(node.getColumnFamily())).collect(Collectors.toList());
    assertEquals(0, filteredNodes.size());
    assertEquals(100, fetchReportPage(volume1, bucket1, "bucket1-snap1", "bucket1-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket1, "bucket1-snap2", "bucket1-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket1, "bucket1-snap1", "bucket1-snap3", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket2, "bucket2-snap1", "bucket2-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket2, "bucket2-snap2", "bucket2-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket2, "bucket2-snap1", "bucket2-snap3", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket3, "bucket3-snap1", "bucket3-snap2", null, 0).getDiffList().size());
    assertEquals(100, fetchReportPage(volume1, bucket3, "bucket3-snap2", "bucket3-snap3", null, 0).getDiffList().size());
    assertEquals(200, fetchReportPage(volume1, bucket3, "bucket3-snap1", "bucket3-snap3", null, 0).getDiffList().size());
    if (!disableNativeDiff) {
        // Prune SST files in compaction backup directory.
        RocksDatabase db = getRdbStore().getDb();
        RocksDBCheckpointDiffer differ = getRdbStore().getRocksDBCheckpointDiffer();
        differ.pruneSstFileValues();
        // Verify backup SST files are pruned on DB compactions.
        java.nio.file.Path sstBackUpDir = java.nio.file.Paths.get(differ.getSSTBackupDir());
        try (ManagedOptions managedOptions = new ManagedOptions();
            ManagedRocksIterator managedRocksIterator = new ManagedRocksIterator(db.getManagedRocksDb().get().newIterator(db.getColumnFamily(COMPACTION_LOG_TABLE).getHandle()))) {
            managedRocksIterator.get().seekToFirst();
            while (managedRocksIterator.get().isValid()) {
                byte[] value = managedRocksIterator.get().value();
                CompactionLogEntry compactionLogEntry = CompactionLogEntry.getFromProtobuf(CompactionLogEntryProto.parseFrom(value));
                compactionLogEntry.getInputFileInfoList().forEach(f -> {
                    java.nio.file.Path file = sstBackUpDir.resolve(f.getFileName() + ".sst");
                    if (COLUMN_FAMILIES_TO_TRACK_IN_DAG.contains(f.getColumnFamily()) && java.nio.file.Files.exists(file)) {
                        assertTrue(f.isPruned());
                        try (ManagedRawSSTFileReader<byte[]> sstFileReader = new ManagedRawSSTFileReader<>(managedOptions, file.toFile().getAbsolutePath(), 2 * 1024 * 1024);
                            ManagedRawSSTFileIterator<byte[]> itr = sstFileReader.newIterator(keyValue -> keyValue.getValue(), null, null)) {
                            while (itr.hasNext()) {
                                assertEquals(0, itr.next().length);
                            }
                        }
                    } else {
                        assertFalse(f.isPruned());
                    }
                });
                managedRocksIterator.get().next();
            }
        }
    }
}

