    readKeys(newKeys);
    OzoneManager newLeaderOM = getNewLeader(leaderOM, followerOM.getOMNodeId(), followerOM);
    OzoneManager newFollowerOM = cluster.getOzoneManager(leaderOM.getOMNodeId());
    assertEquals(leaderOM, newFollowerOM);
    SnapshotInfo newSnapshot = createOzoneSnapshot(newLeaderOM, SNAPSHOT_NAME_PREFIX + counter.incrementAndGet());
    /*
      Check whether newly created key data is reclaimed
      create key a
      create snapshot b
      delete key a
      create snapshot c
      assert that a is in c's deleted table
      create snapshot d
      delete snapshot c
      wait until key a appears in deleted table of d.
    */
    // create key a
    String keyNameA = writeKeys(1).get(0);
    String keyA = OM_KEY_PREFIX + ozoneBucket.getVolumeName() + OM_KEY_PREFIX + ozoneBucket.getName() + OM_KEY_PREFIX + keyNameA;
    Table<String, OmKeyInfo> omKeyInfoTable = newLeaderOM.getMetadataManager().getKeyTable(ozoneBucket.getBucketLayout());
    OmKeyInfo keyInfoA = omKeyInfoTable.get(keyA);
    assertNotNull(keyInfoA);
    // create snapshot b
    SnapshotInfo snapshotInfoB = createOzoneSnapshot(newLeaderOM, SNAPSHOT_NAME_PREFIX + counter.incrementAndGet());
    assertNotNull(snapshotInfoB);
    // delete key a
    ozoneBucket.deleteKey(keyNameA);
    LambdaTestUtils.await(10000, 1000, () -> !isKeyInTable(keyA, omKeyInfoTable));
    // create snapshot c
    SnapshotInfo snapshotInfoC = createOzoneSnapshot(newLeaderOM, SNAPSHOT_NAME_PREFIX + counter.incrementAndGet());
    // get snapshot c
    OmSnapshot snapC;
    try (UncheckedAutoCloseableSupplier<OmSnapshot> rcC = newLeaderOM.getOmSnapshotManager().getSnapshot(volumeName, bucketName, snapshotInfoC.getName())) {
        assertNotNull(rcC);
        snapC = rcC.get();
    }
    // assert that key a is in snapshot c's deleted table
    LambdaTestUtils.await(10000, 1000, () -> isKeyInTable(keyA, snapC.getMetadataManager().getDeletedTable()));
    // create snapshot d
    SnapshotInfo snapshotInfoD = createOzoneSnapshot(newLeaderOM, SNAPSHOT_NAME_PREFIX + counter.incrementAndGet());
    // delete snapshot c
    client.getObjectStore().deleteSnapshot(volumeName, bucketName, snapshotInfoC.getName());
    LambdaTestUtils.await(30000, 1000, () -> !isKeyInTable(snapshotInfoC.getTableKey(), newLeaderOM.getMetadataManager().getSnapshotInfoTable()));
    // get snapshot d
    OmSnapshot snapD;
    try (UncheckedAutoCloseableSupplier<OmSnapshot> rcD = newLeaderOM.getOmSnapshotManager().getSnapshot(volumeName, bucketName, snapshotInfoD.getName())) {
        assertNotNull(rcD);
        snapD = rcD.get();
    }
    // wait until key a appears in deleted table of snapshot d
    LambdaTestUtils.await(10000, 1000, () -> isKeyInTable(keyA, snapD.getMetadataManager().getDeletedTable()));
    // Confirm entry for deleted snapshot removed from info table
    client.getObjectStore().deleteSnapshot(volumeName, bucketName, newSnapshot.getName());
    LambdaTestUtils.await(10000, 1000, () -> isKeyInTable(newSnapshot.getTableKey(), newLeaderOM.getMetadataManager().getSnapshotInfoTable()));
    confirmSnapDiffForTwoSnapshotsDifferingBySingleKey(newLeaderOM);
}

