    SnapshotDiffReportOzone diff = getSnapDiffReport(volume, bucket, "snap2", "snap3");
    assertEquals(2, diff.getDiffList().size());
    assertEquals(Arrays.asList(new DiffReportEntry(SnapshotDiffReport.DiffType.CREATE, StringUtils.string2Bytes("dir1/dir4")), new DiffReportEntry(SnapshotDiffReport.DiffType.CREATE, StringUtils.string2Bytes("dir1/dir4/dir5"))), diff.getDiffList());
}

