    // case-8: keyPrefix corresponds to multiple existing keys and
    // startKey is null
    keyPrefix = "a1/b1/c12";
    // a1/b1/c1222.tx
    expectedKeys = getExpectedKeyShallowList(keyPrefix, startKey, legacyOzoneBucket);
    checkKeyShallowList(keyPrefix, startKey, expectedKeys, fsoOzoneBucket);
}

