    if (cluster.isOMActive(followerNodeId)) {
        followerNodeId = leaderOM.getPeerNodes().get(1).getNodeId();
    }
    OzoneManager followerOM = cluster.getOzoneManager(followerNodeId);
    // Do some transactions so that the log index increases
    writeKeysToIncreaseLogIndex(leaderRatisServer, 100);
    DBCheckpoint leaderDbCheckpoint = leaderOM.getMetadataManager().getStore().getCheckpoint(false);
    Path leaderCheckpointLocation = leaderDbCheckpoint.getCheckpointLocation();
    OmSnapshotUtils.createHardLinks(leaderCheckpointLocation, true);
    TransactionInfo leaderCheckpointTrxnInfo = OzoneManagerRatisUtils.getTrxnInfoFromCheckpoint(conf, leaderCheckpointLocation);
    // Corrupt the leader checkpoint and install that on the OM. The
    // operation should fail and OM should shutdown.
    boolean delete = true;
    File[] files = leaderCheckpointLocation.toFile().listFiles();
    assertNotNull(files);
    for (File file : files) {
        if (file.getName().contains(".sst")) {
            if (delete) {
                FileUtils.deleteQuietly(file);
                delete = false;
            } else {
                delete = true;
            }
        }
    }
    GenericTestUtils.setLogLevel(OzoneManager.class, Level.INFO);
    LogCapturer logCapture = LogCapturer.captureLogs(OzoneManager.class);
    followerOM.setExitManagerForTesting(new DummyExitManager());
    // Install corrupted checkpoint
    followerOM.installCheckpoint(leaderOMNodeId, leaderCheckpointLocation, leaderCheckpointTrxnInfo);
    // Wait checkpoint installation to be finished.
    assertLogCapture(logCapture, "System Exit: " + "Failed to reload OM state and instantiate services.");
    String msg = "RPC server is stopped";
    assertLogCapture(logCapture, msg);
}

@Test
public void testStartupSlvLessThanMlv() throws Exception {
    // Add subdirectories under the temporary folder where the version file
    // will be placed.
    String subDir = folder.toAbsolutePath() + "/om/current";
    File omSubdir = Files.createDirectories(Paths.get(subDir)).toFile();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(OMConfigKeys.OZONE_OM_DB_DIRS, folder.toAbsolutePath().toString());
    // Set metadata layout version larger than software layout version.
    int largestSlv = 0;
    for (LayoutFeature f : OMLayoutFeature.values()) {
        largestSlv = Math.max(largestSlv, f.layoutVersion());
    }
    int mlv = largestSlv + 1;
    // Create version file with MLV > SLV, which should fail the cluster build.
    UpgradeTestUtils.createVersionFile(omSubdir, HddsProtos.NodeType.OM, mlv);
    MiniOzoneCluster.Builder clusterBuilder = MiniOzoneCluster.newBuilder(conf);
    GenericTestUtils.withLogDisabled(MiniOzoneClusterImpl.class, () -> {
        OMException omException = assertThrows(OMException.class, clusterBuilder::build);
        String expectedMessage = String.format("Cannot initialize " + "VersionManager. Metadata layout version (%s) > software layout" + " version (%s)", mlv, mlv - 1);
        assertEquals(expectedMessage, omException.getMessage());
    });
}

