/**
 * 1. Stop one of the OM
 * 2. make a call to OM, this will make failover attempts to find new node.
 * a) if LE finishes but leader not ready, it retries to same node
 * b) if LE not done, it will failover to new node and check
 * 3. Try failover to same OM explicitly.
 * Now #3 should wait additional waitBetweenRetries time.
 * LE: Leader Election.
 */
@Test
@Order(Integer.MAX_VALUE - 1)
void testIncrementalWaitTimeWithSameNodeFailover() throws Exception {
    long waitBetweenRetries = getConf().getLong(OzoneConfigKeys.OZONE_CLIENT_WAIT_BETWEEN_RETRIES_MILLIS_KEY, OZONE_CLIENT_WAIT_BETWEEN_RETRIES_MILLIS_DEFAULT);
    HadoopRpcOMFailoverProxyProvider omFailoverProxyProvider = OmFailoverProxyUtil.getFailoverProxyProvider(getObjectStore().getClientProxy());
    // The omFailoverProxyProvider will point to the current leader OM node.
    String leaderOMNodeId = omFailoverProxyProvider.getCurrentProxyOMNodeId();
    getCluster().stopOzoneManager(leaderOMNodeId);
    getCluster().waitForLeaderOM();
    // failover should happen to new node
    createKeyTest(true);
    long numTimesTriedToSameNode = omFailoverProxyProvider.getWaitTime() / waitBetweenRetries;
    omFailoverProxyProvider.setNextOmProxy(omFailoverProxyProvider.getCurrentProxyOMNodeId());
    assertEquals((numTimesTriedToSameNode + 1) * waitBetweenRetries, omFailoverProxyProvider.getWaitTime());
}

