@Test
// Run this UT last. This interferes with testAdminCmdListOpenFiles
@Order(Integer.MAX_VALUE)
public void testRecursiveBucketDelete() throws Exception {
    String volume1 = "volume50";
    String bucket1 = "bucketfso";
    String bucket2 = "bucketobs";
    String bucket3 = "bucketlegacy";
    // Create volume volume1
    // Create bucket bucket1 with layout FILE_SYSTEM_OPTIMIZED
    // Insert some keys into it
    generateKeys(OZONE_URI_DELIMITER + volume1, OZONE_URI_DELIMITER + bucket1, BucketLayout.FILE_SYSTEM_OPTIMIZED.toString());
    // Create OBS bucket in volume1
    String[] args = new String[] { "bucket", "create", "--layout", BucketLayout.OBJECT_STORE.toString(), volume1 + OZONE_URI_DELIMITER + bucket2 };
    execute(ozoneShell, args);
    out.reset();
    // Insert few keys into OBS bucket
    String keyName = OZONE_URI_DELIMITER + volume1 + OZONE_URI_DELIMITER + bucket2 + OZONE_URI_DELIMITER + "key";
    for (int i = 0; i < 5; i++) {
        args = new String[] { "key", "put", "o3://" + omServiceId + keyName + i, testFile.getPath() };
        execute(ozoneShell, args);
    }
    out.reset();
    // Create Legacy bucket in volume1
    args = new String[] { "bucket", "create", "--layout", BucketLayout.LEGACY.toString(), volume1 + OZONE_URI_DELIMITER + bucket3 };
    execute(ozoneShell, args);
    out.reset();
    // Insert few keys into legacy bucket
    keyName = OZONE_URI_DELIMITER + volume1 + OZONE_URI_DELIMITER + bucket3 + OZONE_URI_DELIMITER + "key";
    for (int i = 0; i < 5; i++) {
        args = new String[] { "key", "put", "o3://" + omServiceId + keyName + i, testFile.getPath() };
        execute(ozoneShell, args);
    }
    out.reset();
    // Try bucket delete without recursive
    // It should fail as bucket is not empty
    final String[] args1 = new String[] { "bucket", "delete", volume1 + OZONE_URI_DELIMITER + bucket1 };
    ExecutionException exception = assertThrows(ExecutionException.class, () -> execute(ozoneShell, args1));
    OMException omException = (OMException) exception.getCause();
    assertEquals(BUCKET_NOT_EMPTY, omException.getResult());
    out.reset();
    // bucket1 should still exist
    assertEquals(client.getObjectStore().getVolume(volume1).getBucket(bucket1).getName(), bucket1);
    // Delete bucket1 recursively
    args = new String[] { "bucket", "delete", volume1 + OZONE_URI_DELIMITER + bucket1, "-r", "--yes" };
    execute(ozoneShell, args);
    out.reset();
    // Bucket1 should not exist
    omException = assertThrows(OMException.class, () -> client.getObjectStore().getVolume(volume1).getBucket(bucket1));
    assertEquals(BUCKET_NOT_FOUND, omException.getResult());
    // Bucket2 and Bucket3 should still exist
    assertEquals(client.getObjectStore().getVolume(volume1).getBucket(bucket2).getName(), bucket2);
    assertEquals(client.getObjectStore().getVolume(volume1).getBucket(bucket3).getName(), bucket3);
    // Delete bucket2(obs) recursively.
    args = new String[] { "bucket", "delete", volume1 + OZONE_URI_DELIMITER + bucket2, "-r", "--yes" };
    execute(ozoneShell, args);
    out.reset();
    omException = assertThrows(OMException.class, () -> client.getObjectStore().getVolume(volume1).getBucket(bucket2));
    assertEquals(BUCKET_NOT_FOUND, omException.getResult());
    // Delete bucket3(legacy) recursively.
    args = new String[] { "bucket", "delete", volume1 + OZONE_URI_DELIMITER + bucket3, "-r", "--yes" };
    execute(ozoneShell, args);
    out.reset();
    omException = assertThrows(OMException.class, () -> client.getObjectStore().getVolume(volume1).getBucket(bucket3));
    assertEquals(BUCKET_NOT_FOUND, omException.getResult());
    // Now delete volume without recursive
    // All buckets are already deleted
    args = new String[] { "volume", "delete", volume1 };
    execute(ozoneShell, args);
    out.reset();
    omException = assertThrows(OMException.class, () -> client.getObjectStore().getVolume(volume1));
    assertEquals(VOLUME_NOT_FOUND, omException.getResult());
}

