@Test
public void testTenantSetSecret() throws IOException, InterruptedException {
    final String tenantName = "tenant-test-set-secret";
    // Create test tenant
    executeHA(tenantShell, new String[] { "create", tenantName });
    checkOutput(out, "", true);
    checkOutput(err, "", true);
    // Set secret for non-existent accessId. Expect failure
    executeHA(tenantShell, new String[] { "user", "set-secret", tenantName + "$alice", "--secret=somesecret0" });
    checkOutput(out, "", true);
    checkOutput(err, "accessId '" + tenantName + "$alice' not found.\n", true);
    // Assign a user to the tenant so that we have an accessId entry
    executeHA(tenantShell, new String[] { "user", "assign", "alice", "--tenant=" + tenantName });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='" + tenantName + "$alice'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "", true);
    // Set secret as OM admin should succeed
    executeHA(tenantShell, new String[] { "user", "setsecret", tenantName + "$alice", "--secret=somesecret1" });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='" + tenantName + "$alice'\n" + "export AWS_SECRET_ACCESS_KEY='somesecret1'\n", true);
    checkOutput(err, "", true);
    // Set empty secret key should fail
    int exitCode = executeHA(tenantShell, new String[] { "user", "setsecret", tenantName + "$alice", "--secret=short" });
    assertNotEquals(0, exitCode, "Expected non-zero exit code");
    checkOutput(out, "", true);
    checkOutput(err, "Secret key length should be at least 8 characters\n", true);
    // Get secret should still give the previous secret key
    executeHA(tenantShell, new String[] { "user", "getsecret", tenantName + "$alice" });
    checkOutput(out, "somesecret1", false);
    checkOutput(err, "", true);
    // Set secret as alice should succeed
    final UserGroupInformation ugiAlice = UserGroupInformation.createUserForTesting("alice", new String[] { "usergroup" });
    ugiAlice.doAs((PrivilegedExceptionAction<Void>) () -> {
        executeHA(tenantShell, new String[] { "user", "setsecret", tenantName + "$alice", "--secret=somesecret2" });
        checkOutput(out, "export AWS_ACCESS_KEY_ID='" + tenantName + "$alice'\n" + "export AWS_SECRET_ACCESS_KEY='somesecret2'\n", true);
        checkOutput(err, "", true);
        return null;
    });
    // Set secret as bob should fail
    executeHA(tenantShell, new String[] { "user", "assign", "bob", "--tenant=" + tenantName });
    checkOutput(out, "export AWS_ACCESS_KEY_ID='" + tenantName + "$bob'\n" + "export AWS_SECRET_ACCESS_KEY='", false);
    checkOutput(err, "", true);
    final UserGroupInformation ugiBob = UserGroupInformation.createUserForTesting("bob", new String[] { "usergroup" });
    ugiBob.doAs((PrivilegedExceptionAction<Void>) () -> {
        int exitC = executeHA(tenantShell, new String[] { "user", "setsecret", tenantName + "$alice", "--secret=somesecret2" });
        assertNotEquals(0, exitC, "Should return non-zero exit code!");
        checkOutput(out, "", true);
        checkOutput(err, "Requested accessId 'tenant-test-set-secret$alice'" + " doesn't belong to current user 'bob', nor does current user" + " have Ozone or tenant administrator privilege\n", true);
        return null;
    });
    // Once we make bob an admin of this tenant (non-delegated admin permission
