        certCodec.writeCertificate(cert);
        certCodec.writeCertificate(scmCert, String.format(DefaultCertificateClient.CERT_FILE_NAME_FORMAT, CAType.SUBORDINATE.getFileNamePrefix() + scmCert.getSerialNumber().toString()));
        certCodec.writeCertificate(scmCertClient.getCACertificate(), String.format(DefaultCertificateClient.CERT_FILE_NAME_FORMAT, CAType.ROOT.getFileNamePrefix() + rootCert.getSerialNumber().toString()));
        omStore.setOmCertSerialId(certId);
