/**
 * Test case for verifying directory deletion and namespace summary updates.
 *
 *      dir1
 *      ├── file1
 *      ├── file2
 *      ├── ...
 *      └── file10
 */
@Test
public void testGetDeletedDirectoryInfo() throws Exception {
    // Create a directory structure with 10 files in dir1.
    Path dir1 = new Path("/dir1");
    fs.mkdirs(dir1);
    for (int i = 1; i <= 10; i++) {
        Path path1 = new Path(dir1, "testKey" + i);
        try (FSDataOutputStream stream = fs.create(path1)) {
            stream.write(1);
        }
    }
    // Fetch the file table and directory table from Ozone Manager.
    OMMetadataManager ozoneMetadataManagerInstance = cluster.getOzoneManager().getMetadataManager();
    Table<String, OmKeyInfo> omFileTable = ozoneMetadataManagerInstance.getKeyTable(getFSOBucketLayout());
    Table<String, OmDirectoryInfo> omDirTable = ozoneMetadataManagerInstance.getDirectoryTable();
    // Verify the entries in the Ozone Manager tables.
    assertTableRowCount(omFileTable, 10, false);
    assertTableRowCount(omDirTable, 1, false);
    // Sync data from Ozone Manager to Recon.
    syncDataFromOM();
    // Retrieve tables from Recon's OM-DB.
    ReconOMMetadataManager reconOmMetadataManagerInstance = (ReconOMMetadataManager) recon.getReconServer().getOzoneManagerServiceProvider().getOMMetadataManagerInstance();
    Table<String, OmKeyInfo> reconFileTable = reconOmMetadataManagerInstance.getKeyTable(getFSOBucketLayout());
    Table<String, OmDirectoryInfo> reconDirTable = reconOmMetadataManagerInstance.getDirectoryTable();
    Table<String, OmKeyInfo> reconDeletedDirTable = reconOmMetadataManagerInstance.getDeletedDirTable();
    // Verify the entries in the Recon tables after sync.
    assertTableRowCount(reconFileTable, 10, true);
    assertTableRowCount(reconDirTable, 1, true);
    assertTableRowCount(reconDeletedDirTable, 0, true);
    // Retrieve the object ID of dir1 from directory table.
    Long directoryObjectId = null;
    try (Table.KeyValueIterator<?, OmDirectoryInfo> iterator = reconDirTable.iterator()) {
        if (iterator.hasNext()) {
            directoryObjectId = iterator.next().getValue().getObjectID();
        }
    }
    if (directoryObjectId == null) {
        fail("directoryObjectId is null. Test case cannot proceed.");
    } else {
        // Retrieve Namespace Summary for dir1 from Recon.
        ReconNamespaceSummaryManagerImpl namespaceSummaryManager = (ReconNamespaceSummaryManagerImpl) recon.getReconServer().getReconNamespaceSummaryManager();
        NSSummary summary = namespaceSummaryManager.getNSSummary(directoryObjectId);
        // Assert that the directory dir1 has 10 sub-files and size of 1000 bytes.
        assertEquals(10, summary.getNumOfFiles());
        assertEquals(10, summary.getSizeOfFiles());
    }
    // Delete the entire directory dir1.
    fs.delete(dir1, true);
    syncDataFromOM();
    // Check the count of recon directory table and recon deletedDirectory table
    assertTableRowCount(reconDirTable, 0, true);
    assertTableRowCount(reconDeletedDirTable, 1, true);
    // Create an Instance of OMDBInsightEndpoint.
    OzoneStorageContainerManager reconSCM = recon.getReconServer().getReconStorageContainerManager();
    ReconNamespaceSummaryManagerImpl reconNamespaceSummaryManager = (ReconNamespaceSummaryManagerImpl) recon.getReconServer().getReconNamespaceSummaryManager();
    OMDBInsightEndpoint omdbInsightEndpoint = new OMDBInsightEndpoint(reconSCM, reconOmMetadataManagerInstance, mock(GlobalStatsDao.class), reconNamespaceSummaryManager);
    // Fetch the deleted directory info from Recon OmDbInsightEndpoint.
    Response deletedDirInfo = omdbInsightEndpoint.getDeletedDirInfo(-1, "");
    KeyInsightInfoResponse entity = (KeyInsightInfoResponse) deletedDirInfo.getEntity();
    // Assert the size of deleted directory is 10.
    assertEquals(10, entity.getUnreplicatedDataSize());
    // Cleanup the tables.
    cleanupTables();
}

