/**
 * This test verifies the count of MISSING and EMPTY_MISSING containers.
 * Following steps being followed in a single DN cluster.
 *    --- Allocate a container in SCM.
 *    --- Client writes the chunk and put block to only DN successfully.
 *    --- Shuts down the only DN.
 *    --- Since container to key mapping doesn't have any key mapped to
 *        container, missing container will be marked EMPTY_MISSING.
 *    --- Add a key mapping entry to key container mapping table for the
 *        container added.
 *    --- Now container will no longer be marked as EMPTY_MISSING and just
 *        as MISSING.
 *    --- Restart the only DN in cluster.
 *    --- Now container no longer will be marked as MISSING.
 *
 * @throws Exception
 */
@Test
public void testEmptyMissingContainerDownNode() throws Exception {
    ReconStorageContainerManagerFacade reconScm = (ReconStorageContainerManagerFacade) recon.getReconServer().getReconStorageContainerManager();
    ReconContainerMetadataManager reconContainerMetadataManager = recon.getReconServer().getReconContainerMetadataManager();
    StorageContainerManager scm = cluster.getStorageContainerManager();
    PipelineManager reconPipelineManager = reconScm.getPipelineManager();
    PipelineManager scmPipelineManager = scm.getPipelineManager();
    // Make sure Recon's pipeline state is initialized.
    LambdaTestUtils.await(60000, 1000, () -> (!reconPipelineManager.getPipelines().isEmpty()));
    ContainerManager scmContainerManager = scm.getContainerManager();
    ReconContainerManager reconContainerManager = (ReconContainerManager) reconScm.getContainerManager();
    ContainerInfo containerInfo = scmContainerManager.allocateContainer(RatisReplicationConfig.getInstance(ONE), "test");
    long containerID = containerInfo.getContainerID();
    Pipeline pipeline = scmPipelineManager.getPipeline(containerInfo.getPipelineID());
    XceiverClientGrpc client = new XceiverClientGrpc(pipeline, conf);
    runTestOzoneContainerViaDataNode(containerID, client);
    // Make sure Recon got the container report with new container.
    assertEquals(scmContainerManager.getContainers(), reconContainerManager.getContainers());
    // Bring down the Datanode that had the container replica.
    cluster.shutdownHddsDatanode(pipeline.getFirstNode());
    // Since we no longer add EMPTY_MISSING containers to the table, we should
    // have zero EMPTY_MISSING containers in the DB but their information will be logged.
    LambdaTestUtils.await(25000, 1000, () -> {
        List<UnhealthyContainers> allEmptyMissingContainers = reconContainerManager.getContainerSchemaManager().getUnhealthyContainers(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING, 0L, Optional.empty(), 1000);
        // Check if EMPTY_MISSING containers are not added to the DB and their count is logged
        Map<ContainerSchemaDefinition.UnHealthyContainerStates, Map<String, Long>> unhealthyContainerStateStatsMap = reconScm.getContainerHealthTask().getUnhealthyContainerStateStatsMap();
        // Return true if the size of the fetched containers is 0 and the log shows 1 for EMPTY_MISSING state
        return allEmptyMissingContainers.isEmpty() && unhealthyContainerStateStatsMap.get(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING).getOrDefault(CONTAINER_COUNT, 0L) == 1;
    });
    // Now add a container to key mapping count as 3. This data is used to
    // identify if container is empty in terms of keys mapped to container.
    try (RDBBatchOperation rdbBatchOperation = new RDBBatchOperation()) {
        reconContainerMetadataManager.batchStoreContainerKeyCounts(rdbBatchOperation, containerID, 3L);
        reconContainerMetadataManager.commitBatchOperation(rdbBatchOperation);
    }
    // Verify again and now container is not empty missing but just missing.
    LambdaTestUtils.await(25000, 1000, () -> {
        List<UnhealthyContainers> allMissingContainers = reconContainerManager.getContainerSchemaManager().getUnhealthyContainers(ContainerSchemaDefinition.UnHealthyContainerStates.MISSING, 0L, Optional.empty(), 1000);
        return (allMissingContainers.size() == 1);
    });
    LambdaTestUtils.await(25000, 1000, () -> {
        List<UnhealthyContainers> allEmptyMissingContainers = reconContainerManager.getContainerSchemaManager().getUnhealthyContainers(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING, 0L, Optional.empty(), 1000);
        Map<ContainerSchemaDefinition.UnHealthyContainerStates, Map<String, Long>> unhealthyContainerStateStatsMap = reconScm.getContainerHealthTask().getUnhealthyContainerStateStatsMap();
        // Return true if the size of the fetched containers is 0 and the log shows 0 for EMPTY_MISSING state
        return allEmptyMissingContainers.isEmpty() && unhealthyContainerStateStatsMap.get(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING).getOrDefault(CONTAINER_COUNT, 0L) == 0;
    });
    // Now remove keys from container. This data is used to
    // identify if container is empty in terms of keys mapped to container.
    try (RDBBatchOperation rdbBatchOperation = new RDBBatchOperation()) {
        reconContainerMetadataManager.batchStoreContainerKeyCounts(rdbBatchOperation, containerID, 0L);
        reconContainerMetadataManager.commitBatchOperation(rdbBatchOperation);
    }
    // Since we no longer add EMPTY_MISSING containers to the table, we should
    // have zero EMPTY_MISSING containers in the DB but their information will be logged.
    LambdaTestUtils.await(25000, 1000, () -> {
        List<UnhealthyContainers> allEmptyMissingContainers = reconContainerManager.getContainerSchemaManager().getUnhealthyContainers(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING, 0L, Optional.empty(), 1000);
        Map<ContainerSchemaDefinition.UnHealthyContainerStates, Map<String, Long>> unhealthyContainerStateStatsMap = reconScm.getContainerHealthTask().getUnhealthyContainerStateStatsMap();
        // Return true if the size of the fetched containers is 0 and the log shows 1 for EMPTY_MISSING state
        return allEmptyMissingContainers.isEmpty() && unhealthyContainerStateStatsMap.get(ContainerSchemaDefinition.UnHealthyContainerStates.EMPTY_MISSING).getOrDefault(CONTAINER_COUNT, 0L) == 1;
    });
    // Now restart the cluster and verify the container is no longer missing.
    cluster.restartHddsDatanode(pipeline.getFirstNode(), true);
    LambdaTestUtils.await(25000, 1000, () -> {
        List<UnhealthyContainers> allMissingContainers = reconContainerManager.getContainerSchemaManager().getUnhealthyContainers(ContainerSchemaDefinition.UnHealthyContainerStates.MISSING, 0L, Optional.empty(), 1000);
        return (allMissingContainers.isEmpty());
    });
    IOUtils.closeQuietly(client);
}

@Test
public void testOmDBSyncing() throws Exception {
    // add a vol, bucket and key
    addKeys(0, 1);
    // check if OM metadata has vol0/bucket0/key0 info
    String ozoneKey = metadataManager.getOzoneKey("vol0", "bucket0", "key0");
    OmKeyInfo keyInfo1 = metadataManager.getKeyTable(getBucketLayout()).get(ozoneKey);
    // verify if OM has /vol0/bucket0/key0
    assertEquals("vol0", keyInfo1.getVolumeName());
    assertEquals("bucket0", keyInfo1.getBucketName());
    OzoneManagerServiceProviderImpl impl = (OzoneManagerServiceProviderImpl) recon.getReconServer().getOzoneManagerServiceProvider();
    impl.syncDataFromOM();
    OzoneManagerSyncMetrics metrics = impl.getMetrics();
    // HTTP call to /api/task/status
    long omLatestSeqNumber = ((RDBStore) metadataManager.getStore()).getDb().getLatestSequenceNumber();
    String taskStatusResponse = makeHttpCall(taskStatusURL);
    long reconLatestSeqNumber = getReconTaskAttributeFromJson(taskStatusResponse, OmSnapshotRequest.name(), "lastUpdatedSeqNumber");
    // verify sequence number after full snapshot
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    assertEquals(0, metrics.getSequenceNumberLag());
    //add 4 keys to check for delta updates
    addKeys(1, 5);
    // update the next snapshot from om to verify delta updates
    impl.syncDataFromOM();
    // HTTP call to /api/task/status
    omLatestSeqNumber = ((RDBStore) metadataManager.getStore()).getDb().getLatestSequenceNumber();
    taskStatusResponse = makeHttpCall(taskStatusURL);
    reconLatestSeqNumber = getReconTaskAttributeFromJson(taskStatusResponse, OmDeltaRequest.name(), "lastUpdatedSeqNumber");
    //verify sequence number after Delta Updates
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    assertEquals(0, metrics.getSequenceNumberLag());
    long beforeRestartSnapShotTimeStamp = getReconTaskAttributeFromJson(taskStatusResponse, OmSnapshotRequest.name(), "lastUpdatedTimestamp");
    //restart Recon
    recon.stop();
    recon.start(cluster.getConf());
    impl = (OzoneManagerServiceProviderImpl) recon.getReconServer().getOzoneManagerServiceProvider();
    //add 5 more keys to OM
    addKeys(5, 10);
    // get the next snapshot from om
    impl.syncDataFromOM();
    // HTTP call to /api/task/status
    omLatestSeqNumber = ((RDBStore) metadataManager.getStore()).getDb().getLatestSequenceNumber();
    taskStatusResponse = makeHttpCall(taskStatusURL);
    reconLatestSeqNumber = getReconTaskAttributeFromJson(taskStatusResponse, OmDeltaRequest.name(), "lastUpdatedSeqNumber");
    long afterRestartSnapShotTimeStamp = getReconTaskAttributeFromJson(taskStatusResponse, OmSnapshotRequest.name(), "lastUpdatedTimestamp");
    // verify only Delta updates were added to recon after restart.
    assertThat(afterRestartSnapShotTimeStamp).isGreaterThanOrEqualTo(beforeRestartSnapShotTimeStamp);
    //verify sequence number after Delta Updates
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    assertEquals(0, metrics.getSequenceNumberLag());
}

// This test simulates the mis-match in sequence number between Recon OM
// snapshot DB and OzoneManager OM active DB. Recon sync with OM DB every
// 5-10 mins based on configured interval and if Recon OM snapshot DB
// has higher sequence number than OM active DB last sequence number,
// then OM DB updates call since last sequence number will fail as OM DB
// will not know about that sequence number which is not yet written to
// OM Rocks DB. In such case OM sets the 'isDBUpdateSuccess' flag as false.
// And Recon should fall back on full snapshot and recover itself.
@Test
public void testOmDBSyncWithSeqNumberMismatch() throws Exception {
    LogCapturer logs = LogCapturer.captureLogs(RDBStore.class);
    GenericTestUtils.setLogLevel(RDBStore.class, INFO);
    LogCapturer omServiceProviderImplLogs = LogCapturer.captureLogs(OzoneManagerServiceProviderImpl.class);
    GenericTestUtils.setLogLevel(OzoneManagerServiceProviderImpl.class, INFO);
    // add a vol, bucket and key
    addKeys(10, 15);
    // check if OM metadata has vol10/bucket10/key10 info
    String ozoneKey = metadataManager.getOzoneKey("vol10", "bucket10", "key10");
    OmKeyInfo keyInfo1 = metadataManager.getKeyTable(getBucketLayout()).get(ozoneKey);
    // verify if OM has /vol10/bucket10/key10
    assertEquals("vol10", keyInfo1.getVolumeName());
    assertEquals("bucket10", keyInfo1.getBucketName());
    OzoneManagerServiceProviderImpl impl = (OzoneManagerServiceProviderImpl) recon.getReconServer().getOzoneManagerServiceProvider();
    impl.syncDataFromOM();
    OzoneManagerSyncMetrics metrics = impl.getMetrics();
    // HTTP call to /api/task/status
    long omLatestSeqNumber = ((RDBStore) metadataManager.getStore()).getDb().getLatestSequenceNumber();
    OMMetadataManager reconMetadataManagerInstance = recon.getReconServer().getOzoneManagerServiceProvider().getOMMetadataManagerInstance();
    long reconLatestSeqNumber = ((RDBStore) reconMetadataManagerInstance.getStore()).getDb().getLatestSequenceNumber();
    // verify sequence number after incremental delta snapshot
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    assertEquals(0, metrics.getSequenceNumberLag());
    String volume = "vol15";
    String bucket = "bucket15";
    String key = "key15";
    String omKey = reconMetadataManagerInstance.getOzoneKey(volume, bucket, key);
    // Write additional key in new volume and new bucket in Recon OM snapshot
    // DB to increase the last sequence number by 1 in comparison to OM
    // active DB, this simulates the mis-match between 2 DBs before triggering
    // syncDataFromOM call.
    reconMetadataManagerInstance.getKeyTable(getBucketLayout()).put(omKey, new OmKeyInfo.Builder().setBucketName(bucket).setVolumeName(volume).setKeyName(key).setReplicationConfig(StandaloneReplicationConfig.getInstance(HddsProtos.ReplicationFactor.ONE)).setOmKeyLocationInfos(Collections.singletonList(getOmKeyLocationInfoGroup())).build());
    reconLatestSeqNumber = ((RDBStore) reconMetadataManagerInstance.getStore()).getDb().getLatestSequenceNumber();
    assertEquals(omLatestSeqNumber + 1, reconLatestSeqNumber);
    // This OM DB sync call will eventually fail and throw exception at OM
    // cluster's getDBUpdates(since lastSequenceNumber) API as expected and
    // will return 'isDBUpdateSuccess' flag as false which will force Recon
    // to fallback on full snapshot. Full snapshot sync should normalize the
    // OM active DB lastSequence number and Recon's OM snapshot DB lastSequence
    // number.
    impl.syncDataFromOM();
    assertTrue(logs.getOutput().contains("Requested sequence not yet written in the db"));
    assertTrue(logs.getOutput().contains("Returned DBUpdates isDBUpdateSuccess: false"));
    reconLatestSeqNumber = ((RDBStore) reconMetadataManagerInstance.getStore()).getDb().getLatestSequenceNumber();
    assertEquals(0, metrics.getSequenceNumberLag());
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    reconLatestSeqNumber = ((RDBStore) reconMetadataManagerInstance.getStore()).getDb().getLatestSequenceNumber();
    assertEquals(omLatestSeqNumber, reconLatestSeqNumber);
    impl.syncDataFromOM();
    assertTrue(omServiceProviderImplLogs.getOutput().contains("isDBUpdateSuccess: true"));
}

