@Test
public void testValidateAndUpdateCache() throws Exception {
    OMRequest omRequest = createFileRequest(volumeName, bucketName, keyName, HddsProtos.ReplicationFactor.ONE, HddsProtos.ReplicationType.RATIS, false, true);
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    OMFileCreateRequest omFileCreateRequest = getOMFileCreateRequest(omRequest);
    OMRequest modifiedOmRequest = omFileCreateRequest.preExecute(ozoneManager);
    long id = modifiedOmRequest.getCreateFileRequest().getClientID();
    // Before calling
    OmKeyInfo omKeyInfo = verifyPathInOpenKeyTable(keyName, id, false);
    assertNull(omKeyInfo);
    omFileCreateRequest = getOMFileCreateRequest(modifiedOmRequest);
    OMClientResponse omFileCreateResponse = omFileCreateRequest.validateAndUpdateCache(ozoneManager, 100L);
    assertEquals(OzoneManagerProtocolProtos.Status.OK, omFileCreateResponse.getOMResponse().getStatus());
    // Check open table whether key is added or not.
    omKeyInfo = verifyPathInOpenKeyTable(keyName, id, true);
    List<OmKeyLocationInfo> omKeyLocationInfoList = omKeyInfo.getLatestVersionLocations().getLocationList();
    assertEquals(1, omKeyLocationInfoList.size());
    OmKeyLocationInfo omKeyLocationInfo = omKeyLocationInfoList.get(0);
    // Check modification time
    assertEquals(modifiedOmRequest.getCreateFileRequest().getKeyArgs().getModificationTime(), omKeyInfo.getModificationTime());
    assertEquals(omKeyInfo.getModificationTime(), omKeyInfo.getCreationTime());
    // Check data of the block
    OzoneManagerProtocolProtos.KeyLocation keyLocation = modifiedOmRequest.getCreateFileRequest().getKeyArgs().getKeyLocations(0);
    assertEquals(keyLocation.getBlockID().getContainerBlockID().getContainerID(), omKeyLocationInfo.getContainerID());
    assertEquals(keyLocation.getBlockID().getContainerBlockID().getLocalID(), omKeyLocationInfo.getLocalID());
}

