public void testValidateAndUpdateCacheWithNonRecursive() throws Exception {
    testNonRecursivePath(UUID.randomUUID().toString(), false, false, false);
    testNonRecursivePath("a/b", false, false, true);
    ReplicationConfig replicationConfig = ReplicationConfig.fromProtoTypeAndFactor(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE);
    // Create some child keys for the path
    OMRequestTestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/c/d", 0L, replicationConfig, omMetadataManager);
    OMRequestTestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/c/", 0L, replicationConfig, omMetadataManager);
    OMRequestTestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/", 0L, replicationConfig, omMetadataManager);
    OMRequestTestUtils.addKeyToTable(false, volumeName, bucketName, "a/", 0L, replicationConfig, omMetadataManager);
    // cannot create file if directory of same name exists
    testNonRecursivePath("a/b/c", false, false, true);
    // Delete child key but retain path "a/b/ in the key table
    omMetadataManager.getKeyTable(getBucketLayout()).delete(omMetadataManager.getOzoneKey(volumeName, bucketName, "a/b/c/d"));
    omMetadataManager.getKeyTable(getBucketLayout()).delete(omMetadataManager.getOzoneKey(volumeName, bucketName, "a/b/c/"));
    // can create non-recursive because parents already exist.
    testNonRecursivePath("a/b/e", false, false, false);
}

