@Test
public void testBucketLockWithPurgeDirectory() throws Exception {
    when(ozoneManager.getDefaultReplicationConfig()).thenReturn(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE));
    String bucket1 = "bucket" + RandomUtils.secure().randomInt();
    // Add volume, bucket and key entries to OM DB.
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucket1, omMetadataManager, BucketLayout.FILE_SYSTEM_OPTIMIZED);
    String bucketKey1 = omMetadataManager.getBucketKey(volumeName, bucket1);
    OmBucketInfo bucketInfo1 = omMetadataManager.getBucketTable().get(bucketKey1);
    PurgePathRequest purgePathRequest1 = createBucketDataAndGetPurgePathRequest(bucketInfo1);
    String bucket2 = "bucket" + RandomUtils.secure().randomInt();
    // Add volume, bucket and key entries to OM DB.
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucket2, omMetadataManager, BucketLayout.FILE_SYSTEM_OPTIMIZED);
    String bucketKey2 = omMetadataManager.getBucketKey(volumeName, bucket2);
    OmBucketInfo bucketInfo2 = omMetadataManager.getBucketTable().get(bucketKey2);
    long volumeId = omMetadataManager.getVolumeId(volumeName);
    PurgePathRequest purgePathRequest2 = createBucketDataAndGetPurgePathRequest(bucketInfo2);
    IOzoneManagerLock lock = spy(omMetadataManager.getLock());
    Set<Long> acquiredLockIds = new ConcurrentSkipListSet<>();
    Set<String> acquiredLockKeys = new ConcurrentSkipListSet<>();
    try {
        doAnswer(i -> {
            long threadId = Thread.currentThread().getId();
            GenericTestUtils.waitFor(() -> !acquiredLockIds.contains(threadId) || acquiredLockIds.size() == 2, 1000, 30000);
            OMLockDetails lockDetails = (OMLockDetails) i.callRealMethod();
            acquiredLockIds.add(threadId);
            acquiredLockKeys.add(i.getArgument(1) + "/" + i.getArgument(2));
            return lockDetails;
        }).when(lock).acquireWriteLock(eq(BUCKET_LOCK), anyString(), anyString());
        doAnswer(i -> {
            long threadId = Thread.currentThread().getId();
            GenericTestUtils.waitFor(() -> !acquiredLockIds.contains(threadId) || acquiredLockIds.size() == 2, 1000, 30000);
            OMLockDetails lockDetails = (OMLockDetails) i.callRealMethod();
            acquiredLockIds.add(threadId);
            for (String[] lockKey : (List<String[]>) i.getArgument(1)) {
                acquiredLockKeys.add(lockKey[0] + "/" + lockKey[1]);
            }
            return lockDetails;
        }).when(lock).acquireWriteLocks(eq(BUCKET_LOCK), anyCollection());
        when(omMetadataManager.getLock()).thenReturn(lock);
        List<BucketNameInfo> bucketInfoList = Arrays.asList(BucketNameInfo.newBuilder().setVolumeName(bucketInfo1.getVolumeName()).setBucketName(bucketInfo1.getBucketName()).setBucketId(bucketInfo1.getObjectID()).setVolumeId(volumeId).build(), BucketNameInfo.newBuilder().setVolumeName(bucketInfo2.getVolumeName()).setBucketName(bucketInfo2.getBucketName()).setBucketId(bucketInfo2.getObjectID()).setVolumeId(volumeId).build());
        OMDirectoriesPurgeRequestWithFSO purgePathRequests1 = new OMDirectoriesPurgeRequestWithFSO(preExecute(createPurgeKeysRequest(null, Arrays.asList(purgePathRequest1, purgePathRequest2), bucketInfoList)));
        OMDirectoriesPurgeRequestWithFSO purgePathRequests2 = new OMDirectoriesPurgeRequestWithFSO(preExecute(createPurgeKeysRequest(null, Arrays.asList(purgePathRequest2, purgePathRequest1), bucketInfoList)));
        CompletableFuture future1 = CompletableFuture.runAsync(() -> purgePathRequests1.validateAndUpdateCache(ozoneManager, 100L));
        CompletableFuture future2 = CompletableFuture.runAsync(() -> purgePathRequests2.validateAndUpdateCache(ozoneManager, 100L));
        future1.get();
        future2.get();
        assertEquals(Stream.of(bucketInfo1.getVolumeName() + "/" + bucketInfo1.getBucketName(), bucketInfo2.getVolumeName() + "/" + bucketInfo2.getBucketName()).collect(Collectors.toSet()), acquiredLockKeys);
    } finally {
        reset(lock);
    }
}

