@Test
public void testKeyPurgeInSnapshot() throws Exception {
    when(ozoneManager.getDefaultReplicationConfig()).thenReturn(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE));
    // Create and Delete keys. The keys should be moved to DeletedKeys table
    Pair<List<String>, List<String>> deleteKeysAndRenamedEntry = createAndDeleteKeysAndRenamedEntry(1, null);
    SnapshotInfo snapInfo = createSnapshot("snap1");
    assertEquals(snapInfo.getLastTransactionInfo(), TransactionInfo.valueOf(TransactionInfo.getTermIndex(1L)).toByteString());
    // The keys should be not present in the active Db's deletedTable
    for (String deletedKey : deleteKeysAndRenamedEntry.getKey()) {
        assertFalse(omMetadataManager.getDeletedTable().isExist(deletedKey));
    }
    for (String renamedKey : deleteKeysAndRenamedEntry.getValue()) {
        assertFalse(omMetadataManager.getSnapshotRenamedTable().isExist(renamedKey));
    }
    UncheckedAutoCloseableSupplier<OmSnapshot> rcOmSnapshot = ozoneManager.getOmSnapshotManager().getSnapshot(snapInfo.getVolumeName(), snapInfo.getBucketName(), snapInfo.getName());
    OmSnapshot omSnapshot = rcOmSnapshot.get();
    // The keys should be present in the snapshot's deletedTable
    for (String deletedKey : deleteKeysAndRenamedEntry.getKey()) {
        assertTrue(omSnapshot.getMetadataManager().getDeletedTable().isExist(deletedKey));
    }
    // The keys should be present in the snapshot's deletedTable
    for (String renamedKey : deleteKeysAndRenamedEntry.getValue()) {
        assertTrue(omSnapshot.getMetadataManager().getSnapshotRenamedTable().isExist(renamedKey));
    }
    // Create PurgeKeysRequest to purge the deleted keys
    OMRequest omRequest = createPurgeKeysRequest(deleteKeysAndRenamedEntry.getKey(), deleteKeysAndRenamedEntry.getValue(), snapInfo.getTableKey());
    OMRequest preExecutedRequest = preExecute(omRequest);
    OMKeyPurgeRequest omKeyPurgeRequest = new OMKeyPurgeRequest(preExecutedRequest);
    omKeyPurgeRequest.validateAndUpdateCache(ozoneManager, 100L);
    SnapshotInfo snapshotInfoOnDisk = omMetadataManager.getSnapshotInfoTable().getSkipCache(snapInfo.getTableKey());
    SnapshotInfo updatedSnapshotInfo = omMetadataManager.getSnapshotInfoTable().get(snapInfo.getTableKey());
    assertEquals(snapshotInfoOnDisk, snapInfo);
    snapInfo.setLastTransactionInfo(TransactionInfo.valueOf(TransactionInfo.getTermIndex(100L)).toByteString());
    assertEquals(snapInfo, updatedSnapshotInfo);
    OMResponse omResponse = OMResponse.newBuilder().setPurgeKeysResponse(PurgeKeysResponse.getDefaultInstance()).setCmdType(Type.PurgeKeys).setStatus(Status.OK).build();
    try (BatchOperation batchOperation = omMetadataManager.getStore().initBatchOperation()) {
        OMKeyPurgeResponse omKeyPurgeResponse = new OMKeyPurgeResponse(omResponse, deleteKeysAndRenamedEntry.getKey(), deleteKeysAndRenamedEntry.getValue(), snapInfo, null, null);
        omKeyPurgeResponse.addToDBBatch(omMetadataManager, batchOperation);
        // Do manual commit and see whether addToBatch is successful or not.
        omMetadataManager.getStore().commitBatchOperation(batchOperation);
    }
    snapshotInfoOnDisk = omMetadataManager.getSnapshotInfoTable().getSkipCache(snapInfo.getTableKey());
    assertEquals(snapshotInfoOnDisk, snapInfo);
    // The keys should not exist in the DeletedKeys table
    for (String deletedKey : deleteKeysAndRenamedEntry.getKey()) {
        assertFalse(omSnapshot.getMetadataManager().getDeletedTable().isExist(deletedKey));
    }
    for (String renamedEntry : deleteKeysAndRenamedEntry.getValue()) {
        assertFalse(omSnapshot.getMetadataManager().getSnapshotRenamedTable().isExist(renamedEntry));
    }
    omSnapshot = null;
    rcOmSnapshot.close();
}

