/**
 * Tests removing MPUs from the multipart info table cache that have higher
 * updateID than the transactionID. Those MPUs should be ignored.
 * It is OK if updateID equals to or less than transactionID.
 * See {@link #setUpdateID(long)}.
 *
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("bucketLayouts")
public void testAbortMPUsWithHigherUpdateID(BucketLayout buckLayout) throws Exception {
    this.bucketLayout = buckLayout;
    final String volumeName = UUID.randomUUID().toString();
    final String bucketName = UUID.randomUUID().toString();
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    final long updateId = 200L;
    final long transactionId = 100L;
    // Used only to build the MPU db key
    OmKeyInfo.Builder keyBuilder = new OmKeyInfo.Builder().setVolumeName(volumeName).setBucketName(bucketName);
    OmMultipartKeyInfo.Builder mpuBuilder = new OmMultipartKeyInfo.Builder().setReplicationConfig(ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, ReplicationFactor.THREE));
    if (getBucketLayout().equals(BucketLayout.FILE_SYSTEM_OPTIMIZED)) {
        mpuBuilder.setParentID(UniqueId.next());
    }
    OmKeyInfo keyWithHigherUpdateID = keyBuilder.setKeyName("key").build();
    OmMultipartKeyInfo mpuWithHigherUpdateID = mpuBuilder.setUpdateID(updateId).setUploadID(OMMultipartUploadUtils.getMultipartUploadId()).build();
    OmKeyInfo keyWithSameUpdateID = keyBuilder.setKeyName("key2").build();
    OmMultipartKeyInfo mpuWithSameUpdateID = mpuBuilder.setUpdateID(transactionId).setUploadID(OMMultipartUploadUtils.getMultipartUploadId()).build();
    String mpuDBKeyWithHigherUpdateId = OMRequestTestUtils.addMultipartInfoToTable(false, keyWithHigherUpdateID, mpuWithHigherUpdateID, mpuWithHigherUpdateID.getUpdateID(), omMetadataManager);
    String mpuDBKeyWithSameUpdateId = OMRequestTestUtils.addMultipartInfoToTable(false, keyWithSameUpdateID, mpuWithSameUpdateID, mpuWithSameUpdateID.getUpdateID(), omMetadataManager);
    OMRequest omRequest = doPreExecute(createAbortExpiredMPURequest(volumeName, bucketName, Arrays.asList(mpuDBKeyWithHigherUpdateId, mpuDBKeyWithSameUpdateId)));
    S3ExpiredMultipartUploadsAbortRequest expiredMultipartUploadsAbortRequest = new S3ExpiredMultipartUploadsAbortRequest(omRequest);
    OMClientResponse omClientResponse = expiredMultipartUploadsAbortRequest.validateAndUpdateCache(ozoneManager, transactionId);
    assertEquals(Status.OK, omClientResponse.getOMResponse().getStatus());
    assertInMultipartInfoTable(Collections.singletonList(mpuDBKeyWithHigherUpdateId));
    assertNotInMultipartInfoTable(Collections.singletonList(mpuDBKeyWithSameUpdateId));
}

