@Test
public void testValidateAndUpdateCacheOnOverwrite() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = getKeyName();
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, getBucketLayout());
    createParentPath(volumeName, bucketName);
    // Create part key to be overwritten
    OMRequest initiateMPURequest = doPreExecuteInitiateMPU(volumeName, bucketName, keyName);
    S3InitiateMultipartUploadRequest s3InitiateMultipartUploadRequest = getS3InitiateMultipartUploadReq(initiateMPURequest);
    OMClientResponse omClientResponse = s3InitiateMultipartUploadRequest.validateAndUpdateCache(ozoneManager, 1L);
    long clientID = Time.now();
    String multipartUploadID = omClientResponse.getOMResponse().getInitiateMultiPartUploadResponse().getMultipartUploadID();
    // Take the first 2 blocks for the part key to be overwritten
    List<KeyLocation> originalKeyLocationList = getKeyLocation(5).subList(0, 2);
    List<OmKeyLocationInfo> originalKeyLocationInfos = originalKeyLocationList.stream().map(OmKeyLocationInfo::getFromProtobuf).collect(Collectors.toList());
    // Add key to open key table.
    addKeyToOpenKeyTable(volumeName, bucketName, keyName, clientID, originalKeyLocationInfos);
    OMRequest commitMultipartRequest = doPreExecuteCommitMPU(volumeName, bucketName, keyName, clientID, multipartUploadID, 1, originalKeyLocationList);
    S3MultipartUploadCommitPartRequest s3MultipartUploadCommitPartRequest = getS3MultipartUploadCommitReq(commitMultipartRequest);
    omClientResponse = s3MultipartUploadCommitPartRequest.validateAndUpdateCache(ozoneManager, 2L);
    assertSame(OzoneManagerProtocolProtos.Status.OK, omClientResponse.getOMResponse().getStatus());
    String multipartKey = omMetadataManager.getMultipartKey(volumeName, bucketName, keyName, multipartUploadID);
    OmMultipartKeyInfo multipartKeyInfo = omMetadataManager.getMultipartInfoTable().get(multipartKey);
    assertNotNull(multipartKeyInfo);
    assertEquals(1, multipartKeyInfo.getPartKeyInfoMap().size());
    PartKeyInfo partKeyInfo = multipartKeyInfo.getPartKeyInfo(1);
    assertNotNull(partKeyInfo);
    OmKeyInfo partOmKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
    // Overwrite the key
    // New client ID for the overwritten key
    clientID = Time.now();
    // Take the last 3 blocks for the overwrite key
    List<KeyLocation> overwriteKeyLocationList = getKeyLocation(5).subList(2, 5);
    List<OmKeyLocationInfo> overwriteKeyLocationInfos = overwriteKeyLocationList.stream().map(OmKeyLocationInfo::getFromProtobuf).collect(Collectors.toList());
    OMRequest overwriteOMRequest = doPreExecuteCommitMPU(volumeName, bucketName, keyName, clientID, multipartUploadID, 1, overwriteKeyLocationList);
    S3MultipartUploadCommitPartRequest overwriteRequest = getS3MultipartUploadCommitReq(overwriteOMRequest);
    addKeyToOpenKeyTable(volumeName, bucketName, keyName, clientID, overwriteKeyLocationInfos);
    omClientResponse = overwriteRequest.validateAndUpdateCache(ozoneManager, 3L);
    assertSame(OzoneManagerProtocolProtos.Status.OK, omClientResponse.getOMResponse().getStatus());
    OmMultipartKeyInfo newMultipartKeyInfo = omMetadataManager.getMultipartInfoTable().get(multipartKey);
    assertNotNull(multipartKeyInfo);
    // Part key still remains the same
    assertEquals(1, multipartKeyInfo.getPartKeyInfoMap().size());
    PartKeyInfo newPartKeyInfo = newMultipartKeyInfo.getPartKeyInfo(1);
    assertNotNull(partKeyInfo);
    // Check modification time
    assertEquals(overwriteOMRequest.getCommitMultiPartUploadRequest().getKeyArgs().getModificationTime(), newPartKeyInfo.getPartKeyInfo().getModificationTime());
    OmKeyInfo newPartOmKeyInfo = OmKeyInfo.getFromProtobuf(newPartKeyInfo.getPartKeyInfo());
    assertNotEquals(partOmKeyInfo, newPartOmKeyInfo);
    // Check block location
    List<OmKeyLocationInfo> locationsInfoListFromCommitPartRequest = overwriteOMRequest.getCommitMultiPartUploadRequest().getKeyArgs().getKeyLocationsList().stream().map(OmKeyLocationInfo::getFromProtobuf).collect(Collectors.toList());
    assertEquals(overwriteKeyLocationInfos, locationsInfoListFromCommitPartRequest);
    assertEquals(overwriteKeyLocationInfos, newPartOmKeyInfo.getLatestVersionLocations().getLocationList());
    assertEquals(1, newPartOmKeyInfo.getKeyLocationVersions().size());
    Map<String, RepeatedOmKeyInfo> toDeleteKeyList = ((S3MultipartUploadCommitPartResponse) omClientResponse).getKeyToDelete();
    // Since there are no uncommitted blocks, only the overwritten (original) key should be deleted
    assertEquals(1, toDeleteKeyList.size());
    assertEquals(originalKeyLocationList.size(), toDeleteKeyList.values().stream().findFirst().get().cloneOmKeyInfoList().get(0).getKeyLocationVersions().get(0).getLocationList().size());
}

