    assertEquals(bucketDataSize, snapshotInfoProto.getReferencedSize());
    assertEquals(bucketUsedBytes, snapshotInfoProto.getReferencedReplicatedSize());
    SnapshotInfo snapshotInfoFromProto = getFromProtobuf(snapshotInfoProto);
    // Get value from cache
    SnapshotInfo snapshotInfoInCache = getOmMetadataManager().getSnapshotInfoTable().get(key);
    assertNotNull(snapshotInfoInCache);
    assertEquals(snapshotInfoFromProto, snapshotInfoInCache);
    assertEquals(snapshotInfoInCache.getLastTransactionInfo(), TransactionInfo.valueOf(TransactionInfo.getTermIndex(1L)).toByteString());
    assertEquals(0, getOmMetrics().getNumSnapshotCreateFails());
