@ValueSource(ints = { 0, 1, 2, 3, 4 })
public void testSnapshotChainCleanup(int index) throws Exception {
    List<String> snapshots = createSnapshots(5);
    String snapShotToPurge = snapshots.get(index);
    // Before purge, check snapshot chain
    OmMetadataManagerImpl metadataManager = (OmMetadataManagerImpl) getOmMetadataManager();
    SnapshotChainManager chainManager = metadataManager.getSnapshotChainManager();
    SnapshotInfo snapInfo = metadataManager.getSnapshotInfoTable().get(snapShotToPurge);
    // Get previous and next snapshotInfos to verify if the SnapInfo
    // is changed.
    // Get previous and next snapshotInfos to verify if the SnapInfo
    // is changed.
    UUID prevPathSnapId = null;
    UUID prevGlobalSnapId = null;
    UUID nextPathSnapId = null;
    UUID nextGlobalSnapId = null;
    if (chainManager.hasPreviousPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId())) {
        prevPathSnapId = chainManager.previousPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId());
    }
    if (chainManager.hasPreviousGlobalSnapshot(snapInfo.getSnapshotId())) {
        prevGlobalSnapId = chainManager.previousGlobalSnapshot(snapInfo.getSnapshotId());
    }
    if (chainManager.hasNextPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId())) {
        nextPathSnapId = chainManager.nextPathSnapshot(snapInfo.getSnapshotPath(), snapInfo.getSnapshotId());
    }
    if (chainManager.hasNextGlobalSnapshot(snapInfo.getSnapshotId())) {
        nextGlobalSnapId = chainManager.nextGlobalSnapshot(snapInfo.getSnapshotId());
    }
    long rowsInTableBeforePurge = getOmMetadataManager().countRowsInTable(getOmMetadataManager().getSnapshotInfoTable());
    // Purge Snapshot of the given index.
    List<String> toPurgeList = Collections.singletonList(snapShotToPurge);
    OMRequest snapshotPurgeRequest = createPurgeKeysRequest(toPurgeList);
    purgeSnapshots(snapshotPurgeRequest);
    // After purge, check snapshot chain.
    if (nextPathSnapId != null) {
        SnapshotInfo nextPathSnapshotInfoAfterPurge = metadataManager.getSnapshotInfoTable().get(chainManager.getTableKey(nextPathSnapId));
        assertEquals(nextPathSnapshotInfoAfterPurge.getGlobalPreviousSnapshotId(), prevPathSnapId);
    }
    if (nextGlobalSnapId != null) {
        SnapshotInfo nextGlobalSnapshotInfoAfterPurge = metadataManager.getSnapshotInfoTable().get(chainManager.getTableKey(nextGlobalSnapId));
        assertEquals(nextGlobalSnapshotInfoAfterPurge.getGlobalPreviousSnapshotId(), prevGlobalSnapId);
    }
    assertNotEquals(rowsInTableBeforePurge, getOmMetadataManager().countRowsInTable(getOmMetadataManager().getSnapshotInfoTable()));
}

@ParameterizedTest(name = "{0}")
@MethodSource("snapshotPurgeCases")
public void testSnapshotChainInSnapshotInfoTableAfterSnapshotPurge(String description, int numberOfBuckets, int numberOfKeysPerBucket, int fromIndex, int toIndex, boolean createInBucketOrder) throws Exception {
    SnapshotChainManager chainManager = ((OmMetadataManagerImpl) getOmMetadataManager()).getSnapshotChainManager();
    int totalKeys = numberOfBuckets * numberOfKeysPerBucket;
    List<String> buckets = new ArrayList<>();
    for (int i = 0; i < numberOfBuckets; i++) {
        String bucketNameLocal = "bucket-" + UUID.randomUUID();
        OMRequestTestUtils.addVolumeAndBucketToDB(getVolumeName(), bucketNameLocal, getOmMetadataManager());
        buckets.add(bucketNameLocal);
    }
    List<SnapshotInfo> snapshotInfoList = new ArrayList<>();
    for (int i = 0; i < numberOfBuckets; i++) {
        for (int j = 0; j < numberOfKeysPerBucket; j++) {
            int bucketIndex = createInBucketOrder ? i : j;
            String bucket = buckets.get(bucketIndex % numberOfBuckets);
            String snapshotName = UUID.randomUUID().toString();
            createSnapshotCheckpoint(getVolumeName(), bucket, snapshotName);
            String snapshotTableKey = SnapshotInfo.getTableKey(getVolumeName(), bucket, snapshotName);
            SnapshotInfo snapshotInfo = getOmMetadataManager().getSnapshotInfoTable().get(snapshotTableKey);
            snapshotInfo.setDeepClean(true);
            snapshotInfo.setDeepCleanedDeletedDir(true);
            getOmMetadataManager().getSnapshotInfoTable().addCacheEntry(snapshotTableKey, snapshotInfo, System.currentTimeMillis());
            snapshotInfoList.add(getOmMetadataManager().getSnapshotInfoTable().get(snapshotTableKey));
        }
    }
    long numberOfSnapshotBeforePurge = getOmMetadataManager().countRowsInTable(getOmMetadataManager().getSnapshotInfoTable());
    assertEquals(totalKeys, numberOfSnapshotBeforePurge);
    assertEquals(totalKeys, chainManager.getGlobalSnapshotChain().size());
    Map<UUID, ByteString> expectedTransactionInfos = new HashMap<>();
    Map<UUID, Boolean> expectedDeepCleanFlags = new HashMap<>();
    // Ratis transaction uses term index 1 while creating snapshot.
    ByteString expectedLastTransactionVal = TransactionInfo.valueOf(TransactionInfo.getTermIndex(1L)).toByteString();
    for (SnapshotInfo snapshotInfo : snapshotInfoList) {
        expectedTransactionInfos.put(snapshotInfo.getSnapshotId(), expectedLastTransactionVal);
        expectedDeepCleanFlags.put(snapshotInfo.getSnapshotId(), true);
    }
    validateSnapshotOrderInSnapshotInfoTableAndSnapshotChain(snapshotInfoList, expectedTransactionInfos, expectedDeepCleanFlags);
    // Ratis transaction uses term index 200 while purging snapshot.
    expectedLastTransactionVal = TransactionInfo.valueOf(TransactionInfo.getTermIndex(200L)).toByteString();
    List<String> purgeSnapshotKeys = new ArrayList<>();
    for (int i = fromIndex; i <= toIndex; i++) {
        SnapshotInfo purgeSnapshotInfo = snapshotInfoList.get(i);
        UUID snapId = purgeSnapshotInfo.getSnapshotId();
        // expecting nextPathSnapshot & nextGlobalSnapshot in chain gets updated.
        if (chainManager.hasNextGlobalSnapshot(snapId)) {
            expectedTransactionInfos.put(chainManager.nextGlobalSnapshot(snapId), expectedLastTransactionVal);
        }
        if (chainManager.hasNextPathSnapshot(purgeSnapshotInfo.getSnapshotPath(), snapId)) {
            UUID nextPathSnapshot = chainManager.nextPathSnapshot(purgeSnapshotInfo.getSnapshotPath(), snapId);
            expectedTransactionInfos.put(nextPathSnapshot, expectedLastTransactionVal);
            expectedDeepCleanFlags.put(nextPathSnapshot, false);
            if (chainManager.hasNextPathSnapshot(purgeSnapshotInfo.getSnapshotPath(), nextPathSnapshot)) {
                UUID nextToNextPathSnapshot = chainManager.nextPathSnapshot(purgeSnapshotInfo.getSnapshotPath(), nextPathSnapshot);
                expectedTransactionInfos.put(nextToNextPathSnapshot, expectedLastTransactionVal);
                expectedDeepCleanFlags.put(nextToNextPathSnapshot, false);
            }
        }
        String purgeSnapshotKey = SnapshotInfo.getTableKey(getVolumeName(), purgeSnapshotInfo.getBucketName(), purgeSnapshotInfo.getName());
        purgeSnapshotKeys.add(purgeSnapshotKey);
    }
    OMRequest snapshotPurgeRequest = createPurgeKeysRequest(purgeSnapshotKeys);
    purgeSnapshots(snapshotPurgeRequest);
    List<SnapshotInfo> snapshotInfoListAfterPurge = new ArrayList<>();
    for (int i = 0; i < totalKeys; i++) {
        if (i < fromIndex || i > toIndex) {
            SnapshotInfo info = snapshotInfoList.get(i);
            String snapshotKey = SnapshotInfo.getTableKey(getVolumeName(), info.getBucketName(), info.getName());
            snapshotInfoListAfterPurge.add(getOmMetadataManager().getSnapshotInfoTable().get(snapshotKey));
        }
    }
    long expectNumberOfSnapshotAfterPurge = totalKeys - (toIndex - fromIndex + 1);
    long actualNumberOfSnapshotAfterPurge = getOmMetadataManager().countRowsInTable(getOmMetadataManager().getSnapshotInfoTable());
    assertEquals(expectNumberOfSnapshotAfterPurge, actualNumberOfSnapshotAfterPurge);
    assertEquals(expectNumberOfSnapshotAfterPurge, chainManager.getGlobalSnapshotChain().size());
    validateSnapshotOrderInSnapshotInfoTableAndSnapshotChain(snapshotInfoListAfterPurge, expectedTransactionInfos, expectedDeepCleanFlags);
}

