public void testAddToDBBatch() throws Exception {
    OMResponse omResponse = OMResponse.newBuilder().setRenameKeyResponse(OzoneManagerProtocolProtos.RenameKeyResponse.getDefaultInstance()).setStatus(OzoneManagerProtocolProtos.Status.OK).setCmdType(OzoneManagerProtocolProtos.Type.RenameKey).build();
    String toKeyName = UUID.randomUUID().toString();
