@ParameterizedTest
@MethodSource("bucketLayouts")
public void testAddToDBBatchWithNonEmptyParts(BucketLayout buckLayout) throws Exception {
    this.bucketLayout = buckLayout;
    String volumeName = UUID.randomUUID().toString();
    Map<OmBucketInfo, List<OmMultipartAbortInfo>> mpusToAbort = addMPUsToDB(volumeName, 3, 3);
    Map<OmBucketInfo, List<OmMultipartAbortInfo>> mpusToKeep = addMPUsToDB(volumeName, 3, 3);
    createAndCommitResponse(mpusToAbort, Status.OK);
    for (List<OmMultipartAbortInfo> abortInfos : mpusToAbort.values()) {
        for (OmMultipartAbortInfo abortInfo : abortInfos) {
            // All the associated parts of the MPU should have been moved from
            // the multipartInfoTable to the deleted table.
            assertFalse(omMetadataManager.getMultipartInfoTable().isExist(abortInfo.getMultipartKey()));
            assertFalse(omMetadataManager.getOpenKeyTable(getBucketLayout()).isExist(abortInfo.getMultipartOpenKey()));
            for (PartKeyInfo partKeyInfo : abortInfo.getOmMultipartKeyInfo().getPartKeyInfoMap()) {
                OmKeyInfo currentPartKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
                String deleteKey = omMetadataManager.getOzoneDeletePathKey(currentPartKeyInfo.getObjectID(), abortInfo.getMultipartKey());
                assertTrue(omMetadataManager.getDeletedTable().isExist(deleteKey));
            }
        }
    }
    for (List<OmMultipartAbortInfo> abortInfos : mpusToKeep.values()) {
        for (OmMultipartAbortInfo abortInfo : abortInfos) {
            // These MPUs should not have been removed from the multipartInfoTable
            // and its parts should not be in the deletedTable.
            assertTrue(omMetadataManager.getMultipartInfoTable().isExist(abortInfo.getMultipartKey()));
            assertTrue(omMetadataManager.getOpenKeyTable(getBucketLayout()).isExist(abortInfo.getMultipartOpenKey()));
            for (PartKeyInfo partKeyInfo : abortInfo.getOmMultipartKeyInfo().getPartKeyInfoMap()) {
                OmKeyInfo currentPartKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
                String deleteKey = omMetadataManager.getOzoneDeletePathKey(currentPartKeyInfo.getObjectID(), abortInfo.getMultipartKey());
                assertFalse(omMetadataManager.getDeletedTable().isExist(deleteKey));
            }
        }
    }
}

/**
 * Tests attempting aborting MPUs from the multipartINfoTable when the
 * submitted repsponse has an error status. In this case, no changes to the
 * DB should be mmade.
 */
@ParameterizedTest
@MethodSource("bucketLayouts")
public void testAddToDBBatchWithErrorResponse(BucketLayout buckLayout) throws Exception {
    this.bucketLayout = buckLayout;
    String volumeName = UUID.randomUUID().toString();
    Map<OmBucketInfo, List<OmMultipartAbortInfo>> mpusToAbort = addMPUsToDB(volumeName, 3, 3);
    createAndCommitResponse(mpusToAbort, Status.INTERNAL_ERROR);
    for (List<OmMultipartAbortInfo> multipartAbortInfos : mpusToAbort.values()) {
        for (OmMultipartAbortInfo multipartAbortInfo : multipartAbortInfos) {
            // if an error occurs in the response, the batch operation moving MPUs
            // parts from the multipartInfoTable to the deleted table should not be
            // committed
            assertTrue(omMetadataManager.getMultipartInfoTable().isExist(multipartAbortInfo.getMultipartKey()));
            for (PartKeyInfo partKeyInfo : multipartAbortInfo.getOmMultipartKeyInfo().getPartKeyInfoMap()) {
                OmKeyInfo currentPartKeyInfo = OmKeyInfo.getFromProtobuf(partKeyInfo.getPartKeyInfo());
                String deleteKey = omMetadataManager.getOzoneDeletePathKey(currentPartKeyInfo.getObjectID(), multipartAbortInfo.getMultipartKey());
                assertFalse(omMetadataManager.getDeletedTable().isExist(deleteKey));
            }
        }
    }
}

