@Test
public void testAddDBToBatch() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = getKeyName();
    String multipartUploadID = UUID.randomUUID().toString();
    addVolumeToDB(volumeName);
    addBucketToDB(volumeName, bucketName);
    String multipartOpenKey = getMultipartOpenKey(volumeName, bucketName, keyName, multipartUploadID);
    String multipartKey = omMetadataManager.getMultipartKey(volumeName, bucketName, keyName, multipartUploadID);
    String buckDBKey = omMetadataManager.getBucketKey(volumeName, bucketName);
    OmBucketInfo omBucketInfo = omMetadataManager.getBucketTable().get(buckDBKey);
    long volumeId = omMetadataManager.getVolumeId(volumeName);
    S3InitiateMultipartUploadResponse s3InitiateMultipartUploadResponse = getS3InitiateMultipartUploadResponse(volumeName, bucketName, keyName, multipartUploadID, volumeId, omBucketInfo.getObjectID());
    s3InitiateMultipartUploadResponse.addToDBBatch(omMetadataManager, batchOperation);
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    // Make sure key is present in OpenKeyTable and MPU table before Abort.
    assertNotNull(omMetadataManager.getOpenKeyTable(getBucketLayout()).get(multipartOpenKey));
    assertNotNull(omMetadataManager.getMultipartInfoTable().get(multipartKey));
    S3MultipartUploadAbortResponse s3MultipartUploadAbortResponse = createS3AbortMPUResponse(multipartKey, multipartOpenKey, s3InitiateMultipartUploadResponse.getOmMultipartKeyInfo(), omBucketInfo);
    s3MultipartUploadAbortResponse.addToDBBatch(omMetadataManager, batchOperation);
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    // Key should be deleted from OpenKeyTable and MPU table after Abort.
    assertNull(omMetadataManager.getOpenKeyTable(getBucketLayout()).get(multipartOpenKey));
    assertNull(omMetadataManager.getMultipartInfoTable().get(multipartKey));
    // As no parts are created, so no entries should be there in delete table.
    assertEquals(0, omMetadataManager.countRowsInTable(omMetadataManager.getDeletedTable()));
}

@Test
public void testAddDBToBatchWithParts() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = getKeyName();
    String multipartUploadID = UUID.randomUUID().toString();
    addVolumeToDB(volumeName);
    addBucketToDB(volumeName, bucketName);
    String multipartOpenKey = getMultipartOpenKey(volumeName, bucketName, keyName, multipartUploadID);
    String multipartKey = omMetadataManager.getMultipartKey(volumeName, bucketName, keyName, multipartUploadID);
    OmBucketInfo omBucketInfo = OmBucketInfo.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setCreationTime(Time.now()).build();
    S3InitiateMultipartUploadResponse s3InitiateMultipartUploadResponse = createS3InitiateMPUResponse(volumeName, bucketName, keyName, multipartUploadID);
    s3InitiateMultipartUploadResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Add some dummy parts for testing.
    // Not added any key locations, as this just test is to see entries are
    // adding to delete table or not.
    OmMultipartKeyInfo omMultipartKeyInfo = s3InitiateMultipartUploadResponse.getOmMultipartKeyInfo();
    PartKeyInfo part1 = createPartKeyInfo(volumeName, bucketName, keyName, 1);
    PartKeyInfo part2 = createPartKeyInfo(volumeName, bucketName, keyName, 2);
    addPart(1, part1, omMultipartKeyInfo);
    addPart(2, part2, omMultipartKeyInfo);
    S3MultipartUploadAbortResponse s3MultipartUploadAbortResponse = createS3AbortMPUResponse(multipartKey, multipartOpenKey, s3InitiateMultipartUploadResponse.getOmMultipartKeyInfo(), omBucketInfo);
    s3MultipartUploadAbortResponse.addToDBBatch(omMetadataManager, batchOperation);
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    assertNull(omMetadataManager.getOpenKeyTable(getBucketLayout()).get(multipartKey));
    assertNull(omMetadataManager.getMultipartInfoTable().get(multipartKey));
    // As 2 parts are created, so 2 entries should be there in delete table.
    assertEquals(2, omMetadataManager.countRowsInTable(omMetadataManager.getDeletedTable()));
    String part1DeletedKeyName = omMetadataManager.getOzoneDeletePathKey(omMultipartKeyInfo.getPartKeyInfo(1).getPartKeyInfo().getObjectID(), multipartKey);
    String part2DeletedKeyName = omMetadataManager.getOzoneDeletePathKey(omMultipartKeyInfo.getPartKeyInfo(2).getPartKeyInfo().getObjectID(), multipartKey);
    assertNotNull(omMetadataManager.getDeletedTable().get(part1DeletedKeyName));
    assertNotNull(omMetadataManager.getDeletedTable().get(part2DeletedKeyName));
    RepeatedOmKeyInfo ro = omMetadataManager.getDeletedTable().get(part1DeletedKeyName);
    assertEquals(OmKeyInfo.getFromProtobuf(part1.getPartKeyInfo()), ro.getOmKeyInfoList().get(0));
    ro = omMetadataManager.getDeletedTable().get(part2DeletedKeyName);
    assertEquals(OmKeyInfo.getFromProtobuf(part2.getPartKeyInfo()), ro.getOmKeyInfoList().get(0));
}

