    assertEquals(0, omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable()));
    // Prepare the table, write an entry with SnapshotCreate
    OMSnapshotResponseTestUtil.addVolumeBucketInfoToTable(omMetadataManager, volumeName, bucketName);
    OMSnapshotCreateResponse omSnapshotCreateResponse = new OMSnapshotCreateResponse(OMResponse.newBuilder().setCmdType(Type.CreateSnapshot).setStatus(Status.OK).setCreateSnapshotResponse(CreateSnapshotResponse.newBuilder().setSnapshotInfo(snapshotInfo.getProtobuf()).build()).build(), snapshotInfo);
    omSnapshotCreateResponse.addToDBBatch(omMetadataManager, batchOperation);
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    // Confirm snapshot directory was created
    String snapshotDir = OmSnapshotManager.getSnapshotPath(ozoneConfiguration, snapshotInfo);
    assertTrue((new File(snapshotDir)).exists());
    // Confirm table has 1 entry
    assertEquals(1, omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable()));
    try (Table.KeyValueIterator<String, SnapshotInfo> iter = omMetadataManager.getSnapshotInfoTable().iterator()) {
        // Check snapshotInfo entry content
        Table.KeyValue<String, SnapshotInfo> keyValue = iter.next();
        SnapshotInfo storedInfo = keyValue.getValue();
        assertEquals(snapshotInfo.getTableKey(), keyValue.getKey());
        assertEquals(snapshotInfo, storedInfo);
        assertEquals(SNAPSHOT_ACTIVE, snapshotInfo.getSnapshotStatus());
    }
    // Update snapshot status to DELETED
    snapshotInfo.setSnapshotStatus(SNAPSHOT_DELETED);
    // Trigger OMSnapshotDeleteResponse#addToDBBatch
    OMSnapshotDeleteResponse omSnapshotDeleteResponse = new OMSnapshotDeleteResponse(OMResponse.newBuilder().setCmdType(Type.DeleteSnapshot).setStatus(Status.OK).setDeleteSnapshotResponse(DeleteSnapshotResponse.newBuilder().build()).build(), snapshotInfo.getTableKey(), snapshotInfo);
