    assertEquals(1, omMetadataManager.countRowsInTable(omMetadataManager.getSnapshotInfoTable()));
    try (Table.KeyValueIterator<String, SnapshotInfo> iter = omMetadataManager.getSnapshotInfoTable().iterator()) {
        // 2. snapshot status should now be DELETED
        Table.KeyValue<String, SnapshotInfo> keyValue = iter.next();
        SnapshotInfo storedInfo = keyValue.getValue();
        assertEquals(snapshotInfo.getTableKey(), keyValue.getKey());
        assertEquals(snapshotInfo, storedInfo);
        assertEquals(SNAPSHOT_DELETED, snapshotInfo.getSnapshotStatus());
    }
}

@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testMoveTableKeysToNextSnapshot(boolean nextSnapshotExists) throws Exception {
    OmBucketInfo omBucketInfo = OMKeyRequest.getBucketInfo(getOmMetadataManager(), getVolumeName(), getBucketName());
    createSnapshots(nextSnapshotExists, omBucketInfo.getObjectID());
    try (UncheckedAutoCloseableSupplier<OmSnapshot> snapshot1 = getOmSnapshotManager().getSnapshot(getVolumeName(), getBucketName(), snapshotName1);
        UncheckedAutoCloseableSupplier<OmSnapshot> snapshot2 = nextSnapshotExists ? getOmSnapshotManager().getSnapshot(getVolumeName(), getBucketName(), snapshotName2) : null) {
        OmSnapshot snapshot = snapshot1.get();
        List<OzoneManagerProtocolProtos.SnapshotMoveKeyInfos> deletedTable = new ArrayList<>();
        List<OzoneManagerProtocolProtos.SnapshotMoveKeyInfos> deletedDirTable = new ArrayList<>();
        List<HddsProtos.KeyValue> renamedTable = new ArrayList<>();
        Map<String, String> renameEntries = new HashMap<>();
        snapshot.getMetadataManager().getDeletedTable().iterator().forEachRemaining(entry -> {
            deletedTable.add(OzoneManagerProtocolProtos.SnapshotMoveKeyInfos.newBuilder().setKey(entry.getKey()).addAllKeyInfos(entry.getValue().getOmKeyInfoList().stream().map(omKeyInfo -> omKeyInfo.getProtobuf(ClientVersion.CURRENT_VERSION)).collect(Collectors.toList())).build());
        });
        snapshot.getMetadataManager().getDeletedDirTable().iterator().forEachRemaining(entry -> {
            deletedDirTable.add(OzoneManagerProtocolProtos.SnapshotMoveKeyInfos.newBuilder().setKey(entry.getKey()).addKeyInfos(entry.getValue().getProtobuf(ClientVersion.CURRENT_VERSION)).build());
        });
        snapshot.getMetadataManager().getSnapshotRenamedTable().iterator().forEachRemaining(entry -> {
            renamedTable.add(HddsProtos.KeyValue.newBuilder().setKey(entry.getKey()).setValue(entry.getValue()).build());
            renameEntries.put(entry.getKey(), entry.getValue());
        });
        OMSnapshotMoveTableKeysResponse response = new OMSnapshotMoveTableKeysResponse(OzoneManagerProtocolProtos.OMResponse.newBuilder().setStatus(OzoneManagerProtocolProtos.Status.OK).setCmdType(OzoneManagerProtocolProtos.Type.SnapshotMoveTableKeys).build(), snapshotInfo1, nextSnapshotExists ? snapshotInfo2 : null, omBucketInfo.getObjectID(), deletedTable, deletedDirTable, renamedTable);
        try (BatchOperation batchOperation = getOmMetadataManager().getStore().initBatchOperation()) {
            response.addToDBBatch(getOmMetadataManager(), batchOperation);
            getOmMetadataManager().getStore().commitBatchOperation(batchOperation);
        }
        Assertions.assertTrue(snapshot.getMetadataManager().getDeletedTable().isEmpty());
        Assertions.assertTrue(snapshot.getMetadataManager().getDeletedDirTable().isEmpty());
        Assertions.assertTrue(snapshot.getMetadataManager().getSnapshotRenamedTable().isEmpty());
        OMMetadataManager nextMetadataManager = nextSnapshotExists ? snapshot2.get().getMetadataManager() : getOmMetadataManager();
        AtomicInteger count = new AtomicInteger();
        nextMetadataManager.getDeletedTable().iterator().forEachRemaining(entry -> {
            count.getAndIncrement();
            int maxCount = count.get() >= 6 && count.get() <= 8 ? 20 : 10;
            Assertions.assertEquals(maxCount, entry.getValue().getOmKeyInfoList().size());
            List<Long> versions = entry.getValue().getOmKeyInfoList().stream().map(OmKeyInfo::getKeyLocationVersions).map(omKeyInfo -> omKeyInfo.get(0).getVersion()).collect(Collectors.toList());
            List<Long> expectedVersions = new ArrayList<>();
            if (maxCount == 20) {
                expectedVersions.addAll(LongStream.range(10, 20).boxed().collect(Collectors.toList()));
            }
            expectedVersions.addAll(LongStream.range(0, 10).boxed().collect(Collectors.toList()));
            Assertions.assertEquals(expectedVersions, versions);
        });
        Assertions.assertEquals(15, count.get());
        count.set(0);
        nextMetadataManager.getDeletedDirTable().iterator().forEachRemaining(entry -> count.getAndIncrement());
        Assertions.assertEquals(15, count.get());
        count.set(0);
        nextMetadataManager.getSnapshotRenamedTable().iterator().forEachRemaining(entry -> {
            String expectedValue = renameEntries.getOrDefault(entry.getKey(), entry.getValue());
            Assertions.assertEquals(expectedValue, entry.getValue());
            count.getAndIncrement();
        });
        Assertions.assertEquals(15, count.get());
    }
}

@Test
public void checkAnnotationAndTableName() {
    OMMetadataManager omMetadataManager = om.getMetadataManager();
    Set<String> tables = omMetadataManager.listTableNames();
    Set<Class<? extends OMClientResponse>> subTypes = responseClasses();
    // OMEchoRPCWriteResponse does not need CleanupTable.
    subTypes.remove(OMEchoRPCWriteResponse.class);
    subTypes.remove(DummyOMClientResponse.class);
    subTypes.forEach(aClass -> {
        if (Modifier.isAbstract(aClass.getModifiers())) {
            assertFalse(aClass.isAnnotationPresent(CleanupTableInfo.class), aClass + " is an abstract class and should not contain CleanupTableInfo annotations");
            return;
        } else {
            assertTrue(aClass.isAnnotationPresent(CleanupTableInfo.class), aClass + " does not have annotation of" + " CleanupTableInfo");
        }
        CleanupTableInfo annotation = aClass.getAnnotation(CleanupTableInfo.class);
        assertNotNull(annotation, "CleanupTableInfo is null for class " + aClass.getSimpleName());
        String[] cleanupTables = annotation.cleanupTables();
        boolean cleanupAll = annotation.cleanupAll();
        if (cleanupTables.length >= 1) {
            assertTrue(Arrays.stream(cleanupTables).allMatch(tables::contains));
        } else {
            assertTrue(cleanupAll);
        }
    });
    reset(om);
}

