 * @throws RocksDBException if RocksDB encounters an error.
 */
@ParameterizedTest
@MethodSource("testReclaimableFilterArguments")
public void testExclusiveSizeCalculationWithNonReclaimableKey(int actualNumberOfSnapshots, int index) throws IOException, RocksDBException {
    setup(2, actualNumberOfSnapshots, index, 4, 2);
    String volume = getVolumes().get(3);
    String bucket = getBuckets().get(1);
    index = Math.min(index, actualNumberOfSnapshots);
    OmKeyInfo keyInfo = getMockedOmKeyInfo(1, 1, 4);
    OmKeyInfo prevKeyInfo = index - 1 >= 0 ? getMockedOmKeyInfo(1, 2, 5) : null;
    OmKeyInfo prevPrevKeyInfo = index - 2 >= 0 ? getMockedOmKeyInfo(1, 3, 6) : null;
    if (prevKeyInfo != null) {
        getMockedSnapshotUtils().when(() -> SnapshotUtils.isBlockLocationInfoSame(eq(prevKeyInfo), eq(keyInfo))).thenReturn(true);
    }
    if (prevPrevKeyInfo != null) {
        getMockedSnapshotUtils().when(() -> SnapshotUtils.isBlockLocationInfoSame(eq(prevPrevKeyInfo), eq(prevKeyInfo))).thenReturn(true);
    }
    Optional<AtomicLong> size = Optional.ofNullable(prevKeyInfo).map(i -> prevPrevKeyInfo == null ? new AtomicLong(2) : null);
    Optional<AtomicLong> replicatedSize = Optional.ofNullable(prevKeyInfo).map(i -> prevPrevKeyInfo == null ? new AtomicLong(5) : null);
    testReclaimableKeyFilter(volume, bucket, index, keyInfo, prevKeyInfo, prevPrevKeyInfo, prevKeyInfo == null, size, replicatedSize);
    if (prevPrevKeyInfo != null) {
        getMockedSnapshotUtils().when(() -> SnapshotUtils.isBlockLocationInfoSame(eq(prevPrevKeyInfo), eq(prevKeyInfo))).thenReturn(false);
    }
    if (prevKeyInfo != null) {
        size = Optional.of(size.orElse(new AtomicLong()));
        replicatedSize = Optional.of(replicatedSize.orElse(new AtomicLong()));
        size.get().addAndGet(2L);
        replicatedSize.get().addAndGet(5L);
    }
    testReclaimableKeyFilter(volume, bucket, index, keyInfo, prevKeyInfo, prevPrevKeyInfo, prevKeyInfo == null, size, replicatedSize);
    OmKeyInfo prevPrevKeyInfo1;
    if (prevPrevKeyInfo != null) {
        prevPrevKeyInfo1 = getMockedOmKeyInfo(2, 3, 4);
        getMockedSnapshotUtils().when(() -> SnapshotUtils.isBlockLocationInfoSame(eq(prevPrevKeyInfo1), eq(prevKeyInfo))).thenReturn(true);
    } else {
        prevPrevKeyInfo1 = null;
    }
    if (prevKeyInfo != null) {
        size = Optional.of(size.orElse(new AtomicLong()));
        replicatedSize = Optional.of(replicatedSize.orElse(new AtomicLong()));
        size.get().addAndGet(2L);
        replicatedSize.get().addAndGet(5L);
    }
    testReclaimableKeyFilter(volume, bucket, index, keyInfo, prevKeyInfo, prevPrevKeyInfo1, prevKeyInfo == null, size, replicatedSize);
}

