public void testGetAbsolutePathForValidObjectIDs() throws IOException {
    Map<Integer, List<Integer>> dirMap = ImmutableMap.of(1, Lists.newArrayList(2, 3, 4, 5, 6), 2, Lists.newArrayList(7, 8, 9, 10, 11), 3, Lists.newArrayList(12, 13, 14, 15), 9, Lists.newArrayList(16), 14, Lists.newArrayList(17), 18, Lists.newArrayList(19, 20));
    String prefix = "/vol/buck/";
    FSODirectoryPathResolver fsoDirectoryPathResolver = new FSODirectoryPathResolver(prefix, 1, getMockedDirectoryInfoTable(prefix, dirMap));
    Set<Long> objIds = Sets.newHashSet(17L, 9L, 10L, 15L, 4L, 3L, 1L);
    Set<Long> invalidObjIds = Sets.newHashSet(17L, 9L, 10L, 15L, 4L, 3L, 1L, 19L);
    Map<Long, Path> absolutePathMap = fsoDirectoryPathResolver.getAbsolutePathForObjectIDs(Optional.of(objIds));
    Map<Long, String> pathMapping = ImmutableMap.<Long, String>builder().put(17L, "/dir3/dir14/dir17").put(9L, "/dir2/dir9").put(10L, "/dir2/dir10").put(15L, "/dir3/dir15").put(4L, "/dir4").put(3L, "/dir3").put(1L, "/").build();
    Map<Long, Path> expectedPaths = pathMapping.entrySet().stream().collect(ImmutableMap.toImmutableMap(Map.Entry::getKey, e -> Paths.get(e.getValue())));
    assertEquals(expectedPaths, absolutePathMap);
