/**
 * Test mocks the SSTFileReader to return object Ids from 0-50
 * when not reading tombstones & Object Ids 0-100 when reading tombstones.
 * Creating a mock snapshot table where the fromSnapshot Table contains
 * Object Ids in the range 0-25 & 50-100 and toSnapshot Table contains data
 * with object Ids in the range 0-50.
 * Function should return 25-50 in the new Persistent map.
 * In the case of reading tombstones old Snapshot Persistent map should have
 * object Ids in the range 50-100 & should be empty otherwise
 */
@ParameterizedTest
@CsvSource({ "false," + DIRECTORY_TABLE, "true," + DIRECTORY_TABLE, "false," + FILE_TABLE, "true," + FILE_TABLE, "false," + KEY_TABLE, "true," + KEY_TABLE })
public void testObjectIdMapWithTombstoneEntries(boolean nativeLibraryLoaded, String snapshotTableName) throws IOException, RocksDBException {
    Set<String> keysIncludingTombstones = IntStream.range(0, 100).boxed().map(i -> (i + 100) + "/key" + i).collect(Collectors.toSet());
    // Mocking SST file with keys in SST file excluding tombstones
    Set<String> keysExcludingTombstones = IntStream.range(0, 50).boxed().map(i -> (i + 100) + "/key" + i).collect(Collectors.toSet());
    // Mocking SSTFileReader functions to return the above keys list.
    try (MockedConstruction<SstFileSetReader> mockedSSTFileReader = mockConstruction(SstFileSetReader.class, (mock, context) -> {
        when(mock.getKeyStreamWithTombstone(any(), any())).thenReturn(keysIncludingTombstones.stream());
        when(mock.getKeyStream(any(), any())).thenReturn(keysExcludingTombstones.stream());
    })) {
        Map<String, WithParentObjectId> toSnapshotTableMap = IntStream.concat(IntStream.range(0, 25), IntStream.range(50, 100)).boxed().collect(Collectors.toMap(i -> (i + 100) + "/key" + i, i -> getKeyInfo(i, i, i + 100, snapshotTableName)));
        Table<String, ? extends WithParentObjectId> toSnapshotTable = getMockedTable(toSnapshotTableMap, snapshotTableName);
        Map<String, WithParentObjectId> fromSnapshotTableMap = IntStream.range(0, 50).boxed().collect(Collectors.toMap(i -> (i + 100) + "/key" + i, i -> getKeyInfo(i, i, i + 100, snapshotTableName)));
        Table<String, ? extends WithParentObjectId> fromSnapshotTable = getMockedTable(fromSnapshotTableMap, snapshotTableName);
        SnapshotDiffManager spy = spy(snapshotDiffManager);
        Boolean isKeyInBucket = doAnswer(invocation -> {
            String[] split = invocation.getArgument(0, String.class).split("/");
            String keyName = split[split.length - 1];
            return Integer.parseInt(keyName.substring(3)) % 2 == 0;
        }).when(spy).isKeyInBucket(anyString(), anyMap(), anyString());
        assertFalse(isKeyInBucket);
        PersistentMap<byte[], byte[]> oldObjectIdKeyMap = new StubbedPersistentMap<>();
        PersistentMap<byte[], byte[]> newObjectIdKeyMap = new SnapshotTestUtils.StubbedPersistentMap<>();
        PersistentMap<byte[], Boolean> objectIdsToCheck = new SnapshotTestUtils.StubbedPersistentMap<>();
        Set<Long> oldParentIds = Sets.newHashSet();
        Set<Long> newParentIds = Sets.newHashSet();
        spy.addToObjectIdMap(toSnapshotTable, fromSnapshotTable, Sets.newHashSet("dummy.sst"), nativeLibraryLoaded, oldObjectIdKeyMap, newObjectIdKeyMap, objectIdsToCheck, Optional.of(oldParentIds), Optional.of(newParentIds), ImmutableMap.of(DIRECTORY_TABLE, "", KEY_TABLE, "", FILE_TABLE, ""), "");
        try (ClosableIterator<Map.Entry<byte[], byte[]>> oldObjectIdIter = oldObjectIdKeyMap.iterator()) {
            int oldObjectIdCnt = 0;
            while (oldObjectIdIter.hasNext()) {
                Map.Entry<byte[], byte[]> v = oldObjectIdIter.next();
                long objectId = codecRegistry.asObject(v.getKey(), Long.class);
                assertEquals(0, objectId % 2);
                assertThat(objectId).isGreaterThanOrEqualTo(50);
                assertThat(objectId).isLessThan(100);
                oldObjectIdCnt += 1;
            }
            assertEquals(nativeLibraryLoaded ? 25 : 0, oldObjectIdCnt);
        }
        try (ClosableIterator<Map.Entry<byte[], byte[]>> newObjectIdIter = newObjectIdKeyMap.iterator()) {
            int newObjectIdCnt = 0;
            while (newObjectIdIter.hasNext()) {
                Map.Entry<byte[], byte[]> v = newObjectIdIter.next();
                long objectId = codecRegistry.asObject(v.getKey(), Long.class);
                assertEquals(0, objectId % 2);
                assertThat(objectId).isGreaterThanOrEqualTo(26);
                assertThat(objectId).isLessThan(50);
                newObjectIdCnt += 1;
            }
            assertEquals(12, newObjectIdCnt);
        }
        try (ClosableIterator<Entry<byte[], Boolean>> objectIdsToCheckIter = objectIdsToCheck.iterator()) {
            int objectIdCnt = 0;
            while (objectIdsToCheckIter.hasNext()) {
                Entry<byte[], Boolean> entry = objectIdsToCheckIter.next();
                byte[] v = entry.getKey();
                long objectId = codecRegistry.asObject(v, Long.class);
                assertEquals(0, objectId % 2);
                assertThat(objectId).isGreaterThanOrEqualTo(26);
                assertThat(objectId).isLessThan(nativeLibraryLoaded ? 100 : 50);
                objectIdCnt += 1;
            }
            assertEquals(nativeLibraryLoaded ? 37 : 12, objectIdCnt);
        }
    }
}

@Test
public void testGenerateDiffReport() throws IOException {
    PersistentMap<byte[], byte[]> oldObjectIdKeyMap = new StubbedPersistentMap<>();
    PersistentMap<byte[], byte[]> newObjectIdKeyMap = new StubbedPersistentMap<>();
    PersistentMap<byte[], Boolean> objectIdToIsDirMap = new SnapshotTestUtils.StubbedPersistentMap<>();
    Map<Long, SnapshotDiffReport.DiffType> diffMap = new HashMap<>();
    LongStream.range(0, 100).forEach(objectId -> {
        try {
            String key = "key" + objectId;
            byte[] objectIdVal = codecRegistry.asRawData(objectId);
            byte[] keyBytes = codecRegistry.asRawData(key);
            if (objectId >= 0 && objectId <= 25 || objectId >= 50 && objectId <= 100) {
                oldObjectIdKeyMap.put(objectIdVal, keyBytes);
            }
            if (objectId >= 0 && objectId <= 25 && (objectId % 4 == 0 || objectId % 4 == 2) || objectId > 25 && objectId < 50) {
                newObjectIdKeyMap.put(objectIdVal, keyBytes);
            }
            if (objectId >= 0 && objectId <= 25 && objectId % 4 == 1) {
                String renamedKey = "renamed-key" + objectId;
                byte[] renamedKeyBytes = codecRegistry.asRawData(renamedKey);
                newObjectIdKeyMap.put(objectIdVal, renamedKeyBytes);
                diffMap.put(objectId, SnapshotDiffReport.DiffType.RENAME);
            }
            objectIdToIsDirMap.put(objectIdVal, false);
            if (objectId >= 50 && objectId <= 100 || objectId >= 0 && objectId <= 25 && objectId % 4 > 2) {
                diffMap.put(objectId, SnapshotDiffReport.DiffType.DELETE);
            }
            if (objectId >= 0 && objectId <= 25 && objectId % 4 == 0) {
                diffMap.put(objectId, SnapshotDiffReport.DiffType.RENAME);
            }
            if (objectId >= 0 && objectId <= 25 && objectId % 4 == 2) {
                diffMap.put(objectId, SnapshotDiffReport.DiffType.MODIFY);
            }
            if (objectId > 25 && objectId < 50) {
                diffMap.put(objectId, SnapshotDiffReport.DiffType.CREATE);
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    });
    String volumeName = "vol";
    String bucketName = "buck";
    String fromSnapName = "fs";
    String toSnapName = "ts";
    try (MockedStatic<SnapshotUtils> mockedSnapshotUtils = mockStatic(SnapshotUtils.class)) {
        mockedSnapshotUtils.when(() -> SnapshotUtils.isBlockLocationInfoSame(any(OmKeyInfo.class), any(OmKeyInfo.class))).thenAnswer(i -> {
            int keyVal = Integer.parseInt(((OmKeyInfo) i.getArgument(0)).getKeyName().substring(3));
            return !(keyVal % 4 == 2 && keyVal >= 0 && keyVal <= 25 && keyVal % 8 == 0);
        });
        Table<String, OmKeyInfo> fromSnapTable = mock(Table.class);
        Table<String, OmKeyInfo> toSnapTable = mock(Table.class);
        when(fromSnapTable.get(anyString())).thenAnswer(i -> {
            OmKeyInfo keyInfo = mock(OmKeyInfo.class);
            when(keyInfo.getKeyName()).thenReturn(i.getArgument(0));
            when(keyInfo.isKeyInfoSame(any(OmKeyInfo.class), eq(false), eq(false), eq(false), eq(false), eq(true))).thenAnswer(k -> {
                int keyVal = Integer.parseInt(((String) i.getArgument(0)).substring(3));
                return !(keyVal % 4 == 2 && keyVal >= 0 && keyVal <= 25 && keyVal % 8 != 0);
            });
            return keyInfo;
        });
        when(toSnapTable.get(anyString())).thenAnswer(i -> {
            OmKeyInfo keyInfo = mock(OmKeyInfo.class);
            when(keyInfo.getKeyName()).thenReturn(i.getArgument(0));
            return keyInfo;
        });
        when(fromSnapTable.getName()).thenReturn("table");
        Map<String, String> tablePrefixes = mock(Map.class);
        when(tablePrefixes.get(anyString())).thenReturn("");
        SnapshotDiffManager spy = spy(snapshotDiffManager);
        doReturn(true).when(spy).areDiffJobAndSnapshotsActive(volumeName, bucketName, fromSnapName, toSnapName);
        long totalDiffEntries = spy.generateDiffReport("jobId", fromSnapTable, toSnapTable, null, null, objectIdToIsDirMap, oldObjectIdKeyMap, newObjectIdKeyMap, volumeName, bucketName, fromSnapName, toSnapName, false, Optional.empty(), Optional.empty(), tablePrefixes);
        assertEquals(100, totalDiffEntries);
        SnapshotDiffJob snapshotDiffJob = new SnapshotDiffJob(0, "jobId", JobStatus.DONE, "vol", "buck", "fs", "ts", false, true, diffMap.size(), null, 0.0);
        SnapshotDiffReportOzone snapshotDiffReportOzone = snapshotDiffManager.createPageResponse(snapshotDiffJob, "vol", "buck", "fs", "ts", 0, Integer.MAX_VALUE);
        Set<SnapshotDiffReport.DiffType> expectedOrder = new LinkedHashSet<>();
        expectedOrder.add(SnapshotDiffReport.DiffType.DELETE);
        expectedOrder.add(SnapshotDiffReport.DiffType.RENAME);
        expectedOrder.add(SnapshotDiffReport.DiffType.CREATE);
        expectedOrder.add(SnapshotDiffReport.DiffType.MODIFY);
        Set<SnapshotDiffReport.DiffType> actualOrder = new LinkedHashSet<>();
        for (DiffReportEntry entry : snapshotDiffReportOzone.getDiffList()) {
            actualOrder.add(entry.getType());
            long objectId = Long.parseLong(DFSUtilClient.bytes2String(entry.getSourcePath()).substring(3));
            assertEquals(diffMap.get(objectId), entry.getType());
        }
        assertEquals(expectedOrder, actualOrder);
    }
}

