@Test
public void testListKeysWithFewDeleteEntriesInCache() throws Exception {
    String volumeNameA = "volumeA";
    String ozoneBucket = "ozoneBucket";
    // Create volumes and bucket.
    OMRequestTestUtils.addVolumeToDB(volumeNameA, omMetadataManager);
    addBucketsToCache(volumeNameA, ozoneBucket);
    String prefixKeyA = "key-a";
    TreeSet<String> keysASet = new TreeSet<>();
    TreeSet<String> deleteKeySet = new TreeSet<>();
    for (int i = 1; i <= 100; i++) {
        if (i % 2 == 0) {
            keysASet.add(prefixKeyA + i);
            addKeysToOM(volumeNameA, ozoneBucket, prefixKeyA + i, i);
        } else {
            addKeysToOM(volumeNameA, ozoneBucket, prefixKeyA + i, i);
            String key = omMetadataManager.getOzoneKey(volumeNameA, ozoneBucket, prefixKeyA + i);
            // Mark as deleted in cache.
            omMetadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(key), CacheValue.get(100L));
            deleteKeySet.add(key);
        }
    }
    // Now list keys which match with prefixKeyA.
    List<OmKeyInfo> omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, null, prefixKeyA, 100).getKeys();
    // As in total 100, 50 are marked for delete. It should list only 50 keys.
    assertEquals(50, omKeyInfoList.size());
    assertEquals(50, deleteKeySet.size());
    TreeSet<String> expectedKeys = new TreeSet<>();
    for (OmKeyInfo omKeyInfo : omKeyInfoList) {
        expectedKeys.add(omKeyInfo.getKeyName());
        assertTrue(omKeyInfo.getKeyName().startsWith(prefixKeyA));
    }
    assertEquals(expectedKeys, keysASet);
    // Now get key count by 10.
    String startKey = null;
    expectedKeys = new TreeSet<>();
    for (int i = 0; i < 5; i++) {
        omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, startKey, prefixKeyA, 10).getKeys();
        System.out.println(i);
        assertEquals(10, omKeyInfoList.size());
        for (OmKeyInfo omKeyInfo : omKeyInfoList) {
            expectedKeys.add(omKeyInfo.getKeyName());
            assertTrue(omKeyInfo.getKeyName().startsWith(prefixKeyA));
            startKey = omKeyInfo.getKeyName();
        }
    }
    assertEquals(keysASet, expectedKeys);
    // As now we have iterated all 50 buckets, calling next time should
    // return empty list.
    omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, startKey, prefixKeyA, 10).getKeys();
    assertEquals(omKeyInfoList.size(), 0);
}

@Test
public void testListKeysWithEntriesInCacheAndDB() throws Exception {
    String volumeNameA = "volumeA";
    String ozoneBucket = "ozoneBucket";
    // Create volumes and bucket.
    OMRequestTestUtils.addVolumeToDB(volumeNameA, omMetadataManager);
    addBucketsToCache(volumeNameA, ozoneBucket);
    String prefixKeyA = "key-a";
    TreeMap<String, OmKeyInfo> keyAMap = new TreeMap<>();
    for (int i = 1; i <= 100; i++) {
        if (i % 2 == 0) {
            // Add to DB
            addKeysToOM(volumeNameA, ozoneBucket, prefixKeyA + i, i);
            String key = omMetadataManager.getOzoneKey(volumeNameA, ozoneBucket, prefixKeyA + i);
            // Key is overwritten in cache (with higher updateID),
            // but the cache has not been flushed to the DB
            OmKeyInfo overwriteKey = OMRequestTestUtils.createOmKeyInfo(volumeNameA, ozoneBucket, prefixKeyA + i, RatisReplicationConfig.getInstance(ONE)).setUpdateID(100L).build();
            omMetadataManager.getKeyTable(getDefaultBucketLayout()).addCacheEntry(new CacheKey<>(key), CacheValue.get(100L, overwriteKey));
            keyAMap.put(prefixKeyA + i, overwriteKey);
        } else {
            // Add to cache
            OmKeyInfo omKeyInfo = addKeysToOM(volumeNameA, ozoneBucket, prefixKeyA + i, i);
            keyAMap.put(prefixKeyA + i, omKeyInfo);
        }
    }
    // Now list keys which match with prefixKeyA.
    List<OmKeyInfo> omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, null, prefixKeyA, 1000).getKeys();
    assertEquals(100, omKeyInfoList.size());
    TreeMap<String, OmKeyInfo> currentKeys = new TreeMap<>();
    for (OmKeyInfo omKeyInfo : omKeyInfoList) {
        currentKeys.put(omKeyInfo.getKeyName(), omKeyInfo);
        assertTrue(omKeyInfo.getKeyName().startsWith(prefixKeyA));
    }
    assertEquals(keyAMap, currentKeys);
    omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, null, prefixKeyA, 100).getKeys();
    assertEquals(100, omKeyInfoList.size());
    omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, null, prefixKeyA, 98).getKeys();
    assertEquals(98, omKeyInfoList.size());
    omKeyInfoList = omMetadataManager.listKeys(volumeNameA, ozoneBucket, null, prefixKeyA, 1).getKeys();
    assertEquals(1, omKeyInfoList.size());
}

/**
 * Tests inner impl of listOpenFiles with different bucket types with and
 * without pagination. NOTE: This UT does NOT test hsync here since the hsync
 * status check is done purely on the client side.
 * @param bucketLayout BucketLayout
 */
@ParameterizedTest
@EnumSource
public void testListOpenFiles(BucketLayout bucketLayout) throws Exception {
    final long clientID = 1000L;
    String volumeName = "volume-lof";
    String bucketName = "bucket-" + bucketLayout.name().toLowerCase();
    String keyPrefix = "key";
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, bucketLayout);
    long volumeId = -1L, bucketId = -1L;
    if (bucketLayout.isFileSystemOptimized()) {
        volumeId = omMetadataManager.getVolumeId(volumeName);
        bucketId = omMetadataManager.getBucketId(volumeName, bucketName);
    }
    int numOpenKeys = 3;
    for (int i = 0; i < numOpenKeys; i++) {
        final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, keyPrefix + i, RatisReplicationConfig.getInstance(ONE)).build();
        final String dbOpenKeyName;
        if (bucketLayout.isFileSystemOptimized()) {
            keyInfo.setParentObjectID(i);
            keyInfo.setFileName(OzoneFSUtils.getFileName(keyInfo.getKeyName()));
            OMRequestTestUtils.addFileToKeyTable(true, false, keyInfo.getFileName(), keyInfo, clientID, 0L, omMetadataManager);
            dbOpenKeyName = omMetadataManager.getOpenFileName(volumeId, bucketId, keyInfo.getParentObjectID(), keyInfo.getFileName(), clientID);
        } else {
            OMRequestTestUtils.addKeyToTable(true, false, keyInfo, clientID, 0L, omMetadataManager);
            dbOpenKeyName = omMetadataManager.getOpenKey(volumeName, bucketName, keyInfo.getKeyName(), clientID);
        }
    }
    String dbPrefix;
    if (bucketLayout.isFileSystemOptimized()) {
        dbPrefix = omMetadataManager.getOzoneKeyFSO(volumeName, bucketName, "");
    } else {
        dbPrefix = omMetadataManager.getOzoneKey(volumeName, bucketName, "");
    }
    // Without pagination
    ListOpenFilesResult res = omMetadataManager.listOpenFiles(bucketLayout, 100, dbPrefix, false, dbPrefix);
    assertEquals(numOpenKeys, res.getTotalOpenKeyCount());
    assertFalse(res.hasMore());
    List<OpenKeySession> keySessionList = res.getOpenKeys();
    assertEquals(numOpenKeys, keySessionList.size());
    // Verify that every single open key shows up in the result, and in order
    for (int i = 0; i < numOpenKeys; i++) {
        OpenKeySession keySession = keySessionList.get(i);
        assertEquals(keyPrefix + i, keySession.getKeyInfo().getKeyName());
        assertEquals(clientID, keySession.getId());
        assertEquals(0, keySession.getOpenVersion());
    }
    // With pagination
    int pageSize = 2;
    int numExpectedKeys = pageSize;
    res = omMetadataManager.listOpenFiles(bucketLayout, pageSize, dbPrefix, false, dbPrefix);
    // total open key count should still be 3
    assertEquals(numOpenKeys, res.getTotalOpenKeyCount());
    // hasMore should have been set
    assertTrue(res.hasMore());
    keySessionList = res.getOpenKeys();
    assertEquals(numExpectedKeys, keySessionList.size());
    for (int i = 0; i < numExpectedKeys; i++) {
        OpenKeySession keySession = keySessionList.get(i);
        assertEquals(keyPrefix + i, keySession.getKeyInfo().getKeyName());
        assertEquals(clientID, keySession.getId());
        assertEquals(0, keySession.getOpenVersion());
    }
    // Get the second page
    res = omMetadataManager.listOpenFiles(bucketLayout, pageSize, dbPrefix, true, res.getContinuationToken());
    numExpectedKeys = numOpenKeys - pageSize;
    // total open key count should still be 3
    assertEquals(numOpenKeys, res.getTotalOpenKeyCount());
    assertFalse(res.hasMore());
    keySessionList = res.getOpenKeys();
    assertEquals(numExpectedKeys, keySessionList.size());
    for (int i = 0; i < numExpectedKeys; i++) {
        OpenKeySession keySession = keySessionList.get(i);
        assertEquals(keyPrefix + (pageSize + i), keySession.getKeyInfo().getKeyName());
        assertEquals(clientID, keySession.getId());
        assertEquals(0, keySession.getOpenVersion());
    }
}

@ParameterizedTest
@EnumSource
public void testGetExpiredOpenKeys(BucketLayout bucketLayout) throws Exception {
    final String bucketName = UUID.randomUUID().toString();
    final String volumeName = UUID.randomUUID().toString();
    // Add volume, bucket, key entries to DB.
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, BucketLayout.FILE_SYSTEM_OPTIMIZED);
    final long volumeId = omMetadataManager.getVolumeId(volumeName);
    final long bucketId = omMetadataManager.getBucketId(volumeName, bucketName);
    final int numExpiredOpenKeys = 4;
    final int numUnexpiredOpenKeys = 1;
    final long clientID = 1000L;
    // To create expired keys, they will be assigned a creation time as
    // old as the minimum expiration time.
    final long expireThresholdMillis = ozoneConfiguration.getTimeDuration(OZONE_OM_OPEN_KEY_EXPIRE_THRESHOLD, OZONE_OM_OPEN_KEY_EXPIRE_THRESHOLD_DEFAULT, TimeUnit.MILLISECONDS);
    final Duration expireThreshold = Duration.ofMillis(expireThresholdMillis);
    final long expiredOpenKeyCreationTime = expireThreshold.negated().plusMillis(Time.now()).toMillis();
    // Add expired keys to open key table.
    // The method under test does not check for expired open keys in the
    // cache, since they will be picked up once the cache is flushed.
    Set<String> expiredKeys = new HashSet<>();
    for (int i = 0; i < numExpiredOpenKeys + numUnexpiredOpenKeys; i++) {
        final long creationTime = i < numExpiredOpenKeys ? expiredOpenKeyCreationTime : Time.now();
        final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, "expired" + i, RatisReplicationConfig.getInstance(ONE)).setCreationTime(creationTime).build();
        final String dbOpenKeyName;
        if (bucketLayout.isFileSystemOptimized()) {
            keyInfo.setParentObjectID(i);
            keyInfo.setFileName(OzoneFSUtils.getFileName(keyInfo.getKeyName()));
            OMRequestTestUtils.addFileToKeyTable(true, false, keyInfo.getFileName(), keyInfo, clientID, 0L, omMetadataManager);
            dbOpenKeyName = omMetadataManager.getOpenFileName(volumeId, bucketId, keyInfo.getParentObjectID(), keyInfo.getFileName(), clientID);
        } else {
            OMRequestTestUtils.addKeyToTable(true, false, keyInfo, clientID, 0L, omMetadataManager);
            dbOpenKeyName = omMetadataManager.getOpenKey(volumeName, bucketName, keyInfo.getKeyName(), clientID);
        }
        expiredKeys.add(dbOpenKeyName);
    }
    // Test retrieving fewer expired keys than actually exist.
    final Collection<OpenKeyBucket.Builder> someExpiredKeys = omMetadataManager.getExpiredOpenKeys(expireThreshold, numExpiredOpenKeys - 1, bucketLayout, expireThreshold).getOpenKeyBuckets();
    List<String> names = getOpenKeyNames(someExpiredKeys);
    assertEquals(numExpiredOpenKeys - 1, names.size());
    assertThat(expiredKeys).containsAll(names);
    // Test attempting to retrieving more expired keys than actually exist.
    Collection<OpenKeyBucket.Builder> allExpiredKeys = omMetadataManager.getExpiredOpenKeys(expireThreshold, numExpiredOpenKeys + 1, bucketLayout, expireThreshold).getOpenKeyBuckets();
    names = getOpenKeyNames(allExpiredKeys);
    assertEquals(numExpiredOpenKeys, names.size());
    assertThat(expiredKeys).containsAll(names);
    // Test retrieving exact amount of expired keys that exist.
    allExpiredKeys = omMetadataManager.getExpiredOpenKeys(expireThreshold, numExpiredOpenKeys, bucketLayout, expireThreshold).getOpenKeyBuckets();
    names = getOpenKeyNames(allExpiredKeys);
    assertEquals(numExpiredOpenKeys, names.size());
    assertThat(expiredKeys).containsAll(names);
}

@ParameterizedTest
@EnumSource
public void testGetExpiredOpenKeysExcludeMPUKeys(BucketLayout bucketLayout) throws Exception {
    final String bucketName = UUID.randomUUID().toString();
    final String volumeName = UUID.randomUUID().toString();
    // Add volume, bucket, key entries to DB.
    OMRequestTestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager, BucketLayout.FILE_SYSTEM_OPTIMIZED);
    final int numExpiredMPUOpenKeys = 4;
    final long clientID = 1000L;
    // To create expired keys, they will be assigned a creation time as
    // old as the minimum expiration time.
    final long expireThresholdMillis = ozoneConfiguration.getTimeDuration(OZONE_OM_OPEN_KEY_EXPIRE_THRESHOLD, OZONE_OM_OPEN_KEY_EXPIRE_THRESHOLD_DEFAULT, TimeUnit.MILLISECONDS);
    final Duration expireThreshold = Duration.ofMillis(expireThresholdMillis);
    final long expiredOpenKeyCreationTime = expireThreshold.negated().plusMillis(Time.now()).toMillis();
    // Ensure that "expired" MPU-related open keys are not fetched.
    // MPU-related open keys, identified by isMultipartKey = false
    for (int i = 0; i < numExpiredMPUOpenKeys; i++) {
        final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, "expired" + i, RatisReplicationConfig.getInstance(ONE), new OmKeyLocationInfoGroup(0L, new ArrayList<>(), true)).setCreationTime(expiredOpenKeyCreationTime).build();
        assertThat(keyInfo.getModificationTime()).isPositive();
        final String uploadId = OMMultipartUploadUtils.getMultipartUploadId();
        final OmMultipartKeyInfo multipartKeyInfo = OMRequestTestUtils.createOmMultipartKeyInfo(uploadId, expiredOpenKeyCreationTime, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, 0L);
        if (bucketLayout.isFileSystemOptimized()) {
            keyInfo.setParentObjectID(i);
            keyInfo.setFileName(OzoneFSUtils.getFileName(keyInfo.getKeyName()));
            OMRequestTestUtils.addMultipartKeyToOpenFileTable(false, keyInfo.getFileName(), keyInfo, uploadId, 0L, omMetadataManager);
        } else {
            OMRequestTestUtils.addMultipartKeyToOpenKeyTable(false, keyInfo, uploadId, 0L, omMetadataManager);
        }
        OMRequestTestUtils.addMultipartInfoToTable(false, keyInfo, multipartKeyInfo, 0L, omMetadataManager);
    }
    // Return empty since only MPU-related open keys exist.
    assertTrue(omMetadataManager.getExpiredOpenKeys(expireThreshold, numExpiredMPUOpenKeys, bucketLayout, expireThreshold).getOpenKeyBuckets().isEmpty());
    // This is for MPU-related open keys prior to isMultipartKey fix in
    // HDDS-9017. Although these open keys are MPU-related,
    // the isMultipartKey flags are set to false
    for (int i = numExpiredMPUOpenKeys; i < 2 * numExpiredMPUOpenKeys; i++) {
        final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, "expired" + i, RatisReplicationConfig.getInstance(ONE)).setCreationTime(expiredOpenKeyCreationTime).build();
        final String uploadId = OMMultipartUploadUtils.getMultipartUploadId();
        final OmMultipartKeyInfo multipartKeyInfo = OMRequestTestUtils.createOmMultipartKeyInfo(uploadId, expiredOpenKeyCreationTime, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, 0L);
        if (bucketLayout.isFileSystemOptimized()) {
            keyInfo.setParentObjectID(i);
            keyInfo.setFileName(OzoneFSUtils.getFileName(keyInfo.getKeyName()));
            OMRequestTestUtils.addMultipartKeyToOpenFileTable(false, keyInfo.getFileName(), keyInfo, uploadId, 0L, omMetadataManager);
        } else {
            OMRequestTestUtils.addMultipartKeyToOpenKeyTable(false, keyInfo, uploadId, 0L, omMetadataManager);
        }
        OMRequestTestUtils.addMultipartInfoToTable(false, keyInfo, multipartKeyInfo, 0L, omMetadataManager);
    }
    // MPU-related open keys should not be fetched regardless of isMultipartKey
    // flag if has the multipart upload characteristics
    assertTrue(omMetadataManager.getExpiredOpenKeys(expireThreshold, numExpiredMPUOpenKeys, bucketLayout, expireThreshold).getOpenKeyBuckets().isEmpty());
}

@Test
public void testGetExpiredMPUs() throws Exception {
    final String bucketName = UUID.randomUUID().toString();
    final String volumeName = UUID.randomUUID().toString();
    final int numExpiredMPUs = 4;
    final int numUnexpiredMPUs = 1;
    final int numPartsPerMPU = 5;
    // To create expired keys, they will be assigned a creation time as
    // old as the minimum expiration time.
    final long expireThresholdMillis = ozoneConfiguration.getTimeDuration(OZONE_OM_MPU_EXPIRE_THRESHOLD, OZONE_OM_MPU_EXPIRE_THRESHOLD_DEFAULT, TimeUnit.MILLISECONDS);
    final Duration expireThreshold = Duration.ofMillis(expireThresholdMillis);
    final long expiredMPUCreationTime = expireThreshold.negated().plusMillis(Time.now()).toMillis();
    // Add expired MPUs to multipartInfoTable.
    // The method under test does not check for expired open keys in the
    // cache, since they will be picked up once the cache is flushed.
    Set<String> expiredMPUs = new HashSet<>();
    for (int i = 0; i < numExpiredMPUs + numUnexpiredMPUs; i++) {
        final long creationTime = i < numExpiredMPUs ? expiredMPUCreationTime : Time.now();
        String uploadId = OMMultipartUploadUtils.getMultipartUploadId();
        final OmMultipartKeyInfo mpuKeyInfo = OMRequestTestUtils.createOmMultipartKeyInfo(uploadId, creationTime, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, 0L);
        String keyName = "expired" + i;
        // Key info to construct the MPU DB key
        final OmKeyInfo keyInfo = OMRequestTestUtils.createOmKeyInfo(volumeName, bucketName, keyName, RatisReplicationConfig.getInstance(ONE)).setCreationTime(creationTime).build();
        for (int j = 1; j <= numPartsPerMPU; j++) {
            PartKeyInfo partKeyInfo = OMRequestTestUtils.createPartKeyInfo(volumeName, bucketName, keyName, uploadId, j);
            OMRequestTestUtils.addPart(partKeyInfo, mpuKeyInfo);
        }
        final String mpuDbKey = OMRequestTestUtils.addMultipartInfoToTable(false, keyInfo, mpuKeyInfo, 0L, omMetadataManager);
        expiredMPUs.add(mpuDbKey);
    }
    // Test retrieving fewer expire MPU parts than actually exist (exact).
    List<ExpiredMultipartUploadsBucket> someExpiredMPUs = omMetadataManager.getExpiredMultipartUploads(expireThreshold, (numExpiredMPUs * numPartsPerMPU) - (numPartsPerMPU));
    List<String> names = getMultipartKeyNames(someExpiredMPUs);
    assertEquals(numExpiredMPUs - 1, names.size());
    assertThat(expiredMPUs).containsAll(names);
    // Test retrieving fewer expire MPU parts than actually exist (round up).
    someExpiredMPUs = omMetadataManager.getExpiredMultipartUploads(expireThreshold, (numExpiredMPUs * numPartsPerMPU) - (numPartsPerMPU + 1));
    names = getMultipartKeyNames(someExpiredMPUs);
    assertEquals(numExpiredMPUs - 1, names.size());
    assertThat(expiredMPUs).containsAll(names);
    // Test attempting to retrieving more expire MPU parts than actually exist.
    List<ExpiredMultipartUploadsBucket> allExpiredMPUs = omMetadataManager.getExpiredMultipartUploads(expireThreshold, (numExpiredMPUs * numPartsPerMPU) + numPartsPerMPU);
    names = getMultipartKeyNames(allExpiredMPUs);
    assertEquals(numExpiredMPUs, names.size());
    assertThat(expiredMPUs).containsAll(names);
    // Test retrieving exact amount of MPU parts than actually exist.
    allExpiredMPUs = omMetadataManager.getExpiredMultipartUploads(expireThreshold, (numExpiredMPUs * numPartsPerMPU));
    names = getMultipartKeyNames(allExpiredMPUs);
    assertEquals(numExpiredMPUs, names.size());
    assertThat(expiredMPUs).containsAll(names);
}

