@Test
public void testConcurrentTableReinitialization() throws Exception {
    int threadCount = 10;
    ExecutorService executor = Executors.newFixedThreadPool(threadCount);
    CountDownLatch latch = new CountDownLatch(threadCount);
    AtomicBoolean hasError = new AtomicBoolean(false);
    // Simulate multiple threads reinitializing tables concurrently
    for (int i = 0; i < threadCount; i++) {
        executor.submit(() -> {
            try {
                // Each thread gets the user table, which may trigger reinitialization
                Table<String, ?> userTable = omMetadataManager.getUserTable();
                assertNotNull(userTable);
            } catch (Exception e) {
                if (e.getCause() instanceof MetricsException && e.getCause().getMessage().contains("already exists")) {
                    hasError.set(true);
                }
            } finally {
                latch.countDown();
            }
        });
    }
    assertTrue(latch.await(30, TimeUnit.SECONDS));
    assertFalse(hasError.get(), "Metrics registration conflict occurred during concurrent reinitialization");
}

