    assertEquals(new VersionMeta(0, ImmutableList.of(new SstFileInfo("sst1", "k1", "k2", "table1"), new SstFileInfo("sst2", "k3", "k4", "table1"), new SstFileInfo("sst3", "k4", "k5", "table2"))), notDefraggedSSTFiles);
