    assertEquals(snapshotId, snapshotData.getSnapshotId());
    assertEquals(ImmutableMap.of(0, new VersionMeta(0, ImmutableList.of(new SstFileInfo("sst1", "k1", "k2", "table1"), new SstFileInfo("sst2", "k3", "k4", "table1"), new SstFileInfo("sst3", "k4", "k5", "table2"))), 43, new VersionMeta(1, ImmutableList.of(new SstFileInfo("defragged-sst1", "k1", "k2", "table1"), new SstFileInfo("defragged-sst2", "k3", "k4", "table2"))), 44, new VersionMeta(3, ImmutableList.of(new SstFileInfo("defragged-sst3", "k4", "k5", "table1")))), defraggedSSTFiles);
