    fileSize = processFile(linkToExcludedFile, copyFiles, hardLinkFiles, toExcludeFiles, destLinkToExcludedFile.getParent());
    assertEquals(copyFiles.size(), 1);
    assertEquals(hardLinkFiles.size(), 1);
    assertEquals(hardLinkFiles.get(destLinkToExcludedFile), destExcludeFile);
    assertEquals(fileSize, 0);
    hardLinkFiles = new HashMap<>();
    // Confirm the file with same name as excluded file gets copied.
    fileSize = processFile(sameNameAsExcludeFile, copyFiles, hardLinkFiles, toExcludeFiles, destSameNameAsExcludeFile.getParent());
    assertEquals(copyFiles.size(), 2);
    assertEquals(hardLinkFiles.size(), 0);
    assertEquals(copyFiles.get(sameNameAsExcludeFile.getFileName().toString()).get(sameNameAsExcludeFile), destSameNameAsExcludeFile);
    assertEquals(fileSize, expectedFileSize);
    copyFiles = new HashMap<>();
    copyFiles.computeIfAbsent(copyFileName.toString(), (k) -> new HashMap<>()).put(copyFile, destCopyFile);
    // Confirm the file with same name as copy file gets copied.
    fileSize = processFile(sameNameAsCopyFile, copyFiles, hardLinkFiles, toExcludeFiles, destSameNameAsCopyFile.getParent());
    assertEquals(copyFiles.size(), 2);
    assertEquals(hardLinkFiles.size(), 0);
    assertEquals(copyFiles.get(sameNameAsCopyFile.getFileName().toString()).get(sameNameAsCopyFile), destSameNameAsCopyFile);
    assertEquals(fileSize, expectedFileSize);
    copyFiles = new HashMap<>();
    copyFiles.computeIfAbsent(copyFileName.toString(), (k) -> new HashMap<>()).put(copyFile, destCopyFile);
    // Confirm the linkToCopiedFile gets added as a link.
    fileSize = processFile(linkToCopiedFile, copyFiles, hardLinkFiles, toExcludeFiles, destLinkToCopiedFile.getParent());
    assertEquals(copyFiles.size(), 1);
    assertEquals(hardLinkFiles.size(), 1);
    assertEquals(hardLinkFiles.get(destLinkToCopiedFile), destCopyFile);
    assertEquals(fileSize, 0);
    hardLinkFiles = new HashMap<>();
    // Confirm the addToCopiedFiles gets added to list of copied files
    fileSize = processFile(addToCopiedFiles, copyFiles, hardLinkFiles, toExcludeFiles, destAddToCopiedFiles.getParent());
    assertEquals(copyFiles.size(), 2);
    assertEquals(copyFiles.get(addToCopiedFiles.getFileName().toString()).get(addToCopiedFiles), destAddToCopiedFiles);
    assertEquals(fileSize, expectedFileSize);
    copyFiles = new HashMap<>();
    copyFiles.computeIfAbsent(copyFileName.toString(), (k) -> new HashMap<>()).put(copyFile, destCopyFile);
    // Confirm the addNonSstToCopiedFiles gets added to list of copied files
    fileSize = processFile(addNonSstToCopiedFiles, copyFiles, hardLinkFiles, toExcludeFiles, destAddNonSstToCopiedFiles.getParent());
    assertEquals(copyFiles.size(), 2);
    assertEquals(fileSize, 0);
    assertEquals(copyFiles.get(addNonSstToCopiedFiles.getFileName().toString()).get(addNonSstToCopiedFiles), destAddNonSstToCopiedFiles);
}

@Test
public void testCreateSnapshotIdempotent() throws Exception {
    // set up db tables
    LogCapturer logCapturer = LogCapturer.captureLogs(OmSnapshotManager.class);
    final TypedTable<String, OmVolumeArgs> volumeTable = mock(TypedTable.class);
    final TypedTable<String, OmBucketInfo> bucketTable = mock(TypedTable.class);
    final TypedTable<String, SnapshotInfo> snapshotInfoTable = mock(TypedTable.class);
    HddsWhiteboxTestUtils.setInternalState(om.getMetadataManager(), VOLUME_TABLE, volumeTable);
    HddsWhiteboxTestUtils.setInternalState(om.getMetadataManager(), BUCKET_TABLE, bucketTable);
    HddsWhiteboxTestUtils.setInternalState(om.getMetadataManager(), SNAPSHOT_INFO_TABLE, snapshotInfoTable);
    final String volumeName = UUID.randomUUID().toString();
    final String dbVolumeKey = om.getMetadataManager().getVolumeKey(volumeName);
    final OmVolumeArgs omVolumeArgs = OmVolumeArgs.newBuilder().setVolume(volumeName).setAdminName("bilbo").setOwnerName("bilbo").build();
    when(volumeTable.get(dbVolumeKey)).thenReturn(omVolumeArgs);
    String bucketName = UUID.randomUUID().toString();
    final String dbBucketKey = om.getMetadataManager().getBucketKey(volumeName, bucketName);
    final OmBucketInfo omBucketInfo = OmBucketInfo.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).build();
    when(bucketTable.get(dbBucketKey)).thenReturn(omBucketInfo);
    SnapshotInfo first = createSnapshotInfo(volumeName, bucketName);
    when(snapshotInfoTable.get(first.getTableKey())).thenReturn(first);
    // Create first checkpoint for the snapshot checkpoint
    RDBBatchOperation rdbBatchOperation = new RDBBatchOperation();
    OmSnapshotManager.createOmSnapshotCheckpoint(om.getMetadataManager(), first, rdbBatchOperation);
    om.getMetadataManager().getStore().commitBatchOperation(rdbBatchOperation);
    assertThat(logCapturer.getOutput()).doesNotContain("for snapshot " + first.getName() + " already exists.");
    logCapturer.clearOutput();
    // Create checkpoint again for the same snapshot.
    rdbBatchOperation = new RDBBatchOperation();
    OmSnapshotManager.createOmSnapshotCheckpoint(om.getMetadataManager(), first, rdbBatchOperation);
    om.getMetadataManager().getStore().commitBatchOperation(rdbBatchOperation);
    assertThat(logCapturer.getOutput()).contains("for snapshot " + first.getTableKey() + " already exists.");
}

