@Test
public void testRecursiveAccessFlag() throws IOException {
    RequestContext context = getUserRequestContext("om", IAccessAuthorizer.ACLType.CREATE, false, "volume1", true);
    assertTrue(context.isRecursiveAccessCheck(), "Wrongly sets recursiveAccessCheck flag value");
    context = getUserRequestContext("om", IAccessAuthorizer.ACLType.CREATE, false, "volume1", false);
    assertFalse(context.isRecursiveAccessCheck(), "Wrongly sets recursiveAccessCheck flag value");
    context = getUserRequestContext("user1", IAccessAuthorizer.ACLType.CREATE, true, "volume1");
    assertFalse(context.isRecursiveAccessCheck(), "Wrongly sets recursiveAccessCheck flag value");
    RequestContext.Builder builder = new RequestContext.Builder();
    assertFalse(builder.build().isRecursiveAccessCheck(), "Wrongly sets recursive flag value");
    builder.setRecursiveAccessCheck(true);
    assertTrue(builder.build().isRecursiveAccessCheck(), "Wrongly sets recursive flag value");
    context = new RequestContext("host", null, null, "serviceId", IAccessAuthorizer.ACLIdentityType.GROUP, IAccessAuthorizer.ACLType.CREATE, "owner");
    assertFalse(context.isRecursiveAccessCheck(), "Wrongly sets recursive flag value");
    context = new RequestContext("host", null, null, "serviceId", IAccessAuthorizer.ACLIdentityType.GROUP, IAccessAuthorizer.ACLType.CREATE, "owner", false);
    assertFalse(context.isRecursiveAccessCheck(), "Wrongly sets recursive flag value");
    context = new RequestContext("host", null, null, "serviceId", IAccessAuthorizer.ACLIdentityType.GROUP, IAccessAuthorizer.ACLType.CREATE, "owner", true);
    assertTrue(context.isRecursiveAccessCheck(), "Wrongly sets recursive flag value");
}

