@ParameterizedTest
@MethodSource("parameters")
public void testInitOzoneManager(boolean pvtKeyPresent, boolean pubKeyPresent, boolean certPresent, InitResponse expectedResult) throws Exception {
    if (pvtKeyPresent) {
        omKeyStorage.storePrivateKey(keyPair.getPrivate());
    } else {
        FileUtils.deleteQuietly(Paths.get(securityConfig.getKeyLocation(OM_COMPONENT).toString(), securityConfig.getPrivateKeyFileName()).toFile());
    }
    if (pubKeyPresent) {
        if (omCertificateClient.getPublicKey() == null) {
            omKeyStorage.storePublicKey(keyPair.getPublic());
        }
    } else {
        FileUtils.deleteQuietly(Paths.get(securityConfig.getKeyLocation(OM_COMPONENT).toString(), securityConfig.getPublicKeyFileName()).toFile());
    }
    if (certPresent) {
        CertificateCodec codec = new CertificateCodec(securityConfig, OM_COMPONENT);
        codec.writeCertificate(x509Certificate);
    } else {
        FileUtils.deleteQuietly(Paths.get(securityConfig.getKeyLocation(OM_COMPONENT).toString(), securityConfig.getCertificateFileName()).toFile());
    }
    InitResponse response = omCertificateClient.init();
    if (pvtKeyPresent && pubKeyPresent && !certPresent) {
        assertEquals(GETCERT, response);
    } else {
        assertEquals(expectedResult, response);
    }
    if (!response.equals(FAILURE)) {
        assertTrue(OzoneSecurityUtil.checkIfFileExist(securityConfig.getKeyLocation(OM_COMPONENT), securityConfig.getPrivateKeyFileName()));
        assertTrue(OzoneSecurityUtil.checkIfFileExist(securityConfig.getKeyLocation(OM_COMPONENT), securityConfig.getPublicKeyFileName()));
    }
}

@Test
public void testLeadershipCheckinRetrievePassword() throws Exception {
    secretManager = createSecretManager(conf, TOKEN_MAX_LIFETIME, expiryTime, TOKEN_REMOVER_SCAN_INTERVAL);
    doThrow(new OMNotLeaderException(RaftPeerId.valueOf("om"))).when(om).checkLeaderStatus();
    OzoneTokenIdentifier identifier = new OzoneTokenIdentifier();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        assertEquals(SecretManager.InvalidToken.class, e.getClass());
        assertEquals(OMNotLeaderException.class, e.getCause().getClass());
    }
    doThrow(new OMLeaderNotReadyException("Leader not ready")).when(om).checkLeaderStatus();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        assertEquals(SecretManager.InvalidToken.class, e.getClass());
        assertEquals(OMLeaderNotReadyException.class, e.getCause().getClass());
    }
    doNothing().when(om).checkLeaderStatus();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        assertEquals(SecretManager.InvalidToken.class, e.getClass());
        assertNull(e.getCause());
    }
}

