    // Case 2: Invalid hash in string to sign.
    identifier.setStrToSign("AWS4-HMAC-SHA256\n" + "20190221T002037Z\n" + "20190221/us-west-1/s3/aws4_request\n" + "c297c080cce4e0927779823d3fd1f5cae71481a8f7dfc7e18d91851294efc47d" + "+invalidhash");
    invalidToken = assertThrows(SecretManager.InvalidToken.class, () -> secretManager.retrievePassword(identifier));
    assertTrue(invalidToken.getMessage().startsWith("No S3 secret found for S3 identifier"));
    // Case 3: Invalid hash in authorization hmac.
    identifier.setSignature("56ec73ba1974f8feda8365c3caef89c5d4a688d" + "+invalidhash" + "5f9baccf4765f46a14cd745ad");
