    assertEquals("dir3/dir5/", ofsPath.getKeyName());
    assertEquals("/volume1/bucket2", ofsPath.getNonKeyPath());
    assertFalse(ofsPath.isMount());
    assertEquals("/volume1/bucket2/dir3/dir5/", ofsPath.toString());
}

