@Test
public void testKeyCountsForValidAndInvalidKeyPrefix() {
    Timestamp now = new Timestamp(System.currentTimeMillis());
    GlobalStatsDao statsDao = omdbInsightEndpoint.getDao();
    // Insert valid key count with valid key prefix
    insertGlobalStatsRecords(statsDao, now, "openKeyTable" + "Count", 3L);
    insertGlobalStatsRecords(statsDao, now, "openFileTable" + "Count", 3L);
    insertGlobalStatsRecords(statsDao, now, "openKeyTable" + "ReplicatedDataSize", 150L);
    insertGlobalStatsRecords(statsDao, now, "openFileTable" + "ReplicatedDataSize", 150L);
    insertGlobalStatsRecords(statsDao, now, "openKeyTable" + "UnReplicatedDataSize", 50L);
    insertGlobalStatsRecords(statsDao, now, "openFileTable" + "UnReplicatedDataSize", 50L);
    Response openKeyInfoResp = omdbInsightEndpoint.getOpenKeySummary();
    assertNotNull(openKeyInfoResp);
    Map<String, Long> openKeysSummary = (Map<String, Long>) openKeyInfoResp.getEntity();
    // Assert that the key prefix format is accepted in the global stats
    assertEquals(6L, openKeysSummary.get("totalOpenKeys"));
    assertEquals(300L, openKeysSummary.get("totalReplicatedDataSize"));
    assertEquals(100L, openKeysSummary.get("totalUnreplicatedDataSize"));
    // Delete the previous records and Update the new value for valid key prefix
    statsDao.deleteById("openKeyTable" + "Count", "openFileTable" + "Count", "openKeyTable" + "ReplicatedDataSize", "openFileTable" + "ReplicatedDataSize", "openKeyTable" + "UnReplicatedDataSize", "openFileTable" + "UnReplicatedDataSize");
    // Insert new record for a key with invalid prefix
    insertGlobalStatsRecords(statsDao, now, "openKeyTable" + "InvalidPrefix", 3L);
    insertGlobalStatsRecords(statsDao, now, "openFileTable" + "InvalidPrefix", 3L);
    openKeyInfoResp = omdbInsightEndpoint.getOpenKeySummary();
    assertNotNull(openKeyInfoResp);
    openKeysSummary = (Map<String, Long>) openKeyInfoResp.getEntity();
    // Assert that the key format is not accepted in the global stats
    assertEquals(0L, openKeysSummary.get("totalOpenKeys"));
    assertEquals(0L, openKeysSummary.get("totalReplicatedDataSize"));
    assertEquals(0L, openKeysSummary.get("totalUnreplicatedDataSize"));
}

@Test
public void testKeysSummaryAttribute() {
    Timestamp now = new Timestamp(System.currentTimeMillis());
    GlobalStatsDao statsDao = omdbInsightEndpoint.getDao();
    // Insert records for replicated and unreplicated data sizes
    insertGlobalStatsRecords(statsDao, now, "openFileTableReplicatedDataSize", 30L);
    insertGlobalStatsRecords(statsDao, now, "openKeyTableReplicatedDataSize", 30L);
    insertGlobalStatsRecords(statsDao, now, "deletedTableReplicatedDataSize", 30L);
    insertGlobalStatsRecords(statsDao, now, "openFileTableUnReplicatedDataSize", 10L);
    insertGlobalStatsRecords(statsDao, now, "openKeyTableUnReplicatedDataSize", 10L);
    insertGlobalStatsRecords(statsDao, now, "deletedTableUnReplicatedDataSize", 10L);
    // Insert records for table counts
    insertGlobalStatsRecords(statsDao, now, "openKeyTableCount", 3L);
    insertGlobalStatsRecords(statsDao, now, "openFileTableCount", 3L);
    insertGlobalStatsRecords(statsDao, now, "deletedTableCount", 3L);
    // Call the API of Open keys to get the response
    Response openKeyInfoResp = omdbInsightEndpoint.getOpenKeySummary();
    assertNotNull(openKeyInfoResp);
    Map<String, Long> openKeysSummary = (Map<String, Long>) openKeyInfoResp.getEntity();
    assertEquals(60L, openKeysSummary.get("totalReplicatedDataSize"));
    assertEquals(20L, openKeysSummary.get("totalUnreplicatedDataSize"));
    assertEquals(6L, openKeysSummary.get("totalOpenKeys"));
    // Call the API of Deleted keys to get the response
    Response deletedKeyInfoResp = omdbInsightEndpoint.getDeletedKeySummary();
    assertNotNull(deletedKeyInfoResp);
    Map<String, Long> deletedKeysSummary = (Map<String, Long>) deletedKeyInfoResp.getEntity();
    assertEquals(30L, deletedKeysSummary.get("totalReplicatedDataSize"));
    assertEquals(10L, deletedKeysSummary.get("totalUnreplicatedDataSize"));
    assertEquals(3L, deletedKeysSummary.get("totalDeletedKeys"));
}

