@Test
public void testGetOpenKeyInfoWithIncludeFsoAndIncludeNonFsoParams() throws Exception {
    OmKeyInfo omKeyInfo1 = getOmKeyInfo("sampleVol", "non_fso_Bucket", "non_fso_key1", true);
    OmKeyInfo omKeyInfo2 = getOmKeyInfo("sampleVol", "non_fso_Bucket", "non_fso_key2", true);
    OmKeyInfo omKeyInfo3 = getOmKeyInfo("sampleVol", "non_fso_Bucket", "non_fso_key3", true);
    reconOMMetadataManager.getOpenKeyTable(getBucketLayout()).put("/sampleVol/non_fso_Bucket/non_fso_key1", omKeyInfo1);
    reconOMMetadataManager.getOpenKeyTable(getBucketLayout()).put("/sampleVol/non_fso_Bucket/non_fso_key2", omKeyInfo2);
    reconOMMetadataManager.getOpenKeyTable(getBucketLayout()).put("/sampleVol/non_fso_Bucket/non_fso_key3", omKeyInfo3);
    omKeyInfo1 = getOmKeyInfo("sampleVol", "fso_Bucket", "fso_key1", false);
    omKeyInfo2 = getOmKeyInfo("sampleVol", "fso_Bucket", "fso_key2", false);
    omKeyInfo3 = getOmKeyInfo("sampleVol", "fso_Bucket", "fso_key3", false);
    OmKeyInfo omKeyInfo4 = getOmKeyInfo("sampleVol", "fso_Bucket", "fso_key4", false);
    reconOMMetadataManager.getOpenKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).put("/sampleVol/fso_Bucket/fso_key1", omKeyInfo1);
    reconOMMetadataManager.getOpenKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).put("/sampleVol/fso_Bucket/fso_key2", omKeyInfo2);
    reconOMMetadataManager.getOpenKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).put("/sampleVol/fso_Bucket/fso_key3", omKeyInfo3);
    reconOMMetadataManager.getOpenKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).put("/sampleVol/fso_Bucket/fso_key4", omKeyInfo4);
    // CASE 1 :- Display only FSO keys in response
    // includeFsoKeys=true, includeNonFsoKeys=false
    Response openKeyInfoResp = omdbInsightEndpoint.getOpenKeyInfo(10, "", "", true, false);
    KeyInsightInfoResponse keyInsightInfoResp = (KeyInsightInfoResponse) openKeyInfoResp.getEntity();
    assertNotNull(keyInsightInfoResp);
    assertEquals(4, keyInsightInfoResp.getFsoKeyInfoList().size());
    assertEquals(0, keyInsightInfoResp.getNonFSOKeyInfoList().size());
    // CASE 2 :- Display only Non-FSO keys in response
    // includeFsoKeys=false, includeNonFsoKeys=true
    openKeyInfoResp = omdbInsightEndpoint.getOpenKeyInfo(10, "", "", false, true);
    keyInsightInfoResp = (KeyInsightInfoResponse) openKeyInfoResp.getEntity();
    assertNotNull(keyInsightInfoResp);
    assertEquals(0, keyInsightInfoResp.getFsoKeyInfoList().size());
    assertEquals(3, keyInsightInfoResp.getNonFSOKeyInfoList().size());
    // CASE 3 :- Display both FSO and Non-FSO keys in response
    // includeFsoKeys=true, includeNonFsoKeys=true
    openKeyInfoResp = omdbInsightEndpoint.getOpenKeyInfo(10, "", "", true, true);
    keyInsightInfoResp = (KeyInsightInfoResponse) openKeyInfoResp.getEntity();
    assertNotNull(keyInsightInfoResp);
    assertEquals(4, keyInsightInfoResp.getFsoKeyInfoList().size());
    assertEquals(3, keyInsightInfoResp.getNonFSOKeyInfoList().size());
    // CASE 4 :- Don't Display both FSO and Non-FSO keys in response
    // includeFsoKeys=false, includeNonFsoKeys=false
    openKeyInfoResp = omdbInsightEndpoint.getOpenKeyInfo(10, "", "", false, false);
    assertEquals(204, openKeyInfoResp.getStatus());
    String entity = (String) openKeyInfoResp.getEntity();
    assertTrue(entity.contains("No keys matched the search prefix"), "Expected a message indicating no keys were found");
}

