    ContainerHealthTask containerHealthTask = new ContainerHealthTask(scmMock.getContainerManager(), scmMock.getScmServiceProvider(), containerHealthSchemaManager, placementMock, reconTaskConfig, reconContainerMetadataManager, new OzoneConfiguration(), getMockTaskStatusUpdaterManager());
