@Test
public void testSchemaVersionCRUDOperations() throws SQLException {
    Connection connection = getConnection();
    // Ensure no tables exist initially, simulating a fresh installation
    dropAllTables(connection);
    // Create the schema version table
    createSchemaVersionTable(connection);
    DSLContext dslContext = DSL.using(connection);
    DatabaseMetaData metaData = connection.getMetaData();
    ResultSet resultSet = metaData.getTables(null, null, SCHEMA_VERSION_TABLE_NAME, null);
    while (resultSet.next()) {
        assertEquals(SCHEMA_VERSION_TABLE_NAME, resultSet.getString("TABLE_NAME"));
    }
    // Insert a new version record
    dslContext.insertInto(DSL.table(SCHEMA_VERSION_TABLE_NAME)).columns(DSL.field(name("version_number")), DSL.field(name("applied_on"))).values(1, new Timestamp(System.currentTimeMillis())).execute();
    // Read the inserted record
    Record1<Integer> result = dslContext.select(DSL.field(name("version_number"), Integer.class)).from(DSL.table(SCHEMA_VERSION_TABLE_NAME)).fetchOne();
    assertEquals(1, result.value1(), "The version number does not match the expected value.");
    // Update the version record
    dslContext.update(DSL.table(SCHEMA_VERSION_TABLE_NAME)).set(DSL.field(name("version_number")), 2).execute();
    // Read the updated record
    result = dslContext.select(DSL.field(name("version_number"), Integer.class)).from(DSL.table(SCHEMA_VERSION_TABLE_NAME)).fetchOne();
    assertEquals(2, result.value1(), "The updated version number does not match the expected value.");
    // Delete the version record
    dslContext.deleteFrom(DSL.table(SCHEMA_VERSION_TABLE_NAME)).execute();
    // Verify deletion
    int count = dslContext.fetchCount(DSL.table(SCHEMA_VERSION_TABLE_NAME));
    assertEquals(0, count, "The table should be empty after deletion.");
}

