    assertNotNull(omMetadataManager.getKeyTable(getBucketLayout()).get("/sampleVol/bucketOne/key_one"));
    assertNotNull(omMetadataManager.getKeyTable(getBucketLayout()).get("/sampleVol/bucketOne/key_two"));
    //Take checkpoint of OM DB.
    DBCheckpoint checkpoint = omMetadataManager.getStore().getCheckpoint(true);
    assertNotNull(checkpoint.getCheckpointLocation());
    //Create new Recon OM Metadata manager instance.
    File reconOmDbDir = Files.createDirectory(temporaryFolder.resolve("reconOmDbDir")).toFile();
    OzoneConfiguration configuration = new OzoneConfiguration();
    configuration.set(OZONE_RECON_OM_SNAPSHOT_DB_DIR, reconOmDbDir.getAbsolutePath());
    ReconOMMetadataManager reconOMMetadataManager = new ReconOmMetadataManagerImpl(configuration, new ReconUtils());
    reconOMMetadataManager.start(configuration);
    //Before accepting a snapshot, the metadata should have null tables.
    assertNull(reconOMMetadataManager.getBucketTable());
    //Update Recon OM DB with the OM DB checkpoint location.
    reconOMMetadataManager.updateOmDB(checkpoint.getCheckpointLocation().toFile(), true);
    //Now, the tables should have been initialized.
    assertNotNull(reconOMMetadataManager.getBucketTable());
    // Check volume and bucket entries.
    assertNotNull(reconOMMetadataManager.getVolumeTable().get("/sampleVol"));
    assertNotNull(reconOMMetadataManager.getBucketTable().get("/sampleVol/bucketOne"));
