@Test
public void testFileTableProcess() throws Exception {
    // Verify that keyPrefixesForContainer is empty for container 1 and 2
    Map<ContainerKeyPrefix, Integer> keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(1);
    assertThat(keyPrefixesForContainer).isEmpty();
    keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(2);
    assertThat(keyPrefixesForContainer).isEmpty();
    // Create a random pipeline and a list of OmKeyLocationInfo objects
    Pipeline pipeline = getRandomPipeline();
    List<OmKeyLocationInfo> omKeyLocationInfoList = new ArrayList<>();
    BlockID blockID1 = new BlockID(1L, 1L);
    OmKeyLocationInfo omKeyLocationInfo1 = getOmKeyLocationInfo(blockID1, pipeline);
    BlockID blockID2 = new BlockID(2L, 1L);
    OmKeyLocationInfo omKeyLocationInfo2 = getOmKeyLocationInfo(blockID2, pipeline);
    omKeyLocationInfoList.add(omKeyLocationInfo1);
    omKeyLocationInfoList.add(omKeyLocationInfo2);
    OmKeyLocationInfoGroup omKeyLocationInfoGroup = new OmKeyLocationInfoGroup(0L, omKeyLocationInfoList);
    // Reprocess container key mappings
    ContainerKeyMapperTaskFSO containerKeyMapperTaskFSO = new ContainerKeyMapperTaskFSO(reconContainerMetadataManager, omConfiguration);
    String bucket = BUCKET_NAME;
    String volume = VOLUME_NAME;
    String key = INSERTED_KEY;
    String omKey = omMetadataManager.getOzoneKey(volume, bucket, key);
    OmKeyInfo omKeyInfo = buildOmKeyInfo(volume, bucket, key, omKeyLocationInfoGroup);
    OMDBUpdateEvent keyEvent1 = new OMDBUpdateEvent.OMUpdateEventBuilder<String, OmKeyInfo>().setKey(omKey).setValue(omKeyInfo).setTable(omMetadataManager.getKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).getName()).setAction(OMDBUpdateEvent.OMDBUpdateAction.PUT).build();
    String key2 = DELETED_KEY;
    omKey = omMetadataManager.getOzoneKey(volume, bucket, key2);
    OMDBUpdateEvent keyEvent2 = new OMDBUpdateEvent.OMUpdateEventBuilder<String, OmKeyInfo>().setKey(omKey).setValue(omKeyInfo).setAction(OMDBUpdateEvent.OMDBUpdateAction.PUT).setTable(omMetadataManager.getKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).getName()).build();
    OMUpdateEventBatch omUpdateEventBatch = new OMUpdateEventBatch(new ArrayList<OMDBUpdateEvent>() {

        {
            add(keyEvent1);
            add(keyEvent2);
        }
    }, 0L);
    // Process PUT event for both the keys
    containerKeyMapperTaskFSO.process(omUpdateEventBatch, Collections.emptyMap());
    keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(1);
    assertEquals(2, keyPrefixesForContainer.size());
    Iterator<ContainerKeyPrefix> iterator = keyPrefixesForContainer.keySet().iterator();
    ContainerKeyPrefix firstKeyPrefix = iterator.next();
    ContainerKeyPrefix secondKeyPrefix = iterator.next();
    assertEquals("/" + VOLUME_NAME + "/" + BUCKET_NAME + "/" + DELETED_KEY, firstKeyPrefix.getKeyPrefix());
    assertEquals("/" + VOLUME_NAME + "/" + BUCKET_NAME + "/" + INSERTED_KEY, secondKeyPrefix.getKeyPrefix());
    omKey = omMetadataManager.getOzoneKey(volume, bucket, key2);
    OMDBUpdateEvent keyEvent3 = new OMDBUpdateEvent.OMUpdateEventBuilder<String, OmKeyInfo>().setKey(omKey).setAction(OMDBUpdateEvent.OMDBUpdateAction.DELETE).setValue(omKeyInfo).setTable(omMetadataManager.getKeyTable(BucketLayout.FILE_SYSTEM_OPTIMIZED).getName()).build();
    OMUpdateEventBatch omUpdateEventBatch2 = new OMUpdateEventBatch(new ArrayList<OMDBUpdateEvent>() {

        {
            add(keyEvent3);
        }
    }, 0L);
    // Process DELETE event for key2
    containerKeyMapperTaskFSO.process(omUpdateEventBatch2, Collections.emptyMap());
    keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(1);
    // The second key is deleted
    assertEquals(1, keyPrefixesForContainer.size());
    iterator = keyPrefixesForContainer.keySet().iterator();
    firstKeyPrefix = iterator.next();
    assertEquals("/" + VOLUME_NAME + "/" + BUCKET_NAME + "/" + INSERTED_KEY, firstKeyPrefix.getKeyPrefix());
}

@Test
public void testDuplicateFSOKeysInDifferentDirectories() throws Exception {
    // Ensure container 1 is initially empty.
    Map<ContainerKeyPrefix, Integer> keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(1L);
    assertThat(keyPrefixesForContainer).isEmpty();
    Pipeline pipeline = getRandomPipeline();
    // Create a common OmKeyLocationInfoGroup for all keys.
    List<OmKeyLocationInfo> omKeyLocationInfoList = new ArrayList<>();
    BlockID blockID = new BlockID(1L, 1L);
    OmKeyLocationInfo omKeyLocationInfo = getOmKeyLocationInfo(blockID, pipeline);
    omKeyLocationInfoList.add(omKeyLocationInfo);
    OmKeyLocationInfoGroup omKeyLocationInfoGroup = new OmKeyLocationInfoGroup(0L, omKeyLocationInfoList);
    // Define file names.
    String file1Key = "file1";
    String file2Key = "file2";
    // Define directory (parent) object IDs with shorter values.
    long dir1Id = -101L;
    long dir2Id = -102L;
    long dir3Id = -103L;
    // Write three FSO keys for "file1" with different parent object IDs.
    writeKeyToOm(reconOMMetadataManager, // keyName
    file1Key, // bucketName
    BUCKET_NAME, // volName
    VOLUME_NAME, // fileName
    file1Key, // objectId
    KEY_ONE_OBJECT_ID, // ObjectId for first directory
    dir1Id, // bucketObjectId
    BUCKET_ONE_OBJECT_ID, // volumeObjectId
    VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    writeKeyToOm(reconOMMetadataManager, file1Key, BUCKET_NAME, VOLUME_NAME, file1Key, KEY_ONE_OBJECT_ID, // ObjectId for second directory
    dir2Id, BUCKET_ONE_OBJECT_ID, VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    writeKeyToOm(reconOMMetadataManager, file1Key, BUCKET_NAME, VOLUME_NAME, file1Key, KEY_ONE_OBJECT_ID, // ObjectId for third directory
    dir3Id, BUCKET_ONE_OBJECT_ID, VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    // Write three FSO keys for "file2" with different parent object IDs.
    writeKeyToOm(reconOMMetadataManager, "fso-file2", BUCKET_NAME, VOLUME_NAME, file2Key, KEY_ONE_OBJECT_ID, dir1Id, BUCKET_ONE_OBJECT_ID, VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    writeKeyToOm(reconOMMetadataManager, "fso-file2", BUCKET_NAME, VOLUME_NAME, file2Key, KEY_ONE_OBJECT_ID, dir2Id, BUCKET_ONE_OBJECT_ID, VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    writeKeyToOm(reconOMMetadataManager, "fso-file2", BUCKET_NAME, VOLUME_NAME, file2Key, KEY_ONE_OBJECT_ID, dir3Id, BUCKET_ONE_OBJECT_ID, VOL_OBJECT_ID, Collections.singletonList(omKeyLocationInfoGroup), BucketLayout.FILE_SYSTEM_OPTIMIZED, KEY_ONE_SIZE);
    // Reprocess container key mappings.
    ContainerKeyMapperTaskFSO containerKeyMapperTask = new ContainerKeyMapperTaskFSO(reconContainerMetadataManager, omConfiguration);
    containerKeyMapperTask.reprocess(reconOMMetadataManager);
    // With our changes using the raw key prefix as the unique identifier,
    // we expect six distinct entries in container 1.
    keyPrefixesForContainer = reconContainerMetadataManager.getKeyPrefixesForContainer(1L);
    assertEquals(6, keyPrefixesForContainer.size());
}

@Test
public void testProcess() throws IOException {
    // mock a container with invalid used bytes
    ContainerInfo omContainerInfo0 = mock(ContainerInfo.class);
    given(omContainerInfo0.containerID()).willReturn(ContainerID.valueOf(0));
    given(omContainerInfo0.getUsedBytes()).willReturn(-1L);
    given(omContainerInfo0.getState()).willReturn(OPEN);
    // Write 2 keys
    ContainerInfo omContainerInfo1 = mock(ContainerInfo.class);
    given(omContainerInfo1.containerID()).willReturn(ContainerID.valueOf(1));
    // 1.5GB
    given(omContainerInfo1.getUsedBytes()).willReturn(1500000000L);
    given(omContainerInfo1.getState()).willReturn(CLOSED);
    ContainerInfo omContainerInfo2 = mock(ContainerInfo.class);
    given(omContainerInfo2.containerID()).willReturn(ContainerID.valueOf(2));
    // 2.5GB
    given(omContainerInfo2.getUsedBytes()).willReturn(2500000000L);
    given(omContainerInfo2.getState()).willReturn(CLOSING);
    // mock getContainers method to return a list of containers
    List<ContainerInfo> containers = new ArrayList<>();
    containers.add(omContainerInfo0);
    containers.add(omContainerInfo1);
    containers.add(omContainerInfo2);
    task.processContainers(containers);
    // Verify 3 containers are in correct bins.
    // Note: getEstimatedKeyCount() may be inaccurate in RocksDB, so we count actual entries
    int firstCount = 0;
    try (org.apache.hadoop.hdds.utils.db.Table.KeyValueIterator<ContainerSizeCountKey, Long> iterator = containerCountTable.iterator()) {
        while (iterator.hasNext()) {
            iterator.next();
            firstCount++;
        }
    }
    assertEquals(3, firstCount);
    // container size upper bound for
    // 1500000000L (1.5GB) is 2147483648L = 2^31 = 2GB (next highest power of 2)
    ContainerSizeCountKey key1 = new ContainerSizeCountKey(2147483648L);
    assertEquals(1L, containerCountTable.get(key1).longValue());
    // container size upper bound for
    // 2500000000L (2.5GB) is 4294967296L = 2^32 = 4GB (next highest power of 2)
    ContainerSizeCountKey key2 = new ContainerSizeCountKey(4294967296L);
    assertEquals(1L, containerCountTable.get(key2).longValue());
    // Add a new container
    ContainerInfo omContainerInfo3 = mock(ContainerInfo.class);
    given(omContainerInfo3.containerID()).willReturn(ContainerID.valueOf(3));
    // 1GB
    given(omContainerInfo3.getUsedBytes()).willReturn(1000000000L);
    given(omContainerInfo3.getState()).willReturn(QUASI_CLOSED);
    containers.add(omContainerInfo3);
    // Update existing key.
    given(omContainerInfo2.containerID()).willReturn(ContainerID.valueOf(2));
    // 50KB
    given(omContainerInfo2.getUsedBytes()).willReturn(50000L);
    task.processContainers(containers);
    // Total size groups added to the database
    // After migration to RocksDB, entries with count=0 are deleted, so we expect 4 entries
    // Note: getEstimatedKeyCount() may be inaccurate in RocksDB, so we count actual entries
    int actualCount = 0;
    try (org.apache.hadoop.hdds.utils.db.Table.KeyValueIterator<ContainerSizeCountKey, Long> iterator = containerCountTable.iterator()) {
        while (iterator.hasNext()) {
            iterator.next();
            actualCount++;
        }
    }
    assertEquals(4, actualCount);
    // Check whether container size upper bound for
    // 50000L is 536870912L = 2^29 = 512MB (next highest power of 2)
    ContainerSizeCountKey key3 = new ContainerSizeCountKey(536870912L);
    assertEquals(1L, containerCountTable.get(key3).longValue());
    // Check whether container size of 1000000000L has been successfully updated
    // The previous value upperbound was 4294967296L which is no longer there
    ContainerSizeCountKey key4 = new ContainerSizeCountKey(4294967296L);
    Long count = containerCountTable.get(key4);
    assertEquals(0L, count == null ? 0L : count.longValue());
    // Remove the container having size 1.5GB and upperbound 2147483648L
    containers.remove(omContainerInfo1);
    task.processContainers(containers);
    ContainerSizeCountKey key5 = new ContainerSizeCountKey(2147483648L);
    Long count2 = containerCountTable.get(key5);
    assertEquals(0L, count2 == null ? 0L : count2.longValue());
}

@Test
public void testProcessDeletedAndNegativeSizedContainers() throws IOException {
    // Create a list of containers, including one that is deleted
    ContainerInfo omContainerInfo1 = mock(ContainerInfo.class);
    given(omContainerInfo1.containerID()).willReturn(ContainerID.valueOf(1));
    // 1.5GB
    given(omContainerInfo1.getUsedBytes()).willReturn(1500000000L);
    given(omContainerInfo1.getState()).willReturn(OPEN);
    ContainerInfo omContainerInfo2 = mock(ContainerInfo.class);
    given(omContainerInfo2.containerID()).willReturn(ContainerID.valueOf(2));
    // 2.5GB
    given(omContainerInfo2.getUsedBytes()).willReturn(2500000000L);
    given(omContainerInfo2.getState()).willReturn(CLOSED);
    ContainerInfo omContainerInfoDeleted = mock(ContainerInfo.class);
    given(omContainerInfoDeleted.containerID()).willReturn(ContainerID.valueOf(3));
    given(omContainerInfoDeleted.getUsedBytes()).willReturn(1000000000L);
    // 1GB
    given(omContainerInfoDeleted.getState()).willReturn(DELETED);
    // Create a mock container with negative size
    final ContainerInfo negativeSizeContainer = mock(ContainerInfo.class);
    given(negativeSizeContainer.containerID()).willReturn(ContainerID.valueOf(0));
    given(negativeSizeContainer.getUsedBytes()).willReturn(-1L);
    given(negativeSizeContainer.getState()).willReturn(OPEN);
    // Create a mock container with negative size and DELETE state
    final ContainerInfo negativeSizeDeletedContainer = mock(ContainerInfo.class);
    given(negativeSizeDeletedContainer.containerID()).willReturn(ContainerID.valueOf(0));
    given(negativeSizeDeletedContainer.getUsedBytes()).willReturn(-1L);
    given(negativeSizeDeletedContainer.getState()).willReturn(DELETED);
    // Create a mock container with id 1 and updated size of 1GB from 1.5GB
    final ContainerInfo validSizeContainer = mock(ContainerInfo.class);
    given(validSizeContainer.containerID()).willReturn(ContainerID.valueOf(1));
    // 1GB
    given(validSizeContainer.getUsedBytes()).willReturn(1000000000L);
    given(validSizeContainer.getState()).willReturn(CLOSED);
    // Mock getContainers method to return a list of containers including
    // both valid and invalid ones
    List<ContainerInfo> containers = new ArrayList<>();
    containers.add(omContainerInfo1);
    containers.add(omContainerInfo2);
    containers.add(omContainerInfoDeleted);
    containers.add(negativeSizeContainer);
    containers.add(negativeSizeDeletedContainer);
    containers.add(validSizeContainer);
    task.processContainers(containers);
    // Verify that only the valid containers are counted
    // Note: getEstimatedKeyCount() may be inaccurate in RocksDB, so we count actual entries
    int count = 0;
    try (org.apache.hadoop.hdds.utils.db.Table.KeyValueIterator<ContainerSizeCountKey, Long> iterator = containerCountTable.iterator()) {
        while (iterator.hasNext()) {
            iterator.next();
            count++;
        }
    }
    assertEquals(3, count);
}

/**
 * Demonstrates buffer overflow detection and async reinitialization.
 * This test shows how rapid event submission can trigger buffer overflow
 * and async reinitialization instead of blocking OM synchronization.
 */
@Test
public void testBufferOverflowAndAsyncReinitialization() throws Exception {
    // Set very small buffer capacity for easy demonstration
    OzoneConfiguration ozoneConfiguration = new OzoneConfiguration();
    ozoneConfiguration.setInt(ReconServerConfigKeys.OZONE_RECON_OM_EVENT_BUFFER_CAPACITY, 2);
    ReconTaskStatusDao reconTaskStatusDao = getDao(ReconTaskStatusDao.class);
