    assertNotNull(finalBucket);
    assertEquals(4, finalBucket.getNumOfFiles());
    assertEquals(FILE_Q_SIZE + FILE_P_SIZE + FILE_X_SIZE + FILE_Y_SIZE, finalBucket.getSizeOfFiles());
