    for (int i = 0; i <= TEST_CAPACITY; i++) {
        List<OMDBUpdateEvent> events = new ArrayList<>();
        events.add(createTestEvent("test" + i));
        OMUpdateEventBatch batch = new OMUpdateEventBatch(events, i);
