@ParameterizedTest
@ValueSource(booleans = { false, true })
void testUpgrade(boolean dryRun) throws IOException {
    initDatanode(HDDSLayoutFeature.DATANODE_SCHEMA_V3);
    final Map<KeyValueContainerData, Map<String, BlockData>> keyValueContainerBlockDataMap = genSchemaV2Containers(2);
    shutdownAllVolume();
    List<VolumeUpgradeResult> results = runCommand(dryRun, 0);
    assertNotNull(results);
    assertEquals(2, results.size());
    for (VolumeUpgradeResult result : results) {
        assertTrue(result.isSuccess());
        for (ContainerUpgradeResult cr : result.getResultMap().values()) {
            assertSame(ContainerUpgradeResult.Status.SUCCESS, cr.getStatus());
            KeyValueContainerData pre = assertInstanceOf(KeyValueContainerData.class, cr.getOriginContainerData());
            KeyValueContainerData post = assertInstanceOf(KeyValueContainerData.class, cr.getNewContainerData());
            assertEquals(SCHEMA_V2, pre.getSchemaVersion());
            assertEquals(SCHEMA_V3, post.getSchemaVersion());
            assertEquals(pre.getState(), post.getState());
            String schemaVersionKey = "schemaVersion\\s*:\\W*";
            assertThat(new File(cr.getBackupContainerFilePath())).exists().content(UTF_8).containsPattern(schemaVersionKey + SCHEMA_V2);
            assertThat(new File(cr.getNewContainerFilePath())).exists().content(UTF_8).containsPattern(schemaVersionKey + (dryRun ? SCHEMA_V2 : SCHEMA_V3));
        }
    }
    if (!dryRun) {
        checkV3MetaData(keyValueContainerBlockDataMap, results);
    }
}

/**
 * Test manual compaction of RocksDB.
 * This test creates a large number of keys, deletes them (creating tombstones),
 * and then runs manual compaction via the CLI tool.
 * It verifies the following:
 *    Compaction command executes successfully.
 *    Tombstones are removed (i.e., numDeletions in SST files is 0).
 *    Size of the db reduces after compaction.
 *    The RocksDB options remain unchanged after the compaction.
 */
@Test
public void testRocksDBManualCompaction() throws Exception {
    Table<byte[], byte[]> testTable = rdbStore.getTable(TEST_CF_NAME);
    // Create many keys
    for (int i = 0; i < NUM_KEYS; i++) {
        String key = "key" + i;
        String value = RandomStringUtils.secure().nextAlphanumeric(100);
        testTable.put(key.getBytes(StandardCharsets.UTF_8), value.getBytes(StandardCharsets.UTF_8));
    }
    rdbStore.flushDB();
    long sizeAfterKeysCreate = calculateSstFileSize(dbPath);
    // Delete all keys
    for (int i = 0; i < NUM_KEYS; i++) {
        String key = "key" + i;
        testTable.delete(key.getBytes(StandardCharsets.UTF_8));
    }
    rdbStore.flushDB();
    long sizeAfterKeysDelete = calculateSstFileSize(dbPath);
    rdbStore.close();
    DatabaseOptions optionsBeforeCompaction = readDatabaseOptions();
    // Trigger compaction of the table
    RocksDBManualCompaction compactionTool = new RocksDBManualCompaction();
    CommandLine cmd = new CommandLine(compactionTool);
    String[] args = { "--db", dbPath.toString(), "--column-family", TEST_CF_NAME };
    int exitCode = withTextFromSystemIn("y").execute(() -> cmd.execute(args));
    assertEquals(0, exitCode, "Compaction command should execute successfully");
    long sizeAfterCompaction = calculateSstFileSize(dbPath);
    System.out.printf("Size after creating keys: %d, after deleting keys: %d, after compaction: %d %n", sizeAfterKeysCreate, sizeAfterKeysDelete, sizeAfterCompaction);
    // Deletes should increase the size due to tombstones
    assertTrue(sizeAfterKeysCreate < sizeAfterKeysDelete, String.format("sizeAfterKeysCreate (%d) is not lesser than sizeAfterKeysDelete (%d), ", sizeAfterKeysCreate, sizeAfterKeysDelete));
    // Compaction should reduce the size below original
    assertTrue(sizeAfterCompaction < sizeAfterKeysCreate, String.format("sizeAfterCompaction (%d) is not lesser than sizeAfterKeysCreate (%d), ", sizeAfterCompaction, sizeAfterKeysCreate));
    // check all tombstones were removed
    List<ColumnFamilyHandle> cfHandleList = new ArrayList<>();
    List<ColumnFamilyDescriptor> cfDescList = RocksDBUtils.getColumnFamilyDescriptors(dbPath.toString());
    try (ManagedRocksDB db = ManagedRocksDB.openReadOnly(dbPath.toString(), cfDescList, cfHandleList)) {
        List<LiveFileMetaData> liveFileMetaDataList = RdbUtil.getLiveSSTFilesForCFs(db, Collections.singletonList(TEST_CF_NAME));
        for (LiveFileMetaData liveMetadata : liveFileMetaDataList) {
            assertEquals(0, liveMetadata.numDeletions(), "Tombstones found in file: " + liveMetadata.fileName());
        }
    }
    DatabaseOptions optionsAfterCompaction = readDatabaseOptions();
    optionsBeforeCompaction.assertEqualOptions(optionsAfterCompaction);
}

