    String[] args = { "local", "raftMetaConf", "-peers", "peer1|localhost:8080,peer1|localhost:8081", "-path", "/path" };
    String output = execute(args);
    assertTrue(output.contains("Found duplicated ID: peer1."));
}

@ParameterizedTest
@EnumSource(PrintableGraph.GraphType.class)
void testPrintNoGraphMessage(PrintableGraph.GraphType graphType) {
    PrintableGraph graph = new PrintableGraph(mutableGraph, graphType);
    try {
        graph.generateImage(dir.resolve(graphType.name()).toString());
    } catch (IOException e) {
        assertEquals("Graph is empty.", e.getMessage());
    }
}

@ParameterizedTest
@EnumSource(PrintableGraph.GraphType.class)
void testPrintActualGraph(PrintableGraph.GraphType graphType) throws IOException {
    Set<CompactionNode> nodes = Stream.of(new CompactionNode("fileName1", 100, "startKey1", "endKey1", "columnFamily1"), new CompactionNode("fileName2", 200, "startKey2", "endKey2", null), new CompactionNode("fileName3", 300, null, "endKey3", "columnFamily3"), new CompactionNode("fileName4", 400, "startKey4", null, "columnFamily4")).collect(Collectors.toSet());
    when(mutableGraph.nodes()).thenReturn(nodes);
    PrintableGraph graph = new PrintableGraph(mutableGraph, graphType);
    graph.generateImage(dir.resolve(graphType.name()).toString());
    assertTrue(Files.exists(dir.resolve(graphType.name())), "Graph hasn't been generated");
}
